def find_google_chrome_executable() -> Path | None:
    candidates: list[Path] = []
    if os.name == "nt":
        for root_name in ("PROGRAMFILES", "PROGRAMFILES(X86)", "LOCALAPPDATA"):
            root = os.environ.get(root_name, "").strip()
            if root:
                candidates.append(Path(root) / "Google" / "Chrome" / "Application" / "chrome.exe")
        candidates.extend(
            [
                Path.home() / "AppData" / "Local" / "Google" / "Chrome" / "Application" / "chrome.exe",
                Path("C:/Program Files/Google/Chrome/Application/chrome.exe"),
                Path("C:/Program Files (x86)/Google/Chrome/Application/chrome.exe"),
            ]
        )
    elif sys.platform == "darwin":
        candidates.append(Path("/Applications/Google Chrome.app/Contents/MacOS/Google Chrome"))
    else:
        for executable in ("google-chrome", "google-chrome-stable", "chromium", "chromium-browser"):
            resolved = shutil.which(executable)
            if resolved:
                candidates.append(Path(resolved))
    return next((path for path in candidates if path.exists()), None)


def require_google_chrome_executable() -> Path:
    chrome_path = find_google_chrome_executable()
    if chrome_path is None:
        raise RuntimeError("Google Chrome을 찾지 못했습니다. Chrome을 먼저 설치해 주세요.")
    return chrome_path


def append_naver_kin_debug_log(message: str) -> None:
    try:
        DATA_DIR.mkdir(parents=True, exist_ok=True)
        timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
        with NAVER_KIN_DEBUG_LOG_FILE.open("a", encoding="utf-8") as log_file:
            log_file.write(f"[{timestamp}] {message}\n")
    except Exception:
        pass


def put_naver_kin_action_log(result_queue: queue.Queue | None, message: str) -> None:
    """N지식인 자동화 진행 상황을 화면 로그와 디버그 파일에 동시에 남깁니다."""
    append_naver_kin_debug_log(f"action_log {message}")
    if result_queue is None:
        return
    try:
        result_queue.put(("naver_kin_auto_log", message))
    except Exception:
        pass


