def wrap_text_for_svg_static(text: str, max_chars: int, max_lines: int) -> list[str]:
    source = re.sub(r"\s+", " ", text or "").strip()
    if not source:
        return ["핵심 정보"]
    words = source.split()
    lines: list[str] = []
    current = ""
    if len(words) <= 1:
        words = list(source)
        separator = ""
    else:
        separator = " "
    for word in words:
        candidate = f"{current}{separator}{word}".strip() if current else word
        if len(candidate) <= max_chars:
            current = candidate
            continue
        if current:
            lines.append(current)
        current = word
        if len(lines) >= max_lines:
            break
    if current and len(lines) < max_lines:
        lines.append(current)
    if not lines:
        lines = [source[:max_chars]]
    if len(lines) == max_lines and len(lines[-1]) > max_chars:
        lines[-1] = lines[-1][: max(1, max_chars - 1)].rstrip() + "…"
    return lines[:max_lines]


def shorten_thumbnail_text(text: str, keyword: str = "", max_chars: int = 24) -> str:
    cleaned = re.sub(r"<[^>]+>", " ", text or "")
    cleaned = unescape(cleaned)
    cleaned = re.sub(r"[\[\]{}()<>「」『』“”\"']", " ", cleaned)
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" ,.;:·-|")
    if not cleaned:
        cleaned = keyword.strip()
    for delimiter in ("…", "·", "|", " - ", " – ", " — ", ",", ":", "?", "!"):
        if delimiter in cleaned:
            left = cleaned.split(delimiter, 1)[0].strip()
            if 4 <= len(left) <= max_chars:
                cleaned = left
                break
    for connector in (" 및 ", " 그리고 ", " 또는 "):
        if connector in cleaned:
            left = cleaned.split(connector, 1)[0].strip()
            if len(left) >= 4:
                cleaned = left
                break
    filler_patterns = (
        r"\b총정리\b",
        r"\b최신\s*소식\b",
        r"\b관련\s*포인트\b",
        r"\b알아보기\b",
        r"\b한눈에\s*보기\b",
        r"\b완벽\s*정리\b",
    )
    for pattern in filler_patterns:
        cleaned = re.sub(pattern, " ", cleaned, flags=re.I)
    cleaned = re.sub(r"\s+", " ", cleaned).strip()
    if keyword and len(cleaned) > max_chars:
        key = re.sub(r"\s+", " ", keyword).strip()
        if 4 <= len(key) <= max_chars:
            cleaned = key
    if len(cleaned) > max_chars:
        tokens = cleaned.split()
        compact = ""
        for token in tokens:
            candidate = f"{compact} {token}".strip()
            if len(candidate) > max_chars:
                break
            compact = candidate
        cleaned = compact or cleaned[:max_chars].rstrip()
    return cleaned or (keyword.strip()[:max_chars] if keyword else "핵심 정보")


def render_svg_to_png(svg_markup: str, destination: Path, size: int, failure_label: str) -> Path:
    destination.parent.mkdir(parents=True, exist_ok=True)
    if sys.platform != "darwin":
        try:
            from playwright.sync_api import sync_playwright

            with sync_playwright() as playwright:
                browser = playwright.chromium.launch(
                    executable_path=str(require_google_chrome_executable()),
                    headless=True,
                )
                try:
                    page = browser.new_page(viewport={"width": size, "height": size})
                    page.set_content(svg_markup, wait_until="load")
                    page.locator("svg").screenshot(path=str(destination), omit_background=False)
                finally:
                    browser.close()
        except Exception as exc:
            raise RuntimeError(f"{failure_label} PNG 생성에 실패했습니다.\n\n{exc}") from exc
        if not destination.exists():
            raise RuntimeError(f"{failure_label} PNG 생성 결과를 찾지 못했습니다.")
        return destination

    with tempfile.TemporaryDirectory(prefix="blog-helper-svg-render-") as temp_dir:
        temp_path = Path(temp_dir)
        svg_path = temp_path / "image.svg"
        svg_path.write_text(svg_markup, encoding="utf-8")
        result = subprocess.run(
            ["qlmanage", "-t", "-s", str(size), "-o", str(temp_path), str(svg_path)],
            capture_output=True,
            text=True,
            check=False,
        )
        rendered_path = temp_path / "image.svg.png"
        if result.returncode != 0 or not rendered_path.exists():
            detail = (result.stderr or result.stdout or "알 수 없는 오류").strip()
            raise RuntimeError(f"{failure_label} PNG 생성에 실패했습니다.\n\n{detail}")
        shutil.copyfile(rendered_path, destination)
    return destination


def create_default_thumbnail_png(settings: "WordPressSettings", title: str, destination: Path) -> Path:
    width = max(400, int(settings.thumbnail_width or 1024))
    height = max(400, int(settings.thumbnail_height or width))
    if width < 800:
        width = 1024
    if height < 800:
        height = 1024
    font_size = max(40, int(settings.thumbnail_font_size or 78))
    bg_color = thumbnail_color_value(settings.thumbnail_bg_color or "흰색")
    border_color = thumbnail_color_value(random.choice(CARDNEWS_BORDER_COLOR_PALETTE))
    text_color = thumbnail_color_value(settings.thumbnail_text_color or "검정색")
    stroke_color = thumbnail_color_value(settings.thumbnail_text_stroke_color or "없음")
    title = shorten_thumbnail_text(title, max_chars=18)
    lines = wrap_text_for_svg_static(title, max(7, width // max(1, font_size)), 3)
    line_height = font_size * 1.18
    first_y = (height / 2) - ((len(lines) - 1) * line_height / 2)
    border_width = max(18, min(width, height) // 24)
    elements = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">',
        f'<rect width="100%" height="100%" fill="{bg_color}" />',
        f'<rect x="{border_width / 2}" y="{border_width / 2}" width="{width - border_width}" height="{height - border_width}" fill="none" stroke="{border_color}" stroke-width="{border_width}" />',
    ]
    stroke_attrs = (
        f' stroke="{stroke_color}" stroke-width="{max(3, font_size // 14)}" stroke-linejoin="round" paint-order="stroke fill"'
        if stroke_color
        else ""
    )
    for index, line in enumerate(lines):
        y = first_y + (index * line_height)
        if settings.thumbnail_shadow != "없음":
            shadow_offset = 4 if settings.thumbnail_shadow == "약한 그림자" else 8
            elements.append(
                f'<text x="{(width / 2) + shadow_offset}" y="{y + shadow_offset}" text-anchor="middle" dominant-baseline="middle" '
                f'font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{font_size}" font-weight="900" fill="#000000">{escape(line)}</text>'
            )
        elements.append(
            f'<text x="{width / 2}" y="{y}" text-anchor="middle" dominant-baseline="middle" '
            f'font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{font_size}" font-weight="900" fill="{text_color}"{stroke_attrs}>{escape(line)}</text>'
        )
    elements.append("</svg>")
    return render_svg_to_png("\n".join(elements), destination, max(width, height), "기본 썸네일")


def create_default_cardnews_png(
    settings: "WordPressSettings",
    title: str,
    summary: str,
    destination: Path,
    index: int,
    total: int,
) -> Path:
    width = max(800, int(settings.cardnews_width or 1024))
    height = max(800, int(settings.cardnews_height or 1024))
    font_size = max(46, int(settings.cardnews_font_size or 78))
    summary_font_size = max(22, round(font_size * 0.44))
    bg_color = thumbnail_color_value(settings.cardnews_bg_color or "흰색")
    border_color = thumbnail_color_value(random.choice(CARDNEWS_BORDER_COLOR_PALETTE))
    text_color = thumbnail_color_value(settings.cardnews_text_color or "검정색")
    stroke_color = thumbnail_color_value(settings.cardnews_text_stroke_color or "없음")
    heading_lines = wrap_text_for_svg_static(title, max(8, width // max(1, font_size)), 3)
    summary_lines = wrap_text_for_svg_static(summary, max(14, width // max(1, summary_font_size)), 2)
    heading_line_gap = font_size * 1.18
    start_y = (height * 0.38) - ((len(heading_lines) - 1) * heading_line_gap / 2)
    summary_y = height * 0.68
    summary_line_gap = summary_font_size * 1.25
    summary_box_height = (summary_font_size * 2.8) + ((len(summary_lines) - 1) * summary_line_gap)
    elements = [
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}" viewBox="0 0 {width} {height}">',
        f'<rect width="100%" height="100%" fill="{bg_color}" />',
        f'<rect x="{width * 0.057}" y="{height * 0.057}" width="{width * 0.886}" height="{height * 0.886}" fill="none" stroke="{border_color}" stroke-width="{max(18, min(width, height) * 0.033)}" />',
        f'<text x="{width * 0.914}" y="{height * 0.11}" text-anchor="end" font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{max(22, min(width, height) * 0.027)}" font-weight="800" fill="{border_color}">{index}/{total}</text>',
    ]
    stroke_attrs = (
        f' stroke="{stroke_color}" stroke-width="{max(3, font_size // 16)}" stroke-linejoin="round" paint-order="stroke fill"'
        if stroke_color
        else ""
    )
    for line_index, line in enumerate(heading_lines):
        y = start_y + (line_index * heading_line_gap)
        if settings.cardnews_shadow != "없음":
            shadow_offset = 4 if settings.cardnews_shadow == "약한 그림자" else 9
            elements.append(
                f'<text x="{(width / 2) + shadow_offset}" y="{y + shadow_offset}" text-anchor="middle" dominant-baseline="middle" '
                f'font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{font_size}" font-weight="900" fill="#000000">{escape(line)}</text>'
            )
        elements.append(
            f'<text x="{width / 2}" y="{y}" text-anchor="middle" dominant-baseline="middle" '
            f'font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{font_size}" font-weight="900" fill="{text_color}"{stroke_attrs}>{escape(line)}</text>'
        )
    elements.append(f'<rect x="{width * 0.127}" y="{summary_y - (summary_box_height / 2)}" width="{width * 0.746}" height="{summary_box_height}" rx="{max(18, min(width, height) * 0.029)}" fill="#ffffff" opacity="0.78" />')
    for line_index, line in enumerate(summary_lines):
        y = summary_y + ((line_index - ((len(summary_lines) - 1) / 2)) * summary_line_gap)
        elements.append(
            f'<text x="{width / 2}" y="{y}" text-anchor="middle" dominant-baseline="middle" '
            f'font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" font-size="{summary_font_size}" font-weight="700" fill="#303845">{escape(line)}</text>'
        )
    elements.append(
        f'<text x="{width / 2}" y="{height * 0.9}" text-anchor="middle" font-family="Apple SD Gothic Neo, Noto Sans CJK KR, sans-serif" '
        f'font-size="{max(20, min(width, height) * 0.029)}" font-weight="800" fill="{border_color}">BLOG HELPER CARD NEWS</text>'
    )
    elements.append("</svg>")
    return render_svg_to_png("\n".join(elements), destination, max(width, height), "기본 카드뉴스")


def migrate_legacy_app_state() -> None:
    if STATE_FILE.exists():
        return
    legacy_candidates = [
        Path(tempfile.gettempdir()) / "BlogHelper" / "app_state.json",
        SCRIPT_DIR / "app_state.json",
    ]
    existing = [path for path in legacy_candidates if path.exists() and path != STATE_FILE]
    if not existing:
        return
    source = max(existing, key=lambda path: path.stat().st_mtime)
    try:
        shutil.copy2(source, STATE_FILE)
    except OSError:
        pass


migrate_legacy_app_state()

