def nonempty_text(value: str | None, fallback: str) -> str:
    value = (value or "").strip()
    return value if value else fallback


def build_keyword_focused_article_html(topic: str, keyword: str) -> str:
    safe_topic = escape(topic)
    safe_keyword = escape(keyword)
    return f"""
    <h1>{safe_keyword} 완벽 가이드</h1>
    <p><strong>{safe_keyword}</strong>를 중심으로 핵심 개념, 준비 방법, 실제 활용 포인트를 한 번에 정리했습니다.</p>
    <p>이 글은 <strong>{safe_topic}</strong>라는 큰 주제 안에서 특히 <strong>{safe_keyword}</strong>에 집중해서 이해하기 쉽게 설명합니다.</p>

    <h2>{safe_keyword}이 중요한 이유</h2>
    <p>{safe_keyword}은 검색 의도가 뚜렷하고, 실제로 정보를 찾는 사용자가 많아 블로그 글 주제로 활용하기 좋습니다.</p>

    <h2>{safe_keyword} 핵심 정리</h2>
    <ul>
      <li>{safe_keyword}의 기본 개념부터 빠르게 이해할 수 있습니다.</li>
      <li>실행 전 확인해야 할 조건과 준비 사항을 확인할 수 있습니다.</li>
      <li>자주 헷갈리는 부분을 한 번에 정리할 수 있습니다.</li>
    </ul>

    <h2>{safe_keyword} 준비 방법</h2>
    <ol>
      <li>{safe_keyword} 관련 기본 정보와 공식 안내를 먼저 확인합니다.</li>
      <li>대상 조건, 필요 서류, 신청 시기를 체크합니다.</li>
      <li>실제 신청 또는 실행 전에 예외 사항을 다시 검토합니다.</li>
    </ol>

    <h2>{safe_keyword} 자주 묻는 질문</h2>
    <h3>{safe_keyword}은 누가 확인하면 좋을까요?</h3>
    <p>{safe_keyword}이 처음인 분, 비교가 필요한 분, 빠르게 핵심만 정리하고 싶은 분에게 적합합니다.</p>
    <h3>{safe_keyword} 글을 더 좋게 만드는 방법은?</h3>
    <p>공식 자료 링크, 실제 사례, 체크리스트, 요약 표를 추가하면 훨씬 설득력 있는 글이 됩니다.</p>
    """.strip()


def render_prompt_template(template: str, topic: str, keyword: str, reference: str = "", title: str = "") -> str:
    return (
        template.replace("{topic}", topic)
        .replace("{keyword}", keyword)
        .replace("{reference}", reference)
        .replace("{title}", title)
    )


def normalize_generated_article_html(article_html: str) -> str:
    article_html = article_html.strip()
    fence_match = re.search(r"```(?:html)?\s*(.*?)```", article_html, flags=re.S | re.I)
    if fence_match:
        article_html = fence_match.group(1).strip()
    return article_html


def normalize_external_url(url: str) -> str:
    url = (url or "").strip()
    if not url:
        return ""
    if not re.match(r"^https?://", url, flags=re.I):
        url = "https://" + url
    parsed = urlparse(url)
    if parsed.scheme.lower() not in {"http", "https"} or not parsed.netloc:
        return ""
    return url


def safe_button_width(value: object) -> int:
    try:
        width = int(float(str(value).strip()))
    except (TypeError, ValueError):
        return 0
    return max(80, min(width, 1200))


def build_external_link_button_html(button_text: str, url: str, width: object = "", full_width: bool = False) -> str:
    normalized_url = normalize_external_url(url)
    if not normalized_url:
        return ""
    label = (button_text or "").strip() or "자세히 보기"
    button_width = safe_button_width(width)
    if full_width:
        wrap_style = "text-align:center;margin:30px 0;"
        link_style = (
            "display:block;width:100%;box-sizing:border-box;padding:14px 26px;border-radius:999px;"
            "background:#2563eb;color:#ffffff;text-decoration:none;font-weight:800;line-height:1.2;"
        )
    elif button_width:
        wrap_style = "text-align:center;margin:30px 0;"
        link_style = (
            f"display:inline-block;width:{button_width}px;box-sizing:border-box;padding:14px 26px;border-radius:999px;"
            "background:#2563eb;color:#ffffff;text-decoration:none;font-weight:800;line-height:1.2;"
        )
    else:
        wrap_style = "text-align:center;margin:30px 0;"
        link_style = (
            "display:inline-block;padding:14px 26px;border-radius:999px;background:#2563eb;"
            "color:#ffffff;text-decoration:none;font-weight:800;line-height:1.2;"
        )
    return (
        f"\n<!-- {CUSTOM_LINK_BUTTON_MARKER} -->\n"
        f'<p class="blog-helper-link-button-wrap" style="{wrap_style}">'
        f'<a href="{escape(normalized_url, quote=True)}" target="_blank" rel="noopener noreferrer" '
        f'style="{link_style}">'
        f"{escape(label)}"
        "</a></p>\n"
    )


def insert_html_near_top(article_html: str, html_to_insert: str) -> str:
    h1_match = re.search(r"</h1\s*>", article_html, flags=re.I)
    if h1_match:
        insert_at = h1_match.end()
        return article_html[:insert_at] + html_to_insert + article_html[insert_at:]
    return f"{html_to_insert}\n{article_html}".strip()


def insert_html_near_middle(article_html: str, html_to_insert: str) -> str:
    paragraph_matches = list(re.finditer(r"</p\s*>", article_html, flags=re.I))
    if paragraph_matches:
        insert_at = paragraph_matches[max(0, len(paragraph_matches) // 2 - 1)].end()
        return article_html[:insert_at] + html_to_insert + article_html[insert_at:]
    heading_matches = list(re.finditer(r"</h[2-4]\s*>", article_html, flags=re.I))
    if heading_matches:
        insert_at = heading_matches[len(heading_matches) // 2].end()
        return article_html[:insert_at] + html_to_insert + article_html[insert_at:]
    midpoint = max(0, len(article_html) // 2)
    return article_html[:midpoint] + html_to_insert + article_html[midpoint:]


def append_external_link_buttons(article_html: str, links: list[dict]) -> str:
    article_html = (article_html or "").strip()
    if not article_html or CUSTOM_LINK_BUTTON_MARKER in article_html:
        return article_html
    grouped_links = {position: [] for position in LINK_POSITION_OPTIONS}
    for link in links[:5]:
        link_button_html = build_external_link_button_html(
            str(link.get("button_text", "")),
            str(link.get("url", "")),
            link.get("width", ""),
            bool(link.get("full_width", False)),
        )
        if not link_button_html:
            continue
        position = str(link.get("position", "본문하단"))
        if position not in grouped_links:
            position = "본문하단"
        grouped_links[position].append(link_button_html)

    content = article_html
    top_html = "\n".join(grouped_links["본문상단"])
    middle_html = "\n".join(grouped_links["본문중간"])
    bottom_html = "\n".join(grouped_links["본문하단"])
    if top_html:
        content = insert_html_near_top(content, top_html)
    if middle_html:
        content = insert_html_near_middle(content, middle_html)
    if bottom_html:
        content = f"{content}\n{bottom_html}".strip()
    return content.strip()


def extract_title_from_article_html(article_html: str, fallback: str) -> str:
    for pattern in (r"<h1[^>]*>(.*?)</h1>", r"<title[^>]*>(.*?)</title>"):
        match = re.search(pattern, article_html, flags=re.S | re.I)
        if match:
            title = unescape(re.sub(r"<[^>]+>", " ", match.group(1)))
            title = re.sub(r"\s+", " ", title).strip()
            if title:
                return title[:120]
    plain_text = re.sub(r"<[^>]+>", " ", article_html).strip()
    first_line = next((line.strip() for line in plain_text.splitlines() if line.strip()), "")
    first_line = re.sub(r"\s+", " ", first_line)
    if 6 <= len(first_line) <= 120:
        return first_line
    return fallback


def clean_generated_title(title: str, fallback: str) -> str:
    title = normalize_generated_article_html(title)
    title = re.sub(r"<[^>]+>", " ", title)
    title = unescape(title)
    title = re.sub(r"^[#\-\*\d\.\s\"'“”‘’]+", "", title)
    title = re.sub(r"[\"'“”‘’\s]+$", "", title)
    title = re.sub(r"\s+", " ", title).strip()
    if not title:
        return fallback
    for prefix in ("제목:", "블로그 제목:", "추천 제목:"):
        if title.startswith(prefix):
            title = title[len(prefix):].strip()
    return title[:120] or fallback


def compact_naver_kin_blog_title(title: str, question_title: str, question_text: str = "") -> str:
    """지식인 원 질문 제목을 그대로 인용하지 않도록 워드프레스용 제목을 짧게 정리합니다."""
    raw_question = re.sub(r"\s+", " ", question_title or "").strip()
    title = clean_generated_title(title, derive_core_keyword(raw_question, question_text) or "지식인 답변")
    question_norm = re.sub(r"[\s\W_]+", "", raw_question).lower()
    title_norm = re.sub(r"[\s\W_]+", "", title).lower()
    too_similar = bool(question_norm and (question_norm in title_norm or title_norm in question_norm))
    too_long = len(title) > 34
    if not too_similar and not too_long:
        return title[:42].strip()

    core_source = derive_core_keyword(raw_question, question_text) or raw_question or "궁금증"
    core_source = re.sub(
        r"(입니다|인가요|일까요|될까요|하나요|하죠|주세요|알려주세요|궁금합니다|문의드립니다|질문입니다)[?.!…\s]*$",
        "",
        core_source,
    ).strip()
    core_source = re.sub(
        r"\b(어디서|어디에|어디로|어떻게|왜|언제|누가|무엇|뭐|가능한가요|가능할까요|할까요|하나요|인가요|일까요)\b",
        " ",
        core_source,
    )
    core_source = re.sub(r"(어디서|어디에|어디로|어떻게|가능한가요|가능할까요|할까요|하나요|인가요|일까요)", " ", core_source)
    core_source = re.sub(r"\s+", " ", core_source)
    core = shorten_thumbnail_text(core_source, max_chars=16) or "궁금증"
    if re.search(r"(신청|가입)$", core):
        suffix = "방법 정리"
    elif any(word in raw_question for word in ("어떻게", "방법", "하나요", "될까요", "가능")):
        suffix = "해결 방법"
    else:
        suffix = "핵심 정리"
    compact = f"{core} {suffix}".strip()
    return compact[:34].strip()


def derive_core_keyword(raw_keyword: str, context: str = "") -> str:
    """제목형 문장에서 태그 생성에 쓸 중심 키워드만 부드럽게 추출합니다."""
    keyword = " ".join((raw_keyword or "").split()).strip()
    keyword = re.sub(r"^[#\-\*\d\.\s\"'“”‘’]+", "", keyword)
    keyword = re.sub(r"[\"'“”‘’\s]+$", "", keyword)
    keyword = re.sub(r"([가-힣]{2,})(사망|별세|부고|타계|영면)$", r"\1 \2", keyword)
    if not keyword:
        return ""

    stop_phrases = (
        "총정리", "완벽정리", "한눈에", "알아보기", "정리", "가이드",
        "최신", "정보", "관련", "포인트", "추천", "후기",
    )
    cleaned = keyword
    for phrase in stop_phrases:
        cleaned = re.sub(rf"\s*{re.escape(phrase)}\s*$", "", cleaned).strip()

    modifier_words = (
        "효능", "효과", "영양", "부작용", "먹는법", "먹는 방법", "섭취",
        "가입", "신청", "조건", "방법", "기간", "서류", "가격", "일정",
        "이유", "원인", "혜택", "주의사항",
    )
    parts = cleaned.split()
    while len(parts) > 1 and parts[-1] in modifier_words:
        parts.pop()
    core = " ".join(parts).strip() or cleaned

    # 너무 짧게 잘리면 원문에서 첫 핵심 명사구를 사용합니다.
    if len(core) < 2:
        token_match = re.search(r"[가-힣A-Za-z0-9]{2,}(?:잎|계좌|적금|티켓|축제|공연|보험|대출|지원금|영양제|차|약)?", keyword)
        core = token_match.group(0) if token_match else keyword
    return core[:24].strip()


def build_focus_keyword_and_tags(topic: str, keyword: str, context: str = "") -> tuple[str, list[str]]:
    source_keyword = " ".join((keyword.strip() or topic.strip() or "블로그 키워드").split())
    primary_keyword = derive_core_keyword(source_keyword, context) or source_keyword
    combined_context = " ".join(
        re.sub(r"<[^>]+>", " ", value or "")
        for value in (topic, keyword, context)
    )
    combined_context = unescape(re.sub(r"\s+", " ", combined_context)).strip()
    primary_keyword = re.sub(
        r"([가-힣]{2,})(사망|별세|부고|타계|영면)$",
        r"\1 \2",
        primary_keyword,
    )
    compact_keyword = primary_keyword.replace(" ", "")
    lower_keyword = primary_keyword.lower()
    custom_candidates: list[str] = []
    obituary_tokens = ("사망", "별세", "부고", "타계", "영면", "빈소", "발인", "장례")
    if any(token in combined_context for token in obituary_tokens):
        role_match = re.search(
            r"(가수|배우|방송인|코미디언|개그맨|개그우먼|성우|작가|감독|선수|아나운서|정치인|기업인)\s*"
            r"([가-힣]{2,5})(?=\s*(?:사망|별세|부고|타계|영면|씨|님|,|…|\.|$))?",
            combined_context,
        )
        compact_match = re.search(
            r"(?:가수|배우|방송인|코미디언|개그맨|개그우먼|성우|작가|감독|선수|아나운서|정치인|기업인)?\s*"
            r"([가-힣]{2,5})(?:사망|별세|부고|타계|영면)",
            combined_context,
        )
        role = role_match.group(1) if role_match else ""
        person_name = role_match.group(2) if role_match else (compact_match.group(1) if compact_match else "")
        person_name = re.sub(r"^(가수|배우|방송인|코미디언|성우|작가|감독|선수)", "", person_name).strip()
        subject = person_name or re.sub(
            r"\b(가수|배우|방송인|코미디언|개그맨|개그우먼|성우|작가|감독|선수|아나운서|정치인|기업인)\b",
            "",
            primary_keyword,
        )
        subject = re.sub(r"(사망|별세|부고|타계|영면).*", "", subject).strip() or primary_keyword
        custom_candidates = [
            f"{subject} 사망",
            f"{role} {subject}".strip() if role else subject,
            f"{subject} 별세",
            f"{subject} 사망 원인",
        ]
        illness_match = re.search(
            r"([가-힣A-Za-z0-9]{2,12}(?:암|병|증후군|질환))\s*(?:투병|치료|진단)",
            combined_context,
        )
        if illness_match:
            custom_candidates.append(f"{subject} {illness_match.group(1)} 투병")
        custom_candidates.extend(
            [
                f"{subject} 빈소",
                f"{subject} 발인",
                f"{subject} 장례",
            ]
        )
        if "대한가수협회장" in combined_context:
            custom_candidates.append(f"{subject} 대한가수협회장")
        intents = []
    elif any(token in primary_keyword for token in ("계좌", "적금", "청약", "지원금", "장려금", "환급", "대출", "보험", "카드")):
        intents = ["가입조건", "신청방법", "신청기간", "나이", "서류", "혜택", "금리", "만기", "중도해지", "대상"]
    elif any(token in combined_context for token in ("효능", "효과", "영양", "건강", "혈당", "식단", "섭취", "부작용", "먹는법", "다이어트", "운동", "병원", "영양제")):
        custom_candidates = [
            f"{primary_keyword} 효과",
            f"{primary_keyword} 효능",
            f"{primary_keyword} 영양",
            f"{primary_keyword} 부작용",
            f"{primary_keyword} 먹는법",
            f"{primary_keyword} 섭취방법",
            f"{primary_keyword} 혈당",
            f"{primary_keyword} 주의사항",
        ]
        intents = []
    elif any(token in primary_keyword for token in ("티켓", "예매", "예약", "공연", "축제", "여행", "숙소", "항공권")):
        intents = ["예매방법", "가격", "후기", "취소", "할인", "일정", "준비물", "주의사항", "추천", "비교"]
    elif any(token in primary_keyword for token in ("다이어트", "혈당", "건강", "영양", "운동", "식단", "병원", "약")):
        intents = ["방법", "효과", "주의사항", "식단", "추천", "부작용", "후기", "원인", "관리법", "비교"]
    elif any(token in lower_keyword for token in ("아이폰", "갤럭시", "노트북", "맥북", "앱", "프로그램", "ai", "api")):
        intents = ["사용법", "설정", "가격", "후기", "비교", "오류", "추천", "업데이트", "다운로드", "활용법"]
    else:
        intents = ["뜻", "방법", "조건", "후기", "가격", "추천", "주의사항", "비교", "신청방법", "정리"]
    candidates = custom_candidates or [primary_keyword]
    candidates.extend(f"{primary_keyword} {intent}" for intent in intents)
    if intents and compact_keyword != primary_keyword:
        candidates.extend(f"{compact_keyword} {intent}" for intent in intents[:6])
    if not custom_candidates and topic.strip() and topic.strip() != primary_keyword:
        candidates.append(topic.strip())
    unique_tags: list[str] = []
    seen: set[str] = set()
    for candidate in candidates:
        normalized = " ".join(candidate.split()).strip()
        normalized = re.sub(r"\s+", " ", normalized)
        if not normalized or normalized in seen:
            continue
        if len(normalized) > 32:
            continue
        seen.add(normalized)
        unique_tags.append(normalized)
        if len(unique_tags) >= 8:
            break

    while intents and len(unique_tags) < 5:
        fallback_intent = intents[len(unique_tags) % len(intents)]
        filler = f"{primary_keyword} {fallback_intent}"
        if filler not in seen:
            unique_tags.append(filler)
            seen.add(filler)
        else:
            break

    return primary_keyword, unique_tags[:8]


def build_naver_kin_focus_keyword_and_tags(question_title: str, question_text: str, wordpress_title: str) -> tuple[str, list[str]]:
    """N지식인 질문형 제목을 그대로 태그로 쓰지 않고, 실제 검색 단어 위주로 정리합니다."""
    source = " ".join((wordpress_title or question_title or "").split())
    context = " ".join((question_title or "", question_text or "", wordpress_title or ""))
    source = re.sub(
        r"(어디서|어디에|어디로|어떻게|왜|언제|누가|무엇|뭐|가능한가요|가능할까요|할까요|하나요|인가요|일까요|알려주세요|궁금합니다|문의드립니다)",
        " ",
        source,
    )
    source = re.sub(r"[?？!！~…]+", " ", source)
    source = re.sub(r"\s+", " ", source).strip()
    core = derive_core_keyword(source, context) or derive_core_keyword(question_title, question_text) or source or "지식인 답변"
    core = re.sub(
        r"(해결 방법|핵심 정리|방법 정리|총정리|정리|가이드|알아보기|정보)$",
        "",
        core,
    ).strip() or core
    core = re.sub(r"\s+", " ", core)

    financial_tokens = ("계좌", "적금", "청약", "지원금", "장려금", "환급", "대출", "보험", "카드")
    health_tokens = ("효능", "효과", "영양", "혈당", "건강", "병원", "질환", "부작용", "먹는법", "섭취")
    event_tokens = ("공연", "축제", "콘서트", "티켓", "예매", "예약", "전시", "행사")
    obituary_tokens = ("사망", "별세", "부고", "타계", "영면", "빈소", "발인", "장례")
    context_compact = re.sub(r"\s+", "", context)

    if any(token in context for token in obituary_tokens):
        person = re.sub(r"(사망|별세|부고|타계|영면|이유|원인|빈소|발인|장례).*", "", core).strip() or core
        core = person
        candidates = [person, f"{person} 사망", f"{person} 별세", f"{person} 사망 이유", f"{person} 빈소", f"{person} 발인"]
    elif any(token in context for token in financial_tokens):
        candidates = [core, f"{core} 조건", f"{core} 신청", f"{core} 신청방법", f"{core} 서류", f"{core} 혜택", f"{core} 기간"]
    elif any(token in context for token in health_tokens):
        base = re.sub(r"(효능|효과|부작용|먹는법|섭취|주의사항)$", "", core).strip() or core
        candidates = [base, f"{base} 효능", f"{base} 효과", f"{base} 부작용", f"{base} 먹는법", f"{base} 주의사항"]
    elif any(token in context for token in event_tokens):
        candidates = [core, f"{core} 일정", f"{core} 예매", f"{core} 가격", f"{core} 장소", f"{core} 후기"]
    else:
        candidates = [core, f"{core} 원인", f"{core} 방법", f"{core} 해결", f"{core} 주의사항", f"{core} 확인"]

    if core.replace(" ", "") not in context_compact and len(core) > 2:
        candidates.insert(0, core)

    unique_tags: list[str] = []
    seen: set[str] = set()
    banned = ("어디서", "하나요", "인가요", "궁금", "알려", "질문", "답변", "지식인")
    question_compact = re.sub(r"[\s\W_]+", "", question_title or "").lower()
    for candidate in candidates:
        tag = " ".join(str(candidate or "").split()).strip(" ,.#")
        tag = re.sub(r"[?？!！~…]+", "", tag).strip()
        tag_compact = re.sub(r"[\s\W_]+", "", tag).lower()
        if not tag or len(tag) > 22 or any(word in tag for word in banned):
            continue
        if question_compact and tag_compact == question_compact:
            continue
        if tag in seen:
            continue
        seen.add(tag)
        unique_tags.append(tag)
        if len(unique_tags) >= 8:
            break
    return core[:22], unique_tags[:8] or [core[:22]]


def expand_keyword_from_context(keyword: str, *contexts: str) -> str:
    keyword = " ".join((keyword or "").split()).strip()
    if not keyword:
        return ""
    escaped_keyword = re.escape(keyword)
    best = keyword
    for context in contexts:
        text = re.sub(r"<[^>]+>", " ", context or "")
        text = unescape(text)
        for match in re.finditer(rf"{escaped_keyword}[가-힣A-Za-z0-9]*", text):
            candidate = " ".join(match.group(0).split()).strip()
            if len(candidate) > len(best):
                best = candidate
    return best


def ensure_focus_keyword_in_title(title: str, focus_keyword: str) -> str:
    title = (title or "").strip()
    focus_keyword = (focus_keyword or "").strip()
    if not title or not focus_keyword:
        return title
    if focus_keyword.replace(" ", "") in title.replace(" ", ""):
        return title
    return f"{focus_keyword}: {title}"


def ensure_focus_keyword_in_content(content: str, focus_keyword: str) -> str:
    content = (content or "").strip()
    focus_keyword = (focus_keyword or "").strip()
    if not content or not focus_keyword:
        return content
    compact_content = re.sub(r"\s+", "", re.sub(r"<[^>]+>", "", content))
    compact_keyword = re.sub(r"\s+", "", focus_keyword)
    if compact_keyword and compact_keyword in compact_content:
        return content
    return f"<p><strong>{escape(focus_keyword)}</strong>에 대한 핵심 내용을 정리했습니다.</p>\n{content}"


def slugify_korean_text(text: str) -> str:
    cleaned = re.sub(r"[^\w\s-]", "", text.strip().lower())
    cleaned = re.sub(r"[-\s]+", "-", cleaned).strip("-")
    return cleaned or "blog-post"


def build_meta_description(topic: str, keyword: str) -> str:
    description = (
        f"{keyword} 핵심 정보와 준비 방법, 주의사항을 빠르게 정리했습니다. "
        f"{topic} 주제 안에서 {keyword}이 왜 중요한지 한 번에 확인해 보세요."
    ).strip()
    return description[:155]


