class PromptFileStore:
    FILES = {
        "wordpress_title_prompt_template": "wordpress_title.txt",
        "wordpress_article_prompt_template": "wordpress_article.txt",
        "tistory_title_prompt_template": "tistory_title.txt",
        "tistory_article_prompt_template": "tistory_article.txt",
        "tistory_automation_prompt": "tistory_automation.txt",
        "blogspot_title_prompt_template": "blogspot_title.txt",
        "blogspot_article_prompt_template": "blogspot_article.txt",
        "naver_blog_conversion_rules": "naver_blog_conversion_rules.txt",
        "naver_kin_answer_prompt": "naver_kin_answer_prompt.txt",
    }

    @classmethod
    def load_into(cls, settings: WordPressSettings) -> WordPressSettings:
        cls._ensure_directory()
        for attribute, file_name in cls.FILES.items():
            path = PROMPT_STORAGE_DIR / file_name
            if path.exists():
                try:
                    value = path.read_text(encoding="utf-8").strip()
                except OSError:
                    value = ""
                if value:
                    setattr(settings, attribute, value)
                    continue
            cls._write_text(path, str(getattr(settings, attribute, "") or cls._default_value(attribute)))
        settings.title_prompt_template = settings.wordpress_title_prompt_template
        settings.article_prompt_template = settings.wordpress_article_prompt_template
        if not settings.prompt_sets:
            settings.prompt_sets = cls.default_prompt_sets(settings)
        settings.prompt_sets = cls.normalize_prompt_sets(settings.prompt_sets, settings)
        settings.selected_prompt_id = settings.selected_prompt_id or settings.prompt_sets[0]["id"]
        return settings

    @classmethod
    def save_values(cls, values: dict[str, str]) -> None:
        cls._ensure_directory()
        for attribute, file_name in cls.FILES.items():
            if attribute not in values:
                continue
            value = str(values.get(attribute) or "").strip()
            if not value:
                value = cls._default_value(attribute)
            cls._write_text(PROMPT_STORAGE_DIR / file_name, value)

    @classmethod
    def save_settings(cls, settings: WordPressSettings) -> None:
        cls.save_values({attribute: str(getattr(settings, attribute, "")) for attribute in cls.FILES})
        cls.save_prompt_sets(settings.prompt_sets)

    @classmethod
    def load_prompt_sets(cls, settings: WordPressSettings) -> list[dict]:
        cls._ensure_directory()
        if not PROMPT_SETS_FILE.exists():
            return cls.default_prompt_sets(settings)
        try:
            payload = json.loads(PROMPT_SETS_FILE.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            return cls.default_prompt_sets(settings)
        return cls.normalize_prompt_sets(payload if isinstance(payload, list) else [], settings)

    @classmethod
    def save_prompt_sets(cls, prompt_sets: list[dict]) -> None:
        cls._ensure_directory()
        normalized = cls.normalize_prompt_sets(prompt_sets, WordPressSettings())
        temporary_path = PROMPT_SETS_FILE.with_suffix(".json.tmp")
        temporary_path.write_text(json.dumps(normalized, ensure_ascii=False, indent=2), encoding="utf-8")
        temporary_path.replace(PROMPT_SETS_FILE)

    @classmethod
    def default_prompt_sets(cls, settings: WordPressSettings) -> list[dict]:
        return [
            {
                "id": "wordpress-default",
                "platform": "wordpress",
                "name": "기본",
                "title_prompt": settings.wordpress_title_prompt_template or DEFAULT_WORDPRESS_TITLE_PROMPT,
                "article_prompt": settings.wordpress_article_prompt_template or DEFAULT_WORDPRESS_ARTICLE_PROMPT,
            },
            {
                "id": "tistory-default",
                "platform": "tistory",
                "name": "기본",
                "title_prompt": settings.tistory_title_prompt_template or DEFAULT_TISTORY_TITLE_PROMPT,
                "article_prompt": settings.tistory_article_prompt_template or DEFAULT_TISTORY_ARTICLE_PROMPT,
            },
            {
                "id": "blogspot-default",
                "platform": "blogspot",
                "name": "기본",
                "title_prompt": settings.blogspot_title_prompt_template or DEFAULT_BLOGSPOT_TITLE_PROMPT,
                "article_prompt": settings.blogspot_article_prompt_template or DEFAULT_BLOGSPOT_ARTICLE_PROMPT,
            },
        ]

    @classmethod
    def normalize_prompt_sets(cls, prompt_sets: list[dict], settings: WordPressSettings) -> list[dict]:
        defaults = {item["platform"]: item for item in cls.default_prompt_sets(settings)}
        normalized: list[dict] = []
        seen_ids: set[str] = set()
        for item in prompt_sets or []:
            if not isinstance(item, dict):
                continue
            platform = str(item.get("platform") or "").strip()
            if platform not in ("wordpress", "tistory", "blogspot"):
                continue
            prompt_id = str(item.get("id") or f"{platform}-{int(time.time() * 1000)}").strip()
            if prompt_id in seen_ids:
                prompt_id = f"{platform}-{int(time.time() * 1000)}-{len(seen_ids)}"
            seen_ids.add(prompt_id)
            name = str(item.get("name") or "기본").strip() or "기본"
            fallback = defaults[platform]
            normalized.append(
                {
                    "id": prompt_id,
                    "platform": platform,
                    "name": name,
                    "title_prompt": str(item.get("title_prompt") or fallback["title_prompt"]).strip(),
                    "article_prompt": str(item.get("article_prompt") or fallback["article_prompt"]).strip(),
                }
            )
        platforms = {item["platform"] for item in normalized}
        for platform, default_item in defaults.items():
            if platform not in platforms:
                normalized.append(default_item)
        return normalized

    @staticmethod
    def _ensure_directory() -> None:
        PROMPT_STORAGE_DIR.mkdir(parents=True, exist_ok=True)
        PromptFileStore._ensure_desktop_shortcut()

    @staticmethod
    def _ensure_desktop_shortcut() -> None:
        try:
            if PROMPT_DIR.is_symlink():
                return
            if not PROMPT_DIR.exists():
                PROMPT_DIR.symlink_to(PROMPT_STORAGE_DIR, target_is_directory=True)
        except OSError:
            # 외부 Python의 Desktop 접근이 막혀도 실제 저장소 사용은 계속합니다.
            pass

    @staticmethod
    def _write_text(path: Path, value: str) -> None:
        temporary_path = path.with_suffix(path.suffix + ".tmp")
        temporary_path.write_text(value.rstrip() + "\n", encoding="utf-8")
        temporary_path.replace(path)

    @staticmethod
    def _default_value(attribute: str) -> str:
        return {
            "wordpress_title_prompt_template": DEFAULT_WORDPRESS_TITLE_PROMPT,
            "wordpress_article_prompt_template": DEFAULT_WORDPRESS_ARTICLE_PROMPT,
            "tistory_title_prompt_template": DEFAULT_TISTORY_TITLE_PROMPT,
            "tistory_article_prompt_template": DEFAULT_TISTORY_ARTICLE_PROMPT,
            "tistory_automation_prompt": DEFAULT_TISTORY_AUTOMATION_PROMPT,
            "blogspot_title_prompt_template": DEFAULT_BLOGSPOT_TITLE_PROMPT,
            "blogspot_article_prompt_template": DEFAULT_BLOGSPOT_ARTICLE_PROMPT,
            "naver_blog_conversion_rules": DEFAULT_NAVER_BLOG_CONVERSION_RULES,
            "naver_kin_answer_prompt": DEFAULT_NAVER_KIN_ANSWER_PROMPT,
        }[attribute]


