def find_visible_text_rect(page, patterns: list[str], min_top: int = 0, max_left_ratio: float = 1.0) -> dict | None:
    return page.evaluate(
        """
({ patterns, minTop, maxLeftRatio }) => {
  const regexes = patterns.map((pattern) => new RegExp(pattern));
  const visible = (node) => {
    if (!node) return false;
    const rect = node.getBoundingClientRect();
    const style = window.getComputedStyle(node);
    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
  };
  const textOf = (node) => (node.innerText || node.textContent || node.value || node.getAttribute?.('aria-label') || node.getAttribute?.('title') || '').replace(/\\s+/g, ' ').trim();
  const nodes = Array.from(document.querySelectorAll('button, a, label, input, [role="button"], [role="radio"], span, div, p, strong, em'))
    .filter(visible)
    .map((node) => {
      const text = textOf(node);
      const rect = node.getBoundingClientRect();
      return { node, text, rect };
    })
    .filter((item) => {
      if (!item.text) return false;
      if (item.rect.top < minTop) return false;
      if (item.rect.left > window.innerWidth * maxLeftRatio) return false;
      return regexes.some((regex) => regex.test(item.text));
    })
    .sort((a, b) => (a.rect.width * a.rect.height) - (b.rect.width * b.rect.height));
  const item = nodes[0];
  if (!item) return null;
  return {
    text: item.text,
    x: item.rect.left + item.rect.width / 2,
    y: item.rect.top + item.rect.height / 2,
    left: item.rect.left,
    top: item.rect.top,
    width: item.rect.width,
    height: item.rect.height
  };
}
""",
        {"patterns": patterns, "minTop": min_top, "maxLeftRatio": max_left_ratio},
    )


def find_naver_kin_answer_button_rect(page) -> dict | None:
    try:
        result = page.evaluate(
            """
() => {
  const visible = (node) => {
    if (!node) return false;
    const rect = node.getBoundingClientRect();
    const style = window.getComputedStyle(node);
    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
  };
  const textOf = (node) => [
      node.innerText,
      node.textContent,
      node.value,
      node.getAttribute?.('aria-label'),
      node.getAttribute?.('title')
    ].filter(Boolean).join(' ').replace(/\\s+/g, ' ').trim();
  const questionTitle = document.querySelector('h1, .title, .question-content__title, [class*="title"]');
  const questionTop = questionTitle ? questionTitle.getBoundingClientRect().top + window.scrollY : 0;
  const minDocumentTop = Math.max(600, questionTop + 250);
  const normalized = (value) => String(value || '').replace(/\\s+/g, '').trim();
  const looksBlue = (node) => {
    const style = window.getComputedStyle(node);
    const bg = style.backgroundColor || '';
    const match = bg.match(/rgba?\\((\\d+),\\s*(\\d+),\\s*(\\d+)/i);
    if (!match) return false;
    const r = Number(match[1]), g = Number(match[2]), b = Number(match[3]);
    return b > 120 && g > 60 && r < 120;
  };
  const makeRect = (node, reason) => {
    node.scrollIntoView({ block: 'center', inline: 'center' });
    const rect = node.getBoundingClientRect();
    return {
      text: textOf(node),
      reason,
      x: rect.left + rect.width / 2,
      y: rect.top + rect.height / 2,
      left: rect.left,
      top: rect.top,
      width: rect.width,
      height: rect.height
    };
  };
  const isHeaderArea = (node) => Boolean(node.closest?.('header, nav, [role="navigation"], .gnb, .lnb, #header, [class*="gnb"], [class*="navigation"]'));
  const promptRects = [];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const textNode = walker.currentNode;
    const text = normalized(textNode.nodeValue);
    if (!text.includes('정보를공유해주세요')) continue;
    const parent = textNode.parentElement;
    if (!parent || !visible(parent) || isHeaderArea(parent)) continue;
    const rect = parent.getBoundingClientRect();
    const documentTop = rect.top + window.scrollY;
    if (documentTop < minDocumentTop - 120) continue;
    promptRects.push({ node: parent, rect, documentTop, text });
  }
  for (const node of Array.from(document.querySelectorAll('section, article, div, li, p, span')).filter(visible)) {
    const text = normalized(textOf(node));
    if (!text.includes('정보를공유해주세요') || isHeaderArea(node)) continue;
    const rect = node.getBoundingClientRect();
    const documentTop = rect.top + window.scrollY;
    if (documentTop < minDocumentTop - 120) continue;
    promptRects.push({ node, rect, documentTop, text });
  }
  promptRects.sort((a, b) => a.documentTop - b.documentTop || a.rect.left - b.rect.left);
  const prompt = promptRects[0] || null;
  if (prompt) {
    const promptY = prompt.rect.top + prompt.rect.height / 2;
    const promptDocumentTop = prompt.documentTop;
    const promptLeft = prompt.rect.left;
    const answerButtons = Array.from(document.querySelectorAll('button, a, [role="button"], input, div, span'))
      .filter((node) => visible(node) && !isHeaderArea(node))
      .map((node) => {
        const clickable = node.closest?.('button, a, [role="button"], input') || node;
        const rect = clickable.getBoundingClientRect();
        const text = normalized(textOf(clickable) || textOf(node));
        const documentTop = rect.top + window.scrollY;
        const centerY = rect.top + rect.height / 2;
        return {
          node: clickable,
          rect,
          text,
          documentTop,
          centerY,
          blue: looksBlue(clickable),
          score:
            (text === '답변' ? 0 : 4) +
            (looksBlue(clickable) ? 0 : 2) +
            (rect.left > promptLeft + 120 ? 0 : 3) +
            Math.abs(centerY - promptY) / 100
        };
      })
      .filter((button) => {
        if (/답변하기|답변쓰기|질문하기|나도궁금|댓글|공유|신고|프로필|메뉴/.test(button.text)) return false;
        if (button.rect.width < 38 || button.rect.width > 260) return false;
        if (button.rect.height < 24 || button.rect.height > 110) return false;
        if (button.documentTop < promptDocumentTop - 140 || button.documentTop > promptDocumentTop + 260) return false;
        if (Math.abs(button.centerY - promptY) > 150) return false;
        if (button.rect.left < promptLeft + 80) return false;
        return button.text === '답변' || button.blue;
      })
      .sort((a, b) => a.score - b.score || b.rect.left - a.rect.left);
    if (answerButtons[0]) return makeRect(answerButtons[0].node, 'share-prompt-right-answer-button');
  }
  const isExactAnswer = (value) => String(value || '').replace(/\\s+/g, '') === '답변';
  const candidates = Array.from(document.querySelectorAll('button, a, input, [role="button"], label, div, span'))
    .filter(visible)
    .map((node) => {
      const clickable = node.closest?.('button, a, [role="button"], label') || node;
      const nodeText = textOf(node);
      const clickableText = textOf(clickable);
      const text = (nodeText + ' ' + clickableText).replace(/\\s+/g, ' ').trim();
      const rect = clickable.getBoundingClientRect();
      return {
        node: clickable,
        text,
        nodeText,
        clickableText,
        rect,
        documentTop: rect.top + window.scrollY
      };
    })
    .filter((item) => {
      if (!item.text) return false;
      const exactTexts = [item.nodeText, item.clickableText, item.text].map((text) => String(text || '').replace(/\\s+/g, ''));
      if (!exactTexts.some((normalized) => normalized === '답변')) return false;
      if (item.documentTop < minDocumentTop) return false;
      if (item.rect.width < 40 || item.rect.width > 220) return false;
      if (item.rect.height < 24 || item.rect.height > 90) return false;
      return exactTexts.some(isExactAnswer);
    })
    .sort((a, b) => {
      return a.documentTop - b.documentTop;
    });
  const item = candidates[0];
  if (item) return makeRect(item.node, 'exact-answer-button');

  const promptNodes = Array.from(document.querySelectorAll('section, article, div, li'))
    .filter(visible)
    .map((node) => {
      const rect = node.getBoundingClientRect();
      return {
        node,
        text: textOf(node).replace(/\\s+/g, ''),
        rect,
        documentTop: rect.top + window.scrollY
      };
    })
    .filter((item) => {
      if (item.documentTop < minDocumentTop) return false;
      if (!item.text.includes('정보를공유해주세요')) return false;
      if (item.rect.width < 300 || item.rect.height < 80 || item.rect.height > 520) return false;
      return true;
    })
    .sort((a, b) => a.documentTop - b.documentTop);
  for (const prompt of promptNodes) {
    const buttons = Array.from(prompt.node.querySelectorAll('button, a, [role="button"], input'))
      .filter(visible)
      .map((node) => {
        const rect = node.getBoundingClientRect();
        return {
          node,
          text: textOf(node).replace(/\\s+/g, ''),
          rect,
          score: (looksBlue(node) ? 0 : 1) + (rect.left > prompt.rect.left + prompt.rect.width * 0.55 ? 0 : 2)
        };
      })
      .filter((button) => {
        if (button.text.includes('답변하기') || button.text.includes('답변쓰기')) return false;
        if (button.text && button.text !== '답변') return false;
        if (button.rect.width < 40 || button.rect.width > 240) return false;
        if (button.rect.height < 24 || button.rect.height > 100) return false;
        return button.text === '답변' || looksBlue(button.node);
      })
      .sort((a, b) => a.score - b.score || b.rect.left - a.rect.left);
    if (buttons[0]) return makeRect(buttons[0].node, 'answer-prompt-card-button');
  }
  return null;
}
""",
        )
        if isinstance(result, dict):
            append_naver_kin_debug_log(
                "answer_rect_found "
                + json.dumps(
                    {
                        "url": page.url,
                        "text": result.get("text"),
                        "reason": result.get("reason"),
                        "x": result.get("x"),
                        "y": result.get("y"),
                        "width": result.get("width"),
                        "height": result.get("height"),
                    },
                    ensure_ascii=False,
                )
            )
        else:
            append_naver_kin_debug_log(f"answer_rect_not_found url={page.url}")
        return result
    except Exception as exc:
        append_naver_kin_debug_log(f"answer_rect_error url={getattr(page, 'url', '')} error={exc}")
        return None


def click_naver_kin_share_prompt_answer_button(page) -> bool:
    """질문 본문 아래 '정보를 공유해 주세요' 카드 오른쪽의 작은 파란 '답변' 버튼만 누릅니다."""
    try:
        clicked = bool(
            page.evaluate(
                """
() => {
  const visible = (node) => {
    if (!node) return false;
    const rect = node.getBoundingClientRect();
    const style = window.getComputedStyle(node);
    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
  };
  const textOf = (node) => [
      node.innerText,
      node.textContent,
      node.value,
      node.getAttribute?.('aria-label'),
      node.getAttribute?.('title')
    ].filter(Boolean).join(' ').replace(/\\s+/g, ' ').trim();
  const normalized = (value) => String(value || '').replace(/\\s+/g, '').trim();
  const isHeaderArea = (node) => Boolean(node?.closest?.('header, nav, [role="navigation"], .gnb, .lnb, #header, [class*="gnb"], [class*="navigation"]'));
  const questionTitle = document.querySelector('h1, .title, .question-content__title, [class*="title"]');
  const questionTop = questionTitle ? questionTitle.getBoundingClientRect().top + window.scrollY : 0;
  const minDocumentTop = Math.max(520, questionTop + 220);
  const clickNode = (node) => {
    if (!node || isHeaderArea(node)) return false;
    node.scrollIntoView({ block: 'center', inline: 'center' });
    node.focus?.();
    node.dispatchEvent(new MouseEvent('mouseover', { bubbles: true, cancelable: true, view: window }));
    node.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true, view: window }));
    node.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true, view: window }));
    node.click?.();
    node.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
    return true;
  };
  const shareSeeds = [];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const textNode = walker.currentNode;
    if (!normalized(textNode.nodeValue).includes('정보를공유해주세요')) continue;
    if (textNode.parentElement && visible(textNode.parentElement) && !isHeaderArea(textNode.parentElement)) {
      shareSeeds.push(textNode.parentElement);
    }
  }
  for (const node of Array.from(document.querySelectorAll('section, article, div, li, p, span')).filter(visible)) {
    if (normalized(textOf(node)).includes('정보를공유해주세요') && !isHeaderArea(node)) {
      shareSeeds.push(node);
    }
  }
  const cards = [];
  for (const seed of shareSeeds) {
    let current = seed;
    for (let depth = 0; current && depth < 10; depth += 1, current = current.parentElement) {
      if (!visible(current) || isHeaderArea(current)) continue;
      const rect = current.getBoundingClientRect();
      const documentTop = rect.top + window.scrollY;
      const text = normalized(textOf(current));
      if (
        text.includes('정보를공유해주세요') &&
        documentTop >= minDocumentTop - 180 &&
        rect.width >= Math.min(420, window.innerWidth * 0.42) &&
        rect.height >= 58 &&
        rect.height <= 420
      ) {
        cards.push({ node: current, rect, documentTop });
        break;
      }
    }
  }
  // 네이버가 카드 DOM을 바꾸면 버튼이 같은 부모 안에 없을 수 있어,
  // "정보를 공유해 주세요" 문구의 같은 가로선 오른쪽 영역에서 작은 답변 버튼을 직접 찾습니다.
  for (const seed of shareSeeds) {
    if (!visible(seed) || isHeaderArea(seed)) continue;
    seed.scrollIntoView({ block: 'center', inline: 'center' });
    const seedRect = seed.getBoundingClientRect();
    const seedDocumentTop = seedRect.top + window.scrollY;
    if (seedDocumentTop < minDocumentTop - 220) continue;
    const lineY = Math.max(24, Math.min(window.innerHeight - 24, seedRect.top + seedRect.height / 2));
    const pointXs = [
      window.innerWidth * 0.78,
      window.innerWidth * 0.72,
      window.innerWidth * 0.66,
      seedRect.right + 520,
      seedRect.right + 420,
      seedRect.right + 320,
      seedRect.right + 220,
    ].map((x) => Math.max(24, Math.min(window.innerWidth - 24, x)));
    for (const x of pointXs) {
      const target = document.elementFromPoint(x, lineY);
      const clickable = target?.closest?.('button, a, [role="button"], input') || target;
      if (!clickable || !visible(clickable) || isHeaderArea(clickable)) continue;
      const targetText = normalized(textOf(clickable));
      const rect = clickable.getBoundingClientRect();
      const isSmallRightButton = rect.width >= 38 && rect.width <= 240 && rect.height >= 24 && rect.height <= 110 && rect.left > seedRect.right;
      if (targetText === '답변' && isSmallRightButton) return clickNode(clickable);
      if (!targetText && isSmallRightButton) return clickNode(clickable);
    }
    const nearbyButtons = Array.from(document.querySelectorAll('button, a, [role="button"], input'))
      .filter((node) => visible(node) && !isHeaderArea(node))
      .map((node) => {
        const rect = node.getBoundingClientRect();
        const text = normalized(textOf(node));
        return {
          node,
          rect,
          text,
          score: Math.abs((rect.top + rect.height / 2) - lineY) + (rect.left > seedRect.right ? 0 : 800)
        };
      })
      .filter((item) => {
        if (item.text !== '답변') return false;
        if (item.rect.left <= seedRect.right) return false;
        if (item.rect.width < 38 || item.rect.width > 240) return false;
        if (item.rect.height < 24 || item.rect.height > 110) return false;
        if (Math.abs((item.rect.top + item.rect.height / 2) - lineY) > 170) return false;
        return true;
      })
      .sort((a, b) => a.score - b.score || b.rect.left - a.rect.left);
    if (nearbyButtons[0] && clickNode(nearbyButtons[0].node)) return true;
  }
  cards.sort((a, b) => a.documentTop - b.documentTop || b.rect.width - a.rect.width);
  for (const card of cards) {
    card.node.scrollIntoView({ block: 'center', inline: 'center' });
    const rect = card.node.getBoundingClientRect();
    const rightHalfLeft = rect.left + rect.width * 0.54;
    const exactButtons = Array.from(card.node.querySelectorAll('button, a, [role="button"], input, span, div'))
      .filter((node) => visible(node) && !isHeaderArea(node))
      .map((node) => {
        const clickable = node.closest?.('button, a, [role="button"], input') || node;
        const buttonRect = clickable.getBoundingClientRect();
        return { node: clickable, rect: buttonRect, text: normalized(textOf(clickable) || textOf(node)) };
      })
      .filter((item) => {
        if (item.text !== '답변') return false;
        if (item.rect.left < rightHalfLeft) return false;
        if (item.rect.width < 38 || item.rect.width > 220) return false;
        if (item.rect.height < 24 || item.rect.height > 110) return false;
        return true;
      })
      .sort((a, b) => b.rect.left - a.rect.left);
    if (exactButtons[0] && clickNode(exactButtons[0].node)) return true;

    const x = Math.min(window.innerWidth - 24, Math.max(rect.left + 80, rect.right - 76));
    const y = Math.min(window.innerHeight - 24, Math.max(rect.top + 24, rect.top + rect.height / 2));
    const target = document.elementFromPoint(x, y);
    const clickable = target?.closest?.('button, a, [role="button"], input') || target;
    if (clickable && !isHeaderArea(clickable)) {
      const targetText = normalized(textOf(clickable));
      if (!/답변하기|질문하기|나도궁금|프로필|공유|신고|댓글|메뉴/.test(targetText)) {
        return clickNode(clickable);
      }
    }
  }
  return false;
}
                """
            )
        )
        append_naver_kin_debug_log(f"share_prompt_answer_click clicked={clicked} url={page.url}")
        return clicked
    except Exception as exc:
        append_naver_kin_debug_log(f"share_prompt_answer_click_error url={getattr(page, 'url', '')} error={exc}")
        return False


def click_naver_kin_answer_button(page) -> bool:
    """네이버 지식인 질문 본문 아래의 작은 파란 '답변' 버튼만 직접 클릭합니다."""
    try:
        clicked = bool(
            page.evaluate(
                """
() => {
  const visible = (node) => {
    if (!node) return false;
    const rect = node.getBoundingClientRect();
    const style = window.getComputedStyle(node);
    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
  };
  const textOf = (node) => [
      node.innerText,
      node.textContent,
      node.value,
      node.getAttribute?.('aria-label'),
      node.getAttribute?.('title')
    ].filter(Boolean).join(' ').replace(/\\s+/g, ' ').trim();
  const isBad = (text) => /답변하기|답변쓰기|등록|수정|삭제|채택|보기|댓글|프로필|알림|신고|공유|목록|닫기|취소|나도궁금|질문하기/.test(String(text || '').replace(/\\s+/g, ''));
  const isAnswerText = (text) => {
    const normalized = String(text || '').replace(/\\s+/g, '');
    return normalized === '답변';
  };
  const questionTitle = document.querySelector('h1, .title, .question-content__title, [class*="title"]');
  const questionTop = questionTitle ? questionTitle.getBoundingClientRect().top + window.scrollY : 0;
  const minDocumentTop = Math.max(600, questionTop + 250);
  const normalized = (value) => String(value || '').replace(/\\s+/g, '').trim();
  const looksBlue = (node) => {
    const style = window.getComputedStyle(node);
    const bg = style.backgroundColor || '';
    const match = bg.match(/rgba?\\((\\d+),\\s*(\\d+),\\s*(\\d+)/i);
    if (!match) return false;
    const r = Number(match[1]), g = Number(match[2]), b = Number(match[3]);
    return b > 120 && g > 60 && r < 120;
  };
  const clickNode = (node) => {
    node.scrollIntoView({ block: 'center', inline: 'center' });
    node.focus?.();
    node.click?.();
    node.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
    return true;
  };
  const isHeaderArea = (node) => Boolean(node.closest?.('header, nav, [role="navigation"], .gnb, .lnb, #header, [class*="gnb"], [class*="navigation"]'));
  const promptRects = [];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const textNode = walker.currentNode;
    const text = normalized(textNode.nodeValue);
    if (!text.includes('정보를공유해주세요')) continue;
    const parent = textNode.parentElement;
    if (!parent || !visible(parent) || isHeaderArea(parent)) continue;
    const rect = parent.getBoundingClientRect();
    const documentTop = rect.top + window.scrollY;
    if (documentTop < minDocumentTop - 120) continue;
    promptRects.push({ node: parent, rect, documentTop, text });
  }
  for (const node of Array.from(document.querySelectorAll('section, article, div, li, p, span')).filter(visible)) {
    const text = normalized(textOf(node));
    if (!text.includes('정보를공유해주세요') || isHeaderArea(node)) continue;
    const rect = node.getBoundingClientRect();
    const documentTop = rect.top + window.scrollY;
    if (documentTop < minDocumentTop - 120) continue;
    promptRects.push({ node, rect, documentTop, text });
  }
  promptRects.sort((a, b) => a.documentTop - b.documentTop || a.rect.left - b.rect.left);
  const prompt = promptRects[0] || null;
  if (prompt) {
    const promptY = prompt.rect.top + prompt.rect.height / 2;
    const promptDocumentTop = prompt.documentTop;
    const promptLeft = prompt.rect.left;
    const answerButtons = Array.from(document.querySelectorAll('button, a, [role="button"], input, div, span'))
      .filter((node) => visible(node) && !isHeaderArea(node))
      .map((node) => {
        const clickable = node.closest?.('button, a, [role="button"], input') || node;
        const rect = clickable.getBoundingClientRect();
        const text = normalized(textOf(clickable) || textOf(node));
        const documentTop = rect.top + window.scrollY;
        const centerY = rect.top + rect.height / 2;
        return {
          node: clickable,
          rect,
          text,
          documentTop,
          centerY,
          blue: looksBlue(clickable),
          score:
            (text === '답변' ? 0 : 4) +
            (looksBlue(clickable) ? 0 : 2) +
            (rect.left > promptLeft + 120 ? 0 : 3) +
            Math.abs(centerY - promptY) / 100
        };
      })
      .filter((button) => {
        if (/답변하기|답변쓰기|질문하기|나도궁금|댓글|공유|신고|프로필|메뉴/.test(button.text)) return false;
        if (button.rect.width < 38 || button.rect.width > 260) return false;
        if (button.rect.height < 24 || button.rect.height > 110) return false;
        if (button.documentTop < promptDocumentTop - 140 || button.documentTop > promptDocumentTop + 260) return false;
        if (Math.abs(button.centerY - promptY) > 150) return false;
        if (button.rect.left < promptLeft + 80) return false;
        return button.text === '답변' || button.blue;
      })
      .sort((a, b) => a.score - b.score || b.rect.left - a.rect.left);
    if (answerButtons[0]) return clickNode(answerButtons[0].node);
  }
  const candidates = Array.from(document.querySelectorAll('button, a, input, [role="button"], label, div, span'))
    .filter(visible)
    .map((node) => {
      const clickable = node.closest?.('button, a, [role="button"], label, input') || node;
      const nodeText = textOf(node);
      const clickableText = textOf(clickable);
      const text = (nodeText + ' ' + clickableText).replace(/\\s+/g, ' ').trim();
      const normalizedTexts = [nodeText, clickableText, text].map((value) => String(value || '').replace(/\\s+/g, ''));
      const rect = clickable.getBoundingClientRect();
      return {
        node: clickable,
        text,
        normalizedTexts,
        rect,
        documentTop: rect.top + window.scrollY
      };
    })
    .filter((item) => {
      if (!item.text || isBad(item.text)) return false;
      if (item.documentTop < minDocumentTop) return false;
      if (item.rect.width < 40 || item.rect.width > 220) return false;
      if (item.rect.height < 24 || item.rect.height > 90) return false;
      return item.normalizedTexts.some(isAnswerText);
    })
    .sort((a, b) => {
      const priority = (item) => {
        const style = window.getComputedStyle(item.node);
        const colorHint = `${style.backgroundColor} ${style.color}`.toLowerCase();
        return /rgb\\(.*(35|45|55|65|75|85|95).*\\)/.test(colorHint) ? 0 : 1;
      };
      const byPriority = priority(a) - priority(b);
      if (byPriority !== 0) return byPriority;
      return a.documentTop - b.documentTop;
    });
  const item = candidates[0];
  if (item) return clickNode(item.node);

  const promptNodes = Array.from(document.querySelectorAll('section, article, div, li'))
    .filter(visible)
    .map((node) => {
      const rect = node.getBoundingClientRect();
      return {
        node,
        text: textOf(node).replace(/\\s+/g, ''),
        rect,
        documentTop: rect.top + window.scrollY
      };
    })
    .filter((prompt) => {
      if (prompt.documentTop < minDocumentTop) return false;
      if (!prompt.text.includes('정보를공유해주세요')) return false;
      if (prompt.rect.width < 300 || prompt.rect.height < 80 || prompt.rect.height > 520) return false;
      return true;
    })
    .sort((a, b) => a.documentTop - b.documentTop);
  for (const prompt of promptNodes) {
    const buttons = Array.from(prompt.node.querySelectorAll('button, a, [role="button"], input'))
      .filter(visible)
      .map((node) => {
        const rect = node.getBoundingClientRect();
        return {
          node,
          text: textOf(node).replace(/\\s+/g, ''),
          rect,
          score: (looksBlue(node) ? 0 : 1) + (rect.left > prompt.rect.left + prompt.rect.width * 0.55 ? 0 : 2)
        };
      })
      .filter((button) => {
        if (button.text.includes('답변하기') || button.text.includes('답변쓰기')) return false;
        if (button.text && button.text !== '답변') return false;
        if (button.rect.width < 40 || button.rect.width > 240) return false;
        if (button.rect.height < 24 || button.rect.height > 100) return false;
        return button.text === '답변' || looksBlue(button.node);
      })
      .sort((a, b) => a.score - b.score || b.rect.left - a.rect.left);
    if (buttons[0]) return clickNode(buttons[0].node);
  }
  return false;
}
                """
            )
        )
        append_naver_kin_debug_log(f"answer_direct_click clicked={clicked} url={page.url}")
        return clicked
    except Exception:
        append_naver_kin_debug_log(f"answer_direct_click_error url={getattr(page, 'url', '')}")
        return False


def find_naver_kin_register_button_rect(page) -> dict | None:
    return page.evaluate(
        """
() => {
  const visible = (node) => {
    if (!node) return false;
    const rect = node.getBoundingClientRect();
    const style = window.getComputedStyle(node);
    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
  };
  const textOf = (node) => (
    node.innerText || node.textContent || node.value ||
    node.getAttribute?.('aria-label') || node.getAttribute?.('title') || ''
  ).replace(/\\s+/g, ' ').trim();
  const disabled = (node) => {
    const cls = String(node.className || '');
    const aria = String(node.getAttribute?.('aria-disabled') || '').toLowerCase();
    return node.disabled || aria === 'true' || /disabled|inactive/.test(cls);
  };
  const candidates = Array.from(document.querySelectorAll('button, a, [role="button"], input[type="button"], input[type="submit"], div, span'))
    .filter((node) => visible(node) && !disabled(node))
    .map((node) => {
      const clickable = node.closest?.('button, a, [role="button"], input[type="button"], input[type="submit"]') || node;
      const rect = clickable.getBoundingClientRect();
      return { node: clickable, rect, text: textOf(node) || textOf(clickable) };
    })
    .filter((item) => {
      if (!/^(등록|답변등록|답변 등록|작성완료)$/.test(item.text)) return false;
      if (item.rect.top > Math.max(260, window.innerHeight * 0.38)) return false;
      return true;
    })
    .sort((a, b) => {
      const aClickable = /BUTTON|A|INPUT/.test(a.node.tagName) || a.node.getAttribute('role') === 'button';
      const bClickable = /BUTTON|A|INPUT/.test(b.node.tagName) || b.node.getAttribute('role') === 'button';
      if (aClickable !== bClickable) return aClickable ? -1 : 1;
      return b.rect.left - a.rect.left;
    });
  const item = candidates[0];
  if (!item) return null;
  item.node.scrollIntoView({ block: 'center', inline: 'center' });
  const rect = item.node.getBoundingClientRect();
  return {
    text: item.text,
    x: rect.left + rect.width / 2,
    y: rect.top + rect.height / 2,
    left: rect.left,
    top: rect.top,
    width: rect.width,
    height: rect.height
  };
}
""",
    )


def find_tistory_public_publish_button_rect(page) -> dict | None:
    return page.evaluate(
        """
() => {
  const visible = (node) => {
    if (!node) return false;
    const rect = node.getBoundingClientRect();
    const style = window.getComputedStyle(node);
    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
  };
  const textOf = (node) => (node.innerText || node.textContent || node.value || node.getAttribute?.('aria-label') || node.getAttribute?.('title') || '').replace(/\\s+/g, ' ').trim();
  const isDisabled = (node) => {
    const aria = String(node.getAttribute?.('aria-disabled') || '').toLowerCase();
    const cls = String(node.className || '');
    return node.disabled || aria === 'true' || /disabled|inactive/.test(cls);
  };
  const clickables = Array.from(document.querySelectorAll('button, a, label, [role="button"], input[type="button"], input[type="submit"], div, span'))
    .filter(visible)
    .map((node) => {
      const clickable = node.closest?.('button, a, label, [role="button"], input[type="button"], input[type="submit"]') || node;
      const rect = clickable.getBoundingClientRect();
      const style = window.getComputedStyle(clickable);
      return {
        node: clickable,
        text: textOf(clickable) || textOf(node),
        rect,
        bg: style.backgroundColor || '',
        color: style.color || '',
        disabled: isDisabled(clickable)
      };
    })
    .filter((item, index, arr) => item.rect.width > 0 && item.rect.height > 0 && arr.findIndex((other) => other.node === item.node) === index);

  const textMatches = clickables.filter((item) => {
    if (item.disabled) return false;
    if (/(취소|임시저장|저장|닫기)/.test(item.text)) return false;
    return /(공개\\s*발행|공개발행|발행하기|게시)/.test(item.text);
  });
  const darkBottomButtons = clickables.filter((item) => {
    if (item.disabled) return false;
    if (/(취소|임시저장|저장|닫기)/.test(item.text)) return false;
    const isDark = /rgb\\((0, 0, 0|17, 17, 17|20, 20, 20|34, 34, 34|40, 40, 40)/.test(item.bg);
    return isDark && item.rect.width >= 120 && item.rect.height >= 36 && item.rect.top > window.innerHeight * 0.45;
  });
  const candidates = [...textMatches, ...darkBottomButtons]
    .sort((a, b) => {
      const aExact = /^(공개\\s*발행|공개발행)$/.test(a.text) ? 0 : 1;
      const bExact = /^(공개\\s*발행|공개발행)$/.test(b.text) ? 0 : 1;
      if (aExact !== bExact) return aExact - bExact;
      return b.rect.top - a.rect.top || b.rect.width - a.rect.width;
    });
  const item = candidates[0];
  if (!item) return null;
  try { item.node.scrollIntoView({ block: 'center', inline: 'center' }); } catch (error) {}
  const rect = item.node.getBoundingClientRect();
  return {
    text: item.text,
    x: rect.left + rect.width / 2,
    y: rect.top + rect.height / 2,
    left: rect.left,
    top: rect.top,
    width: rect.width,
    height: rect.height
  };
}
"""
    )


def click_tistory_publish_now_native(page, result_queue: queue.Queue | None = None) -> bool:
    if result_queue:
        result_queue.put(("tistory_progress", "티스토리 발행일을 '예약'이 아닌 '현재'로 강제 선택 중입니다..."))
    page.wait_for_timeout(700)
    for _ in range(20):
        rect = find_visible_text_rect(page, [r"^현재$", r"현재\\s*발행", r"^즉시$", r"바로\\s*발행"], min_top=80, max_left_ratio=0.75)
        if rect:
            break
        page.wait_for_timeout(300)
    else:
        return False

    click_points = [
        (rect["x"], rect["y"]),
        (rect["left"] - 24, rect["y"]),
        (rect["left"] - 42, rect["y"]),
        (rect["left"] - 58, rect["y"]),
        (rect["left"] + 8, rect["y"]),
    ]
    clicked = False
    for _attempt in range(3):
        for x, y in click_points:
            if x < 1 or y < 1:
                continue
            page.mouse.move(x, y)
            page.mouse.down()
            page.wait_for_timeout(80)
            page.mouse.up()
            page.wait_for_timeout(260)
            clicked = True
        # 선택 상태를 확정하기 위해 현재 텍스트를 한 번 더 정확히 클릭합니다.
        page.mouse.click(rect["x"], rect["y"])
        page.wait_for_timeout(450)
    return clicked


def click_tistory_public_publish_native(page, result_queue: queue.Queue | None = None) -> bool:
    if result_queue:
        result_queue.put(("tistory_progress", "티스토리 공개발행 버튼을 실제 클릭으로 누르는 중입니다..."))
    click_tistory_publish_now_native(page, result_queue)
    page.wait_for_timeout(1200)
    for attempt in range(30):
        # 현재 선택 직후 버튼이 비활성화되어 있다가 늦게 활성화되는 경우가 있어 반복 대기합니다.
        if attempt in {6, 14, 22}:
            click_tistory_publish_now_native(page, result_queue)
            page.wait_for_timeout(500)
        rect = find_tistory_public_publish_button_rect(page)
        if not rect:
            rect = find_visible_text_rect(page, [r"^공개\\s*발행$", r"^공개발행$", r"공개\\s*발행", r"발행하기", r"게시"], min_top=120, max_left_ratio=0.98)
        if rect:
            if result_queue:
                result_queue.put(("tistory_progress", f"티스토리 '{rect.get('text') or '공개 발행'}' 버튼을 클릭합니다..."))
            page.mouse.move(rect["x"], rect["y"])
            page.wait_for_timeout(120)
            page.mouse.down()
            page.wait_for_timeout(120)
            page.mouse.up()
            page.wait_for_timeout(700)
            page.mouse.click(rect["x"], rect["y"])
            page.wait_for_timeout(1200)
            try:
                confirm_rect = find_visible_text_rect(page, [r"^확인$", r"^OK$", r"^예$", r"발행"], min_top=0, max_left_ratio=1.0)
                if confirm_rect:
                    page.mouse.click(confirm_rect["x"], confirm_rect["y"])
                    page.wait_for_timeout(800)
            except Exception:
                pass
            return True
        page.wait_for_timeout(400)
    return False


def build_naver_blog_write_url(profile: dict | None = None, fallback_url: str = "") -> str:
    url = str((profile or {}).get("write_url") or fallback_url or "").strip()
    if url:
        if not url.startswith(("http://", "https://")):
            url = "https://" + url
        return url
    blog_id = str((profile or {}).get("blog_id") or "").strip()
    blog_id = normalize_naver_blog_id(blog_id)
    if blog_id:
        return f"https://blog.naver.com/{blog_id}?Redirect=Write&"
    return "https://blog.naver.com/GoBlogWrite.naver"


def normalize_naver_blog_id(value: str) -> str:
    value = (value or "").strip()
    if not value:
        return ""
    if "blog.naver.com" in value:
        parsed = urlparse(value if value.startswith(("http://", "https://")) else f"https://{value}")
        parts = [part for part in parsed.path.split("/") if part]
        if parts:
            return parts[0].strip()
    value = value.rstrip("/").split("/")[-1]
    value = value.split("?")[0].split("#")[0]
    return value.strip()


def is_naver_logged_in_context(context) -> bool:
    try:
        for cookie in context.cookies():
            name = str(cookie.get("name") or "")
            domain = str(cookie.get("domain") or "")
            if name in {"NID_AUT", "NID_SES", "NID_JKL"} and "naver.com" in domain:
                return True
    except Exception:
        return False
    return False


def extract_naver_blog_nickname(page) -> str:
    try:
        nickname = str(
            page.evaluate(
                """() => {
                    const text = (selector) => {
                        const el = document.querySelector(selector);
                        return el && el.textContent ? el.textContent.trim() : "";
                    };
                    const attr = (selector, name) => {
                        const el = document.querySelector(selector);
                        return el ? (el.getAttribute(name) || "").trim() : "";
                    };
                    const candidates = [
                        text('#nickNameArea'),
                        text('.blog_nick'),
                        text('.nick'),
                        text('.profile_nick'),
                        text('.area_name'),
                        text('.user_nick'),
                        attr('meta[property="og:title"]', 'content'),
                        attr('meta[name="twitter:title"]', 'content'),
                        document.title || ""
                    ].filter(Boolean);
                    return candidates[0] || "";
                }"""
            )
            or ""
        ).strip()
    except Exception:
        nickname = ""
    nickname = re.sub(r"\s*[:|-]?\s*네이버\s*블로그\s*$", "", nickname).strip()
    nickname = re.sub(r"\s*-\s*NAVER\s*Blog\s*$", "", nickname, flags=re.I).strip()
    return nickname[:80]


def run_naver_blog_playwright_bootstrap(
    write_url: str,
    result_queue: queue.Queue,
    blog_id: str = "",
    login_timeout_seconds: int = 300,
) -> tuple[bool, str]:
    try:
        from playwright.sync_api import TimeoutError as PlaywrightTimeoutError
        from playwright.sync_api import sync_playwright
    except ImportError as exc:
        raise RuntimeError(
            "Playwright가 설치되어 있지 않습니다. 터미널에서 `python3 -m pip install playwright`를 실행해 주세요."
        ) from exc

    chrome_path = require_google_chrome_executable()

    NAVER_BLOG_CHROME_PROFILE_DIR.mkdir(parents=True, exist_ok=True)
    with sync_playwright() as playwright:
        context = playwright.chromium.launch_persistent_context(
            user_data_dir=str(NAVER_BLOG_CHROME_PROFILE_DIR),
            executable_path=str(chrome_path),
            headless=False,
            no_viewport=True,
            args=[
                "--disable-blink-features=AutomationControlled",
                "--disable-session-crashed-bubble",
                "--no-first-run",
                "--no-default-browser-check",
            ],
        )
        try:
            saved_state = load_naver_blog_storage_state()
            saved_cookies = saved_state.get("cookies", []) if isinstance(saved_state, dict) else []
            if saved_cookies:
                context.add_cookies(saved_cookies)
            page = context.pages[-1] if context.pages else context.new_page()
            page.set_default_timeout(20_000)
            page.set_default_navigation_timeout(60_000)
            blog_id = normalize_naver_blog_id(blog_id)
            fixed_write_url = f"https://blog.naver.com/{blog_id}?Redirect=Write&" if blog_id else write_url
            login_url = "https://nid.naver.com/nidlogin.login?mode=form&url=https://www.naver.com/"
            result_queue.put(("naver_blog_progress", "네이버 로그인창을 열고 로그인 완료를 기다립니다..."))
            page.goto(login_url, wait_until="domcontentloaded")

            deadline = time.time() + max(30, login_timeout_seconds)
            login_notice_sent = False
            while time.time() < deadline:
                active_pages = list(context.pages) or [page]
                page = active_pages[-1]
                current_url = page.url or ""
                logged_in = is_naver_logged_in_context(context) or any(
                    "nid.naver.com" not in ((candidate.url or "").lower()) and "naver.com" in ((candidate.url or "").lower())
                    for candidate in active_pages
                )
                if not logged_in:
                    if not login_notice_sent:
                        result_queue.put(("naver_blog_progress", "전용 Chrome에서 네이버 로그인을 완료해 주세요. 로그인 완료까지 기다립니다..."))
                        login_notice_sent = True
                else:
                    save_naver_blog_storage_state(context)
                    nickname = ""
                    if blog_id:
                        result_queue.put(("naver_blog_progress", "로그인 완료. 블로그 닉네임과 글쓰기 URL을 확인하는 중..."))
                        try:
                            page.goto(f"https://blog.naver.com/{blog_id}", wait_until="domcontentloaded")
                            page.wait_for_timeout(1200)
                            nickname = extract_naver_blog_nickname(page)
                        except Exception:
                            nickname = ""
                        try:
                            page.goto(fixed_write_url, wait_until="domcontentloaded")
                        except Exception:
                            pass
                    return True, {
                        "message": "네이버 로그인을 확인했고 프로필 정보를 저장했습니다.",
                        "write_url": fixed_write_url,
                        "nickname": nickname,
                        "blog_id": blog_id,
                    }
                time.sleep(1)
            raise RuntimeError("5분 안에 네이버 로그인이 확인되지 않았습니다. 전용 Chrome에서 로그인한 뒤 다시 시도해 주세요.")
        except PlaywrightTimeoutError as exc:
            raise RuntimeError(f"네이버 블로그 화면 응답 시간이 초과되었습니다: {exc}") from exc
        finally:
            save_naver_blog_storage_state(context)
            context.close()


def run_naver_kin_playwright_bootstrap(
    question_list_url: str,
    sort_mode: str,
    result_queue: queue.Queue,
) -> tuple[bool, dict | str]:
    try:
        from playwright.sync_api import sync_playwright
    except ImportError as exc:
        raise RuntimeError(
            "Playwright가 설치되어 있지 않습니다. 터미널에서 `python3 -m pip install playwright`를 실행해 주세요."
        ) from exc

    chrome_path = require_google_chrome_executable()

    target_url = (question_list_url or NAVER_KIN_QUESTION_LIST_URL).strip() or NAVER_KIN_QUESTION_LIST_URL
    NAVER_BLOG_CHROME_PROFILE_DIR.mkdir(parents=True, exist_ok=True)

    def extract_question_body(detail_page) -> str:
        selectors = (
            ".questionDetail",
            "div.questionDetail",
            ".c-heading__content",
            "div.c-heading__content",
            ".end_question .questionDetail",
            ".qna_detail_question",
            ".question-content",
            "div[class*='QuestionContent']",
            "div[class*='question_content']",
            "div[class*='questionText']",
            "div.se-main-container",
            "div#content .question",
        )
        for selector in selectors:
            try:
                locator = detail_page.locator(selector).first
                if locator.count() <= 0:
                    continue
                text = re.sub(r"\s+", " ", locator.inner_text(timeout=1200) or "").strip()
                if len(text) >= 20:
                    return text[:3500]
            except Exception:
                continue
        try:
            text = detail_page.evaluate(
                """
                () => {
                  const selectors = [
                    '[class*="question"]',
                    '[class*="Question"]',
                    '[class*="c-heading"]',
                    '[class*="end_question"]',
                    '[id*="question"]'
                  ];
                  const candidates = [];
                  for (const selector of selectors) {
                    for (const element of document.querySelectorAll(selector)) {
                      const value = (element.innerText || '').replace(/\\s+/g, ' ').trim();
                      if (value.length >= 20 && value.length <= 5000) candidates.push(value);
                    }
                  }
                  candidates.sort((a, b) => b.length - a.length);
                  return candidates[0] || '';
                }
                """
            )
            return re.sub(r"\s+", " ", str(text or "")).strip()[:3500]
        except Exception:
            return ""

    def question_has_attached_image(detail_page) -> bool:
        try:
            return bool(detail_page.evaluate(
                """
                () => {
                  const visible = (node) => {
                    if (!node) return false;
                    const rect = node.getBoundingClientRect();
                    const style = window.getComputedStyle(node);
                    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
                  };
                  const containers = [
                    '.questionDetail',
                    '.c-heading__content',
                    '.end_question',
                    '.qna_detail_question',
                    '.question-content',
                    '[class*="QuestionContent"]',
                    '[class*="question_content"]',
                    '[class*="questionText"]',
                    'div.se-main-container',
                    'div#content .question'
                  ];
                  const roots = containers
                    .flatMap((selector) => Array.from(document.querySelectorAll(selector)))
                    .filter(visible);
                  const scope = roots.length ? roots : [document.body];
                  for (const root of scope) {
                    const images = Array.from(root.querySelectorAll('img')).filter(visible);
                    for (const img of images) {
                      const rect = img.getBoundingClientRect();
                      const src = String(img.currentSrc || img.src || '').toLowerCase();
                      const alt = String(img.alt || '').toLowerCase();
                      if (rect.width < 70 || rect.height < 45) continue;
                      if (/profile|avatar|icon|sprite|emoji|emoticon|logo|blank|btn|badge/.test(src + ' ' + alt)) continue;
                      return true;
                    }
                    const links = Array.from(root.querySelectorAll('a[href]')).map((node) => String(node.href || '').toLowerCase());
                    if (links.some((href) => /\\.(png|jpe?g|gif|webp)(\\?|#|$)/.test(href))) return true;
                  }
                  return false;
                }
                """
            ))
        except Exception:
            return False

    def extract_detail_title(detail_page) -> str:
        for selector in ("h1", ".title", ".questionTitle", ".c-heading__title", "title"):
            try:
                if selector == "title":
                    text = detail_page.title()
                else:
                    text = detail_page.locator(selector).first.inner_text(timeout=800)
                text = re.sub(r"\s+", " ", text or "").strip()
                text = re.sub(r"\s*:\s*네이버 지식iN.*$", "", text)
                if len(text) >= 4:
                    return text[:160]
            except Exception:
                continue
        return ""

    with sync_playwright() as playwright:
        context = playwright.chromium.launch_persistent_context(
            user_data_dir=str(NAVER_BLOG_CHROME_PROFILE_DIR),
            executable_path=str(chrome_path),
            headless=False,
            no_viewport=True,
            args=[
                "--disable-blink-features=AutomationControlled",
                "--disable-session-crashed-bubble",
                "--no-first-run",
                "--no-default-browser-check",
            ],
        )
        try:
            saved_state = load_naver_blog_storage_state()
            saved_cookies = saved_state.get("cookies", []) if isinstance(saved_state, dict) else []
            if saved_cookies:
                try:
                    context.add_cookies(saved_cookies)
                except Exception:
                    pass
            page = context.pages[-1] if context.pages else context.new_page()
            page.set_default_timeout(12_000)
            page.set_default_navigation_timeout(45_000)
            result_queue.put(("naver_kin_progress", "네이버 지식인 질문 목록으로 이동 중입니다..."))
            page.goto(target_url, wait_until="domcontentloaded")
            page.wait_for_timeout(1400)

            if sort_mode == "최신순":
                result_queue.put(("naver_kin_progress", "최신순 정렬 버튼을 찾는 중입니다..."))
                for selector in (
                    "a:has-text('최신순')",
                    "button:has-text('최신순')",
                    "text=최신순",
                ):
                    try:
                        page.locator(selector).first.click(timeout=1600)
                        page.wait_for_timeout(1000)
                        break
                    except Exception:
                        continue

            questions: list[dict] = []
            seen_urls: set[str] = set()
            for selector in (
                "a[href*='questionId=']",
                "a[href*='/qna/detail.naver']",
                "a[href*='kin.naver.com/qna/detail']",
            ):
                try:
                    anchors = page.locator(selector)
                    count = min(anchors.count(), 20)
                    for index in range(count):
                        anchor = anchors.nth(index)
                        title = re.sub(r"\s+", " ", anchor.inner_text(timeout=800) or "").strip()
                        href = (anchor.get_attribute("href") or "").strip()
                        if not title or not href:
                            continue
                        url = urljoin(page.url, href)
                        if "questionList.naver" in url:
                            continue
                        if url in seen_urls:
                            continue
                        seen_urls.add(url)
                        questions.append({"title": title[:160], "url": url, "question_text": ""})
                        if len(questions) >= 10:
                            break
                    if questions:
                        break
                except Exception:
                    continue

            if questions:
                result_queue.put(("naver_kin_progress", f"질문 상세 페이지 {len(questions)}개의 본문을 수집하는 중입니다..."))
                detail_page = context.new_page()
                detail_page.set_default_timeout(8_000)
                detail_page.set_default_navigation_timeout(30_000)
                try:
                    for question_index, question in enumerate(questions, start=1):
                        url = str(question.get("url") or "")
                        if not url:
                            continue
                        try:
                            result_queue.put(("naver_kin_progress", f"{question_index}/{len(questions)} 질문 본문 수집 중..."))
                            detail_page.goto(url, wait_until="domcontentloaded")
                            detail_page.wait_for_timeout(900)
                            current_detail_url = str(detail_page.url or "").lower()
                            if "/qna/detail.naver" not in current_detail_url and "docid=" not in current_detail_url and "questionid=" not in current_detail_url:
                                question["stale"] = True
                                question["skip_reason"] = "질문 상세 URL이 네이버 홈/목록으로 이동되어 자동화 대상에서 제외됩니다."
                                question["detail_error"] = f"redirected_to={detail_page.url}"
                                continue
                            detail_title = extract_detail_title(detail_page)
                            if detail_title and len(detail_title) > len(str(question.get("title") or "")):
                                question["title"] = detail_title[:160]
                            if question_has_attached_image(detail_page):
                                question["has_image"] = True
                                question["skip_reason"] = "이미지 첨부 질문은 현재 이미지 분석 대상에서 제외됩니다."
                                continue
                            question["question_text"] = extract_question_body(detail_page)
                        except Exception as exc:
                            question["question_text"] = ""
                            question["detail_error"] = str(exc)[:180]
                finally:
                    try:
                        detail_page.close()
                    except Exception:
                        pass

            image_skipped_count = sum(1 for question in questions if question.get("has_image"))
            if image_skipped_count:
                result_queue.put(("naver_kin_progress", f"이미지 첨부 질문 {image_skipped_count}개는 자동화 대상에서 제외했습니다."))
                questions = [question for question in questions if not question.get("has_image")]
            stale_count = sum(1 for question in questions if question.get("stale"))
            if stale_count:
                result_queue.put(("naver_kin_progress", f"홈/목록으로 이동된 질문 {stale_count}개는 자동화 대상에서 제외했습니다."))
                questions = [question for question in questions if not question.get("stale")]

            save_naver_blog_storage_state(context)
            return True, {
                "message": "N지식인 질문 목록 접근 뼈대가 준비되었습니다.",
                "current_url": page.url,
                "sort_mode": sort_mode,
                "questions": questions,
            }
        finally:
            try:
                save_naver_blog_storage_state(context)
            except Exception:
                pass
            context.close()


def run_naver_kin_answer_playwright(
    question_url: str,
    answer_text: str,
    result_queue: queue.Queue,
    login_timeout_seconds: int = 300,
    post_submit_hold_seconds: int = 600,
    question_title: str = "",
    preflight_only: bool = False,
) -> tuple[bool, str]:
    try:
        from playwright.sync_api import TimeoutError as PlaywrightTimeoutError
        from playwright.sync_api import sync_playwright
    except ImportError as exc:
        raise RuntimeError(
            "Playwright가 설치되어 있지 않습니다. 터미널에서 `python3 -m pip install playwright`를 실행해 주세요."
        ) from exc

    chrome_path = require_google_chrome_executable()
    if not question_url:
        raise RuntimeError("지식인 질문 URL이 비어 있습니다.")
    if not answer_text.strip():
        raise RuntimeError("지식인 답변 내용이 비어 있습니다.")

    def is_naver_kin_list_url(url: str) -> bool:
        lowered = str(url or "").lower()
        return "kin.naver.com/qna/questionlist" in lowered or "/qna/questionlist.naver" in lowered

    def is_naver_kin_detail_url(url: str) -> bool:
        lowered = str(url or "").lower()
        return "/qna/detail.naver" in lowered or "docid=" in lowered or "questionid=" in lowered

    def has_question_detail_content(target_page) -> bool:
        """URL 문자열이 아니라 실제 질문 상세 본문이 렌더링됐는지 확인합니다."""
        try:
            return bool(
                target_page.evaluate(
                    """
() => {
  const text = (document.body?.innerText || '').replace(/\\s+/g, ' ').trim();
  const url = String(location.href || '').toLowerCase();
  const path = String(location.pathname || '').toLowerCase();
  const isDetailUrl = /\\/qna\\/detail\\.naver/.test(path) || /docid=|questionid=/.test(url);
  if (!isDetailUrl) return false;
  const isHomeOrList =
    path === '/' ||
    /\\/qna\\/questionlist\\.naver/.test(path) ||
    text.includes('답변을 기다리는 질문') ||
    text.includes('답변을 기다리는 관심질문');
  if (isHomeOrList) return false;
  const questionContainers = [
    'h1',
    '.questionDetail',
    '.c-heading__content',
    '.c-heading__title',
    '.end_question',
    '.qna_detail_question',
    '.question-content',
    '[class*="QuestionContent"]',
    '[class*="question_content"]',
    '[class*="questionText"]'
  ];
  const hasQuestionContainer = questionContainers.some((selector) => {
    const node = document.querySelector(selector);
    return Boolean(node && String(node.innerText || node.textContent || '').replace(/\\s+/g, '').length >= 4);
  });
  const hasQuestionTitle =
    Boolean(document.querySelector('h1')) ||
    /(^|\\s)Q\\./.test(text) ||
    text.includes('나도 궁금해요') ||
    text.includes('나도궁금해요') ||
    text.includes('조회수') ||
    text.includes('비공개');
  return hasQuestionContainer || hasQuestionTitle;
}
                    """
                )
            )
        except Exception as exc:
            append_naver_kin_debug_log(f"detail_content_check_error url={getattr(target_page, 'url', '')} error={exc}")
            return False

    def wait_for_question_detail_content(target_page, timeout_seconds: int = 8) -> bool:
        deadline = time.time() + max(2, int(timeout_seconds or 8))
        while time.time() < deadline:
            if has_question_detail_content(target_page):
                return True
            try:
                target_page.wait_for_timeout(650)
            except Exception:
                time.sleep(0.65)
        return has_question_detail_content(target_page)

    def open_question_detail_from_list(target_page, expected_title: str = "") -> bool:
        expected = re.sub(r"\s+", "", expected_title or "").strip()
        try:
            found_href = target_page.evaluate(
                """
({ expected }) => {
  const normalize = (value) => String(value || '').replace(/\\s+/g, '').trim();
  const visible = (node) => {
    if (!node) return false;
    const rect = node.getBoundingClientRect();
    const style = window.getComputedStyle(node);
    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
  };
  const isDetailHref = (href) => /\\/qna\\/detail\\.naver|docId=|questionId=/i.test(String(href || ''));
  const anchors = Array.from(document.querySelectorAll('a[href]'))
    .filter((node) => visible(node) && isDetailHref(node.href))
    .map((node) => ({
      href: node.href,
      text: normalize(node.innerText || node.textContent || node.getAttribute('title') || ''),
      top: node.getBoundingClientRect().top + window.scrollY
    }))
    .filter((item) => item.href);
  if (!anchors.length) return '';
  if (expected) {
    const exact = anchors.find((item) => item.text && (item.text.includes(expected) || expected.includes(item.text)));
    if (exact) return exact.href;
  }
  anchors.sort((a, b) => a.top - b.top);
  return anchors[0].href || '';
}
                """,
                {"expected": expected},
            )
        except Exception:
            found_href = ""
        if not found_href:
            return False
        try:
            target_page.goto(str(found_href), wait_until="domcontentloaded")
            target_page.wait_for_timeout(1400)
            return is_naver_kin_detail_url(target_page.url) and wait_for_question_detail_content(target_page, 5)
        except Exception:
            pass
        return False

    def click_question_detail_from_list(target_page, expected_title: str = "") -> bool:
        expected = re.sub(r"\s+", "", expected_title or "").strip()
        try:
            clicked = target_page.evaluate(
                """
({ expected }) => {
  const normalize = (value) => String(value || '').replace(/\\s+/g, '').trim();
  const visible = (node) => {
    if (!node) return false;
    const rect = node.getBoundingClientRect();
    const style = window.getComputedStyle(node);
    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
  };
  const badText = /질문하기|답변하기|프로필|로그아웃|인기태그|전체|교육|학문|추천분야|최신순|답변적은순/;
  const nodes = Array.from(document.querySelectorAll('a, [role="link"], .title, .subject, li, div'))
    .filter(visible)
    .map((node) => {
      const text = normalize(node.innerText || node.textContent || node.getAttribute?.('title') || '');
      const rect = node.getBoundingClientRect();
      const clickable = node.closest?.('a[href], [role="link"], li, div') || node;
      return { node: clickable, text, top: rect.top + window.scrollY, width: rect.width, height: rect.height };
    })
    .filter((item) => item.text && item.height > 12 && item.height < 180 && item.width > 80 && !badText.test(item.text));
  let target = null;
  if (expected) {
    target = nodes.find((item) => item.text.includes(expected) || expected.includes(item.text));
  }
  if (!target) {
    target = nodes
      .filter((item) => item.text.length >= 8 && item.top > 300)
      .sort((a, b) => a.top - b.top)[0] || null;
  }
  if (!target) return false;
  target.node.scrollIntoView({ block: 'center', inline: 'center' });
  target.node.click?.();
  target.node.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true, view: window }));
  return true;
}
                """,
                {"expected": expected},
            )
        except Exception:
            clicked = False
        if not clicked:
            return False
        try:
            target_page.wait_for_load_state("domcontentloaded", timeout=8000)
        except Exception:
            pass
        target_page.wait_for_timeout(1600)
        return is_naver_kin_detail_url(target_page.url) and wait_for_question_detail_content(target_page, 5)

    def ensure_question_detail_page(target_page, expected_title: str = "") -> None:
        current_url = target_page.url or ""
        if is_naver_kin_detail_url(current_url) and wait_for_question_detail_content(target_page, 6):
            return
        if is_naver_kin_detail_url(current_url):
            put_naver_kin_action_log(
                result_queue,
                f"질문 상세 URL처럼 보이지만 실제 상세 본문/답변 카드가 확인되지 않았습니다. 현재 URL: {current_url}",
            )
        if is_naver_kin_list_url(current_url):
            result_queue.put(("naver_kin_auto_progress", "목록 페이지가 열려 있어 선택한 질문 상세페이지로 다시 이동합니다..."))
            if open_question_detail_from_list(target_page, expected_title):
                return
            if click_question_detail_from_list(target_page, expected_title):
                return
        raise RuntimeError(
            "지식인 질문 상세 본문을 확인하지 못했습니다. 네이버가 목록/홈으로 이동시켰거나 질문이 사라졌을 수 있습니다. 질문 목록을 다시 수집한 뒤 실행해 주세요."
        )

    def click_first_available(target_page, selectors: tuple[str, ...], timeout: int = 1600) -> bool:
        for selector in selectors:
            try:
                locator = target_page.locator(selector).first
                locator.scroll_into_view_if_needed(timeout=timeout)
                locator.click(timeout=timeout)
                target_page.wait_for_timeout(700)
                return True
            except Exception:
                continue
        return False

    def open_answer_editor(target_page) -> bool:
        if not has_question_detail_content(target_page):
            put_naver_kin_action_log(
                result_queue,
                f"현재 화면이 질문 상세 본문이 아니어서 답변 버튼 클릭을 중단했습니다. 현재 URL: {target_page.url}",
            )
            return False
        put_naver_kin_action_log(result_queue, "지식인 상세페이지에서 본문 아래 '정보를 공유해 주세요' 카드의 답변 버튼을 찾기 시작했습니다.")
        for step in range(10):
            try:
                if step == 0:
                    target_page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
                else:
                    target_page.mouse.wheel(0, 1000)
                target_page.wait_for_timeout(750)
            except Exception:
                pass
            put_naver_kin_action_log(result_queue, f"{step + 1}번째 시도: 본문 아래 작은 파란 '답변' 버튼을 찾는 중입니다.")
            if click_naver_kin_share_prompt_answer_button(target_page):
                put_naver_kin_action_log(result_queue, "본문 아래 '정보를 공유해 주세요' 카드 오른쪽의 답변 버튼을 클릭했습니다.")
                target_page.wait_for_timeout(1400)
                return True
            if click_naver_kin_answer_button(target_page):
                put_naver_kin_action_log(result_queue, "보조 탐색으로 본문 아래 답변 버튼을 클릭했습니다.")
                target_page.wait_for_timeout(1400)
                return True
            try:
                rect = find_naver_kin_answer_button_rect(target_page)
            except Exception:
                rect = None
            if rect:
                try:
                    put_naver_kin_action_log(
                        result_queue,
                        f"좌표 보정으로 답변 버튼 클릭을 시도했습니다. 위치=({round(rect['x'])}, {round(rect['y'])})",
                    )
                    target_page.mouse.click(rect["x"], rect["y"])
                    target_page.wait_for_timeout(900)
                    return True
                except Exception:
                    put_naver_kin_action_log(result_queue, "좌표 보정 클릭에 실패해 다음 위치를 다시 확인합니다.")
                    continue
        try:
            target_page.evaluate("window.scrollTo(0, document.body.scrollHeight)")
            target_page.wait_for_timeout(900)
            put_naver_kin_action_log(result_queue, "마지막 보정: 페이지 맨 아래에서 답변 버튼을 다시 찾습니다.")
            if click_naver_kin_share_prompt_answer_button(target_page):
                put_naver_kin_action_log(result_queue, "마지막 보정에서 본문 아래 답변 버튼을 클릭했습니다.")
                target_page.wait_for_timeout(1400)
                return True
            if click_naver_kin_answer_button(target_page):
                put_naver_kin_action_log(result_queue, "마지막 보조 탐색으로 답변 버튼을 클릭했습니다.")
                target_page.wait_for_timeout(1400)
                return True
            rect = find_naver_kin_answer_button_rect(target_page)
            if rect:
                put_naver_kin_action_log(
                    result_queue,
                    f"마지막 좌표 보정으로 답변 버튼 클릭을 시도했습니다. 위치=({round(rect['x'])}, {round(rect['y'])})",
                )
                target_page.mouse.click(rect["x"], rect["y"])
                target_page.wait_for_timeout(900)
                return True
        except Exception:
            pass
        put_naver_kin_action_log(result_queue, "답변 버튼 클릭 실패: 본문 아래 답변 카드 또는 파란 답변 버튼을 찾지 못했습니다.")
        return False

    def frame_has_answer_editor(frame) -> bool:
        try:
            return bool(frame.evaluate(
                """
                () => {
                  const bodyText = (document.body?.innerText || '').replace(/\\s+/g, ' ');
                  if (bodyText.includes('정보를 공유해 주세요') || bodyText.includes('답변 작성 시')) return true;
                  const selectors = [
                    '.se_editable[contenteditable="true"]',
                    '.se-editable[contenteditable="true"]',
                    '.se-component-content [contenteditable="true"]',
                    '.se-module-text [contenteditable="true"]',
                    '[contenteditable="true"]',
                    'textarea[placeholder*="답변"]'
                  ];
                  return selectors.some((selector) => document.querySelector(selector));
                }
                """
            ))
        except Exception:
            return False

    def page_has_answer_editor(target_page) -> bool:
        for frame in [target_page, *target_page.frames]:
            if frame_has_answer_editor(frame):
                return True
        return False

    def frame_has_editable_answer_editor(frame) -> bool:
        try:
            return bool(frame.evaluate(
                """
                () => {
                  const visible = (node) => {
                    if (!node) return false;
                    const rect = node.getBoundingClientRect();
                    const style = window.getComputedStyle(node);
                    return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
                  };
                  const selectors = [
                    '.se_editable[contenteditable="true"]',
                    '.se-editable[contenteditable="true"]',
                    '.se-component-content [contenteditable="true"]',
                    '.se-module-text [contenteditable="true"]',
                    '.se-text-paragraph[contenteditable="true"]',
                    '[contenteditable="true"]',
                    'textarea[placeholder*="답변"]',
                    'textarea[name*="answer"]',
                    'textarea'
                  ];
                  return selectors.some((selector) => Array.from(document.querySelectorAll(selector)).some(visible));
                }
                """
            ))
        except Exception:
            return False

    def page_has_editable_answer_editor(target_page) -> bool:
        for frame in [target_page, *target_page.frames]:
            if frame_has_editable_answer_editor(frame):
                return True
        return False

    def select_answer_editor_page(context, fallback_page):
        if page_has_answer_editor(fallback_page):
            return fallback_page
        for candidate in reversed(context.pages):
            try:
                if page_has_answer_editor(candidate):
                    return candidate
            except Exception:
                continue
        return fallback_page

    def wait_for_answer_editor(context, fallback_page, timeout_seconds: int = 35):
        deadline = time.time() + max(10, int(timeout_seconds or 35))
        current_page = fallback_page
        last_notice = 0.0
        while time.time() < deadline:
            current_page = select_answer_editor_page(context, current_page)
            if page_has_editable_answer_editor(current_page):
                return current_page
            now = time.time()
            if page_has_answer_editor(current_page) and now - last_notice >= 5:
                result_queue.put(("naver_kin_auto_progress", "답변 에디터 입력 영역이 뜰 때까지 기다리는 중입니다..."))
                last_notice = now
            try:
                current_page.wait_for_timeout(800)
            except Exception:
                time.sleep(0.8)
        return select_answer_editor_page(context, current_page)

    def fill_editor(target_page, value: str) -> bool:
        selectors = (
            ".se_editable[contenteditable='true']",
            ".se-editable[contenteditable='true']",
            ".se-component-content [contenteditable='true']",
            ".se-module-text [contenteditable='true']",
            ".se-text-paragraph[contenteditable='true']",
            "[contenteditable='true']",
            "textarea[placeholder*='답변']",
            "textarea[name*='answer']",
            "textarea",
            ".se-placeholder",
            ".se-section-text",
            ".se-module-text",
            ".se-component-content",
            ".se-text-paragraph",
            ".se-editable",
            "body[contenteditable='true']",
        )
        url_sample_match = re.search(r"https?://[^\s<>'\"]+", value)
        sample_text = (
            re.sub(r"\s+", " ", url_sample_match.group(0)[:80]).strip()
            if url_sample_match
            else re.sub(r"\s+", " ", value[:24]).strip()
        )
        normalized_value = re.sub(r"\s+", " ", value).strip()
        paste_used = False

        def set_system_clipboard_text(text: str) -> bool:
            try:
                command = (
                    ["powershell.exe", "-NoProfile", "-NonInteractive", "-Command", "Set-Clipboard"]
                    if os.name == "nt"
                    else ["pbcopy"]
                )
                subprocess.run(command, input=text, text=True, check=True, timeout=5)
                return True
            except Exception:
                return False

        def focus_editor_with_js(frame) -> bool:
            try:
                return bool(frame.evaluate(
                    """
                    () => {
                      const visible = (node) => {
                        if (!node) return false;
                        const rect = node.getBoundingClientRect();
                        const style = window.getComputedStyle(node);
                        return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
                      };
                      const selectors = [
                        '.se_editable[contenteditable="true"]',
                        '.se-editable[contenteditable="true"]',
                        '.se-component-content [contenteditable="true"]',
                        '.se-module-text [contenteditable="true"]',
                        '.se-text-paragraph[contenteditable="true"]',
                        '[contenteditable="true"]',
                        'textarea[placeholder*="답변"]',
                        'textarea',
                        'body[contenteditable="true"]'
                      ];
                      for (const selector of selectors) {
                        const target = Array.from(document.querySelectorAll(selector)).find(visible);
                        if (!target) continue;
                        target.scrollIntoView({ block: 'center', inline: 'center' });
                        target.focus();
                        target.click?.();
                        return true;
                      }
                      return false;
                    }
                    """
                ))
            except Exception:
                return False

        def paste_with_system_clipboard(frame) -> bool:
            nonlocal paste_used
            if paste_used:
                return False
            if not focus_editor_with_js(frame):
                return False
            if not set_system_clipboard_text(value):
                return False
            try:
                target_page.wait_for_timeout(250)
                target_page.keyboard.press("Meta+A")
                target_page.wait_for_timeout(120)
                target_page.keyboard.press("Backspace")
                target_page.wait_for_timeout(180)
                paste_used = True
                target_page.keyboard.press("Meta+V")
                frame.wait_for_timeout(2200)
                return editor_contains_inserted_text(frame)
            except Exception:
                return False

        def insert_with_keyboard(frame) -> bool:
            if not focus_editor_with_js(frame):
                return False
            try:
                target_page.keyboard.press("Meta+A")
                target_page.keyboard.press("Backspace")
                target_page.keyboard.insert_text(value)
                frame.wait_for_timeout(900)
                return editor_contains_inserted_text(frame)
            except Exception:
                return False

        def try_insert_with_js(frame) -> bool:
            try:
                return bool(frame.evaluate(
                    """
                    (text) => {
                      const visible = (node) => {
                        if (!node) return false;
                        const rect = node.getBoundingClientRect();
                        const style = window.getComputedStyle(node);
                        return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
                      };
                      const selectors = [
                        '.se_editable[contenteditable="true"]',
                        '.se-editable[contenteditable="true"]',
                        '.se-component-content [contenteditable="true"]',
                        '.se-module-text [contenteditable="true"]',
                        '.se-text-paragraph[contenteditable="true"]',
                        '.se-text-paragraph',
                        '[contenteditable="true"]',
                        'textarea',
                        'body[contenteditable="true"]'
                      ];
                      let target = null;
                      for (const selector of selectors) {
                        target = Array.from(document.querySelectorAll(selector)).find(visible);
                        if (target) break;
                      }
                      if (!target) return false;
                      target.scrollIntoView({ block: 'center', inline: 'center' });
                      target.focus();
                      target.click?.();
                      if ('value' in target) {
                        target.value = text;
                        target.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: text }));
                        target.dispatchEvent(new Event('change', { bubbles: true }));
                        return String(target.value || '').replace(/\\s+/g, ' ').includes(text.replace(/\\s+/g, ' ').slice(0, 20));
                      }
                      target.textContent = '';
                      const lines = text.split(/\\n/);
                      for (const [index, line] of lines.entries()) {
                        if (index > 0) target.appendChild(document.createElement('br'));
                        target.appendChild(document.createTextNode(line));
                      }
                      target.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'insertText', data: text }));
                      target.dispatchEvent(new KeyboardEvent('keyup', { bubbles: true, key: 'Process' }));
                      target.dispatchEvent(new Event('change', { bubbles: true }));
                      return (target.innerText || target.textContent || '').replace(/\\s+/g, ' ').includes(text.replace(/\\s+/g, ' ').slice(0, 20));
                    }
                    """,
                    value,
                ))
            except Exception:
                return False

        def editor_contains_inserted_text(frame) -> bool:
            if not sample_text:
                return False
            try:
                return bool(frame.evaluate(
                    """
                    ({ sample, fullText }) => {
                      const visible = (node) => {
                        if (!node) return false;
                        const rect = node.getBoundingClientRect();
                        const style = window.getComputedStyle(node);
                        return rect.width > 0 && rect.height > 0 && style.visibility !== 'hidden' && style.display !== 'none';
                      };
                      const selectors = [
                        '.se_editable[contenteditable="true"]',
                        '.se-editable[contenteditable="true"]',
                        '.se-component-content [contenteditable="true"]',
                        '.se-module-text [contenteditable="true"]',
                        '.se-text-paragraph[contenteditable="true"]',
                        '[contenteditable="true"]',
                        'textarea[placeholder*="답변"]',
                        'textarea[name*="answer"]',
                        'textarea',
                        'body[contenteditable="true"]'
                      ];
                      const expected = String(sample || '').replace(/\\s+/g, ' ').trim();
                      const fullExpected = String(fullText || '').replace(/\\s+/g, ' ').trim();
                      if (!expected) return false;
                      for (const selector of selectors) {
                        const targets = Array.from(document.querySelectorAll(selector)).filter(visible);
                        for (const target of targets) {
                          const text = String(('value' in target ? target.value : (target.innerText || target.textContent || '')) || '')
                            .replace(/\\s+/g, ' ')
                            .trim();
                          if (text.includes(expected)) return true;
                          if (fullExpected && fullExpected.length > 40 && text.length >= Math.min(40, fullExpected.length) && fullExpected.startsWith(text.slice(0, Math.min(40, text.length)))) return true;
                        }
                      }
                      return false;
                    }
                    """,
                    {"sample": sample_text, "fullText": normalized_value},
                ))
            except Exception:
                return False

        def try_paste(frame, locator) -> bool:
            nonlocal paste_used
            if paste_used:
                return False
            try:
                target_page.context.grant_permissions(["clipboard-read", "clipboard-write"], origin=target_page.url)
            except Exception:
                pass
            try:
                target_page.evaluate("(text) => navigator.clipboard.writeText(text)", value)
            except Exception:
                try:
                    target_page.set_extra_http_headers({})
                except Exception:
                    pass
            try:
                locator.click(timeout=1200)
                target_page.keyboard.press("Meta+A")
                try:
                    target_page.keyboard.press("Backspace")
                except Exception:
                    pass
                try:
                    target_page.keyboard.insert_text(value)
                    frame.wait_for_timeout(900)
                    return editor_contains_inserted_text(frame)
                except Exception:
                    pass
                paste_used = True
                target_page.keyboard.press("Meta+V")
                frame.wait_for_timeout(900)
                return editor_contains_inserted_text(frame)
            except Exception:
                return False

        for frame in [target_page, *target_page.frames]:
            if paste_with_system_clipboard(frame):
                return True
            if paste_used:
                return False
            if insert_with_keyboard(frame):
                return True
            for selector in selectors:
                try:
                    locator = frame.locator(selector).first
                    if locator.count() <= 0:
                        continue
                    locator.scroll_into_view_if_needed(timeout=1200)
                    locator.click(timeout=1200)
                    if paste_with_system_clipboard(frame):
                        return True
                    try:
                        locator.fill(value, timeout=1200)
                    except Exception:
                        if not try_insert_with_js(frame):
                            try_paste(frame, locator)
                    frame.wait_for_timeout(500)
                    if editor_contains_inserted_text(frame):
                        return True
                    if try_insert_with_js(frame) and editor_contains_inserted_text(frame):
                        return True
                except Exception:
                    continue
            if try_insert_with_js(frame) and editor_contains_inserted_text(frame):
                return True
            if insert_with_keyboard(frame):
                return True
        return False

    def click_editor_link_toolbar(target_page) -> bool:
        link_selectors = (
            "button:has-text('링크')",
            "a:has-text('링크')",
            "[aria-label='링크']",
            "[aria-label*='링크']",
            "[title='링크']",
            "[title*='링크']",
            "button[class*='link']",
            "[role='button']:has-text('링크')",
        )
        for frame in [target_page, *target_page.frames]:
            for selector in link_selectors:
                try:
                    locator = frame.locator(selector).first
                    if locator.count() <= 0:
                        continue
                    locator.click(timeout=1200)
                    target_page.wait_for_timeout(600)
                    try:
                        if target_page.locator("input[placeholder*='URL'], input[placeholder*='링크'], input[aria-label*='링크']").count() > 0:
                            target_page.keyboard.press("Escape")
                            target_page.wait_for_timeout(250)
                    except Exception:
                        pass
                    return True
                except Exception:
                    continue
        return False

    def click_naver_kin_register(target_page) -> bool:
        selectors = (
            "button:has-text('답변등록')",
            "a:has-text('답변등록')",
            "button:has-text('답변 등록')",
            "a:has-text('답변 등록')",
            "button:has-text('등록')",
            "a:has-text('등록')",
            "[role='button']:has-text('등록')",
            "input[value='등록']",
            "button:has-text('작성완료')",
            "a:has-text('작성완료')",
            "text=답변등록",
            "text=등록",
        )
        if click_first_available(target_page, selectors, timeout=1800):
            return True
        try:
            rect = find_naver_kin_register_button_rect(target_page)
        except Exception:
            rect = None
        if rect:
            try:
                target_page.mouse.click(rect["x"], rect["y"])
                target_page.wait_for_timeout(900)
                return True
            except Exception:
                pass
        try:
            rect = find_visible_text_rect(target_page, [r"^등록$", r"답변\s*등록", r"작성\s*완료"], min_top=0, max_left_ratio=1.0)
            if rect:
                target_page.mouse.click(rect["x"], rect["y"])
                target_page.wait_for_timeout(900)
                return True
        except Exception:
            pass
        return False

    NAVER_BLOG_CHROME_PROFILE_DIR.mkdir(parents=True, exist_ok=True)
    page = None
    detail_screen_opened = False
    answer_screen_opened = False
    submit_attempted = False
    success_hold_completed = False
    with sync_playwright() as playwright:
        context = playwright.chromium.launch_persistent_context(
            user_data_dir=str(NAVER_BLOG_CHROME_PROFILE_DIR),
            executable_path=str(chrome_path),
            headless=False,
            no_viewport=True,
            args=[
                "--disable-blink-features=AutomationControlled",
                "--disable-session-crashed-bubble",
                "--no-first-run",
                "--no-default-browser-check",
            ],
        )
        try:
            saved_state = load_naver_blog_storage_state()
            saved_cookies = saved_state.get("cookies", []) if isinstance(saved_state, dict) else []
            if saved_cookies:
                try:
                    context.add_cookies(saved_cookies)
                except Exception:
                    pass

            page = context.pages[-1] if context.pages else context.new_page()
            page.set_default_timeout(15_000)
            page.set_default_navigation_timeout(60_000)
            result_queue.put(("naver_kin_auto_progress", "네이버 로그인 상태를 확인하고 있습니다..."))
            page.goto(question_url, wait_until="domcontentloaded")

            deadline = time.time() + max(30, login_timeout_seconds)
            login_notice_sent = False
            while time.time() < deadline:
                if is_naver_logged_in_context(context):
                    break
                current_url = page.url or ""
                if "nid.naver.com" not in current_url:
                    login_url = (
                        "https://nid.naver.com/nidlogin.login?mode=form&url="
                        + quote(question_url, safe="")
                    )
                    page.goto(login_url, wait_until="domcontentloaded")
                if not login_notice_sent:
                    result_queue.put(("naver_kin_auto_progress", "전용 Chrome에서 네이버 로그인을 완료해 주세요. 로그인 완료까지 기다립니다..."))
                    login_notice_sent = True
                page.wait_for_timeout(1000)
            else:
                raise RuntimeError("5분 안에 네이버 로그인이 확인되지 않았습니다. 전용 Chrome에서 로그인한 뒤 다시 실행해 주세요.")

            save_naver_blog_storage_state(context)
            result_queue.put(("naver_kin_auto_progress", "로그인 확인 완료. 지식인 질문 상세로 이동합니다..."))
            put_naver_kin_action_log(result_queue, f"지식인 질문 상세페이지로 이동합니다: {question_url}")
            page.goto(question_url, wait_until="domcontentloaded")
            page.wait_for_timeout(1600)
            ensure_question_detail_page(page, question_title)
            detail_screen_opened = True
            append_naver_kin_debug_log(f"detail_ready url={page.url} title={question_title[:120]}")
            put_naver_kin_action_log(result_queue, f"지식인 상세페이지 도착: {page.url}")
            if preflight_only:
                save_naver_blog_storage_state(context)
                put_naver_kin_action_log(result_queue, "지식인 질문 상세 사전검사를 통과했습니다.")
                return True, "지식인 질문 상세 사전검사를 통과했습니다."

            result_queue.put(("naver_kin_auto_progress", "답변 입력 영역을 여는 중입니다..."))
            if not open_answer_editor(page):
                append_naver_kin_debug_log(f"open_answer_editor_failed url={page.url}")
                raise RuntimeError("지식인 상세페이지에서 '답변하기' 버튼을 찾거나 클릭하지 못했습니다. 화면에서 버튼 위치를 확인해 주세요.")
            page = select_answer_editor_page(context, page)
            answer_screen_opened = True
            page = wait_for_answer_editor(context, page, timeout_seconds=35)
            if not page_has_editable_answer_editor(page):
                raise RuntimeError("답변 에디터 입력 영역이 아직 준비되지 않았습니다. 에디터 로딩이 끝난 뒤 다시 실행해 주세요.")

            result_queue.put(("naver_kin_auto_progress", "답변 에디터 준비 완료. 생성한 답변을 입력하는 중입니다..."))
            if not fill_editor(page, answer_text):
                raise RuntimeError("지식인 답변 입력칸을 찾지 못했습니다. 화면 구조가 바뀌었거나 로그인이 필요할 수 있습니다.")
            put_naver_kin_action_log(result_queue, "답변 에디터에 답변 본문을 입력했습니다.")

            result_queue.put(("naver_kin_auto_progress", "답변 본문 입력 완료. 에디터 링크 버튼을 한 번 누르는 중입니다..."))
            click_editor_link_toolbar(page)
            put_naver_kin_action_log(result_queue, "에디터 상단 링크 버튼을 한 번 눌렀습니다.")

            result_queue.put(("naver_kin_auto_progress", "지식인 답변 등록 버튼을 누르는 중입니다..."))
            clicked = click_naver_kin_register(page)
            if not clicked:
                raise RuntimeError("지식인 답변 등록 버튼을 찾지 못했습니다. 답변은 입력됐을 수 있으니 화면을 확인해 주세요.")
            submit_attempted = True
            put_naver_kin_action_log(result_queue, "상단 파란색 등록 버튼 클릭을 시도했습니다.")

            page.wait_for_timeout(2200)
            save_naver_blog_storage_state(context)
            hold_seconds = max(0, int(post_submit_hold_seconds or 0))
            if hold_seconds:
                result_queue.put((
                    "naver_kin_auto_progress",
                    f"답변 등록을 시도했습니다. 확인할 수 있도록 브라우저를 {hold_seconds}초 동안 유지합니다...",
                ))
                page.wait_for_timeout(hold_seconds * 1000)
                success_hold_completed = True
            return True, "지식인 답변 등록을 시도했습니다."
        except PlaywrightTimeoutError as exc:
            append_naver_kin_debug_log(f"playwright_timeout url={getattr(page, 'url', '')} error={exc}")
            raise RuntimeError(f"지식인 화면 응답 시간이 초과되었습니다: {exc}") from exc
        except Exception as exc:
            append_naver_kin_debug_log(f"answer_automation_error url={getattr(page, 'url', '')} error={exc}")
            raise
        finally:
            try:
                save_naver_blog_storage_state(context)
            except Exception:
                pass
            if (submit_attempted or answer_screen_opened or detail_screen_opened) and not success_hold_completed and page is not None:
                try:
                    result_queue.put((
                        "naver_kin_auto_progress",
                        "지식인 답변 화면 확인이 필요해 브라우저를 180초 동안 유지합니다...",
                    ))
                    page.wait_for_timeout(180_000)
                except Exception:
                    pass
            context.close()


def run_tistory_playwright_automation(
    write_url: str,
    script: str,
    result_queue: queue.Queue,
    publish_after_input: bool = False,
    login_timeout_seconds: int = 300,
) -> tuple[bool, str]:
    try:
        from playwright.sync_api import TimeoutError as PlaywrightTimeoutError
        from playwright.sync_api import sync_playwright
    except ImportError as exc:
        raise RuntimeError(
            "Playwright가 설치되어 있지 않습니다. 터미널에서 `python3 -m pip install playwright`를 실행해 주세요."
        ) from exc

    chrome_path = require_google_chrome_executable()
    if not write_url:
        raise RuntimeError("티스토리 글쓰기 URL이 비어 있습니다.")

    TISTORY_CHROME_PROFILE_DIR.mkdir(parents=True, exist_ok=True)
    with sync_playwright() as playwright:
        context = playwright.chromium.launch_persistent_context(
            user_data_dir=str(TISTORY_CHROME_PROFILE_DIR),
            executable_path=str(chrome_path),
            headless=False,
            no_viewport=True,
            args=[
                "--disable-blink-features=AutomationControlled",
                "--disable-session-crashed-bubble",
                "--no-first-run",
                "--no-default-browser-check",
            ],
        )
        try:
            saved_state = load_tistory_storage_state()
            saved_cookies = saved_state.get("cookies", []) if isinstance(saved_state, dict) else []
            if saved_cookies:
                context.add_cookies(saved_cookies)
            page = context.pages[-1] if context.pages else context.new_page()
            page.set_default_timeout(20_000)
            page.set_default_navigation_timeout(60_000)
            page.on("dialog", lambda dialog: dialog.accept())
            result_queue.put(
                (
                    "tistory_progress",
                    "저장된 티스토리 로그인 상태를 확인하고 있습니다...",
                )
            )
            page.goto(write_url, wait_until="domcontentloaded")

            deadline = time.time() + max(30, login_timeout_seconds)
            editor_ready = False
            login_notice_sent = False
            while time.time() < deadline:
                try:
                    current_url = page.url or ""
                    editor_ready = (
                        "/manage/newpost" in current_url
                        or page.locator(
                            '#post-title-inp, textarea[placeholder*="제목"], input[placeholder*="제목"], #editor-mode-layer-btn-open'
                        ).count()
                        > 0
                    )
                    if editor_ready:
                        break
                    if not login_notice_sent and (
                        "/auth/login" in current_url
                        or "accounts.kakao.com" in current_url
                        or "kauth.kakao.com" in current_url
                    ):
                        result_queue.put(
                            (
                                "tistory_progress",
                                "저장된 로그인 세션이 없거나 만료되었습니다. 전용 Chrome에서 한 번만 로그인해 주세요...",
                            )
                        )
                        login_notice_sent = True
                except Exception:
                    pass
                time.sleep(1)

            if not editor_ready:
                raise RuntimeError(
                    "5분 안에 티스토리 로그인이 완료되지 않았습니다. 전용 Chrome에서 로그인한 뒤 다시 실행해 주세요."
                )
            if "/manage/newpost" not in (page.url or ""):
                page.goto(write_url, wait_until="domcontentloaded")

            save_tistory_storage_state(context)
            result_queue.put(("tistory_progress", "로그인 확인 완료. 프롬프트 순서에 따라 제목·본문·이미지를 자동 입력하고 있습니다..."))
            page.wait_for_timeout(1800)
            page.evaluate("window.onbeforeunload = null")
            result = page.evaluate(script)
            page.wait_for_timeout(1600)
            result_text = result if isinstance(result, str) else json.dumps(result, ensure_ascii=False)
            try:
                result_payload = json.loads(result_text)
            except (TypeError, json.JSONDecodeError):
                result_payload = {}
            if not result_payload.get("titleOk") and not result_payload.get("modeOnly"):
                raise RuntimeError("티스토리 제목 입력 요소를 찾지 못했습니다.")
            if not (result_payload.get("bodyOk") or result_payload.get("richBodyOk")) and not result_payload.get("modeOnly"):
                raise RuntimeError("티스토리 본문 입력 요소를 찾지 못했습니다.")
            if publish_after_input:
                published = click_tistory_public_publish_native(page, result_queue)
                if not published:
                    raise RuntimeError("티스토리 발행일 '현재' 선택 또는 공개발행 버튼을 누르지 못했습니다. 화면 구조를 확인해 주세요.")
                page.wait_for_timeout(5000)
                return True, "Playwright 네이티브 클릭으로 티스토리 프롬프트 절차와 현재 공개발행을 완료했습니다."
            return True, "Playwright로 티스토리 제목·본문 자동입력을 완료했습니다."
        except PlaywrightTimeoutError as exc:
            raise RuntimeError(f"티스토리 화면 응답 시간이 초과되었습니다: {exc}") from exc
        finally:
            save_tistory_storage_state(context)
            context.close()


def close_active_browser_tab(browser_name: str) -> None:
    if browser_name == "Safari":
        close_script = """
const app = Application('com.apple.Safari');
if (app.windows.length > 0 && app.windows[0].tabs.length > 0) {
  const tab = app.windows[0].currentTab;
  const url = String(tab.url() || '');
  if (url.includes('tistory.com/manage') || url.includes('/manage/newpost')) {
    tab.close();
  }
}
"""
    else:
        app_identifier = "com.google.Chrome" if browser_name == "Google Chrome" else "com.microsoft.edgemac"
        close_script = f"""
const app = Application({json.dumps(app_identifier)});
if (app.windows.length > 0 && app.windows[0].tabs.length > 0) {{
  const tab = app.windows[0].activeTab;
  const url = String(tab.url() || '');
  if (url.includes('tistory.com/manage') || url.includes('/manage/newpost')) {{
    tab.close();
  }}
}}
"""
    try:
        subprocess.run(
            ["osascript", "-l", "JavaScript", "-e", close_script],
            capture_output=True,
            text=True,
            check=False,
            timeout=5,
        )
    except Exception:
        pass


def run_browser_javascript(script: str, settle_seconds: float = 5.0) -> tuple[bool, str]:
    TISTORY_AUTOMATION_SCRIPT_FILE.write_text(script, encoding="utf-8")
    script_path_literal = json.dumps(str(TISTORY_AUTOMATION_SCRIPT_FILE))
    should_close_tab = False

    def build_runner(app_identifier: str, safari: bool = False) -> str:
        if safari:
            command = 'app.documents[0].doJavaScript(jsCode);'
        else:
            command = 'app.windows[0].activeTab.execute({javascript: jsCode});'
        return f"""
ObjC.import('Foundation');
const jsPath = {script_path_literal};
const jsCode = $.NSString.stringWithContentsOfFileEncodingError(jsPath, $.NSUTF8StringEncoding, null).js;
const app = Application({json.dumps(app_identifier)});
{command}
"""

    browser_scripts = [
        ("Google Chrome", build_runner("com.google.Chrome")),
        ("Microsoft Edge", build_runner("com.microsoft.edgemac")),
        ("Safari", build_runner("com.apple.Safari", safari=True)),
    ]

    errors: list[str] = []
    for browser_name, runner_script in browser_scripts:
        stop_guard = threading.Event()

        def alert_guard() -> None:
            for _ in range(70):
                if stop_guard.is_set():
                    return
                time.sleep(0.25)
                click_browser_dialog_button(browser_name, ["확인", "OK", "Ok", "예", "Yes"])
                click_front_dialog_button(["확인", "OK", "Ok", "예", "Yes"])
                click_browser_confirm_by_position(browser_name)
                send_system_key(36, repeat=1, interval=0.03)
                send_system_key(49, repeat=1, interval=0.03)

        guard_thread = threading.Thread(target=alert_guard, daemon=True)
        guard_thread.start()
        TISTORY_AUTOMATION_RUNNER_FILE.write_text(runner_script, encoding="utf-8")
        try:
            result = subprocess.run(
                ["osascript", "-l", "JavaScript", str(TISTORY_AUTOMATION_RUNNER_FILE)],
                capture_output=True,
                text=True,
                check=False,
                timeout=18,
            )
        except subprocess.TimeoutExpired:
            stop_guard.set()
            errors.append(f"{browser_name}: 자동입력 명령 시간이 초과되었습니다.")
            continue
        if result.returncode == 0:
            # Chrome returns as soon as the async script is scheduled, so keep the guard
            # alive briefly for late Tistory native dialogs.
            time.sleep(settle_seconds)
            if should_close_tab:
                close_active_browser_tab(browser_name)
            stop_guard.set()
            cleanup_tistory_automation_files()
            return True, f"{browser_name} 자동입력 명령 전송 완료"
        stop_guard.set()
        detail = (result.stderr or result.stdout).strip()
        if detail:
            if "Apple Events" in detail or "JavaScript" in detail and "disabled" in detail.lower():
                detail = (
                    f"{browser_name}: 브라우저에서 Apple Events JavaScript 실행이 꺼져 있습니다. "
                    "Chrome은 보기 > 개발자 정보 > Apple Events에서 JavaScript 허용을 켜야 자동입력이 가능합니다. "
                    f"원본 오류: {detail[:180]}"
                )
            errors.append(f"{browser_name}: {detail[:220]}")
    cleanup_tistory_automation_files()
    return False, "\n".join(errors) or "실행 중인 브라우저 탭을 찾지 못했습니다."


def send_system_key(key_code: int, repeat: int = 1, interval: float = 0.2) -> None:
    for _ in range(repeat):
        subprocess.run(
            ["osascript", "-e", f'tell application "System Events" to key code {key_code}'],
            capture_output=True,
            text=True,
            check=False,
        )
        time.sleep(interval)


def click_front_dialog_button(button_names: list[str]) -> bool:
    button_checks = "\n".join(
        f'''
        try
            click button "{button_name}" of window 1 of frontProcess
            return true
        end try
        try
            click button "{button_name}" of sheet 1 of window 1 of frontProcess
            return true
        end try
        '''
        for button_name in button_names
    )
    script = f'''
    tell application "System Events"
        try
            set frontProcess to first application process whose frontmost is true
            {button_checks}
        end try
    end tell
    return false
    '''
    result = subprocess.run(
        ["osascript", "-e", script],
        capture_output=True,
        text=True,
        check=False,
    )
    return result.returncode == 0 and "true" in (result.stdout or "").lower()


def click_browser_dialog_button(browser_name: str, button_names: list[str]) -> bool:
    button_checks = "\n".join(
        f'''
        try
            click button "{button_name}" of window 1 of browserProcess
            return true
        end try
        try
            click button "{button_name}" of sheet 1 of window 1 of browserProcess
            return true
        end try
        try
            click button "{button_name}" of group 1 of window 1 of browserProcess
            return true
        end try
        '''
        for button_name in button_names
    )
    script = f'''
    tell application "{browser_name}" to activate
    delay 0.05
    tell application "System Events"
        try
            set browserProcess to process "{browser_name}"
            set frontmost of browserProcess to true
            {button_checks}
            key code 36
            delay 0.03
            key code 49
        end try
    end tell
    return false
    '''
    result = subprocess.run(
        ["osascript", "-e", script],
        capture_output=True,
        text=True,
        check=False,
    )
    return result.returncode == 0 and "true" in (result.stdout or "").lower()


def click_browser_confirm_by_position(browser_name: str) -> bool:
    # Tistory's native browser confirm is sometimes invisible to accessibility APIs.
    # Read browser bounds through JXA, then click the right-side "확인" area with CoreGraphics.
    bounds = get_browser_window_bounds(browser_name)
    if not bounds:
        return False

    win_x = float(bounds.get("x", 0))
    win_y = float(bounds.get("y", 0))
    win_w = float(bounds.get("width", 0))
    if win_w <= 0:
        return False

    center_x = win_x + (win_w / 2)
    click_points: list[tuple[float, float]] = []
    for y_offset in (205, 220, 235, 250, 265):
        for x_offset in (175, 195, 215, 235):
            click_points.append((center_x + x_offset, win_y + y_offset))
    for x, y in click_points:
        if coregraphics_click(x, y):
            time.sleep(0.04)
    return True


def get_browser_window_bounds(browser_name: str) -> dict | None:
    app_identifiers = {
        "Google Chrome": "com.google.Chrome",
        "Microsoft Edge": "com.microsoft.edgemac",
        "Safari": "com.apple.Safari",
    }
    app_identifier = app_identifiers.get(browser_name, browser_name)
    script = f'JSON.stringify(Application({json.dumps(app_identifier)}).windows[0].bounds())'
    result = subprocess.run(
        ["osascript", "-l", "JavaScript", "-e", script],
        capture_output=True,
        text=True,
        check=False,
    )
    if result.returncode != 0:
        return None
    try:
        payload = json.loads((result.stdout or "").strip())
    except json.JSONDecodeError:
        return None
    return payload if isinstance(payload, dict) else None


def coregraphics_click(x: float, y: float) -> bool:
    try:
        cg = ctypes.CDLL("/System/Library/Frameworks/CoreGraphics.framework/CoreGraphics")
        point_type = ctypes.c_double * 2
        cg.CGEventCreateMouseEvent.restype = ctypes.c_void_p
        cg.CGEventCreateMouseEvent.argtypes = [ctypes.c_void_p, ctypes.c_uint32, point_type, ctypes.c_uint32]
        cg.CGEventPost.argtypes = [ctypes.c_uint32, ctypes.c_void_p]
        cg.CFRelease.argtypes = [ctypes.c_void_p]
        for event_type in (1, 2):
            event = cg.CGEventCreateMouseEvent(None, event_type, point_type(x, y), 0)
            if not event:
                return False
            cg.CGEventPost(0, event)
            cg.CFRelease(event)
            time.sleep(0.015)
        return True
    except Exception:
        return False


