    def _is_widget_inside_scroll_frame(self, widget, scroll_frame: ctk.CTkScrollableFrame) -> bool:
        canvas = getattr(scroll_frame, "_parent_canvas", None)
        while widget is not None:
            if widget == canvas:
                return True
            widget = getattr(widget, "master", None)
        return False

    def _is_scroll_content_taller_than_view(self, scroll_frame: ctk.CTkScrollableFrame) -> bool:
        canvas = getattr(scroll_frame, "_parent_canvas", None)
        if canvas is None:
            return False
        try:
            if not canvas.winfo_exists():
                return False
            bbox = canvas.bbox("all")
            if not bbox:
                return False
            return (bbox[3] - bbox[1]) > canvas.winfo_height() + 2
        except tk.TclError:
            return False

    def _contain_child_scroll(self, parent: ctk.CTkScrollableFrame, child: ctk.CTkScrollableFrame) -> None:
        original_check = getattr(parent, "check_if_master_is_canvas", None)
        if not callable(original_check):
            return
        if not hasattr(parent, "_blog_helper_scroll_exclusions"):
            parent._blog_helper_scroll_exclusions = []
            parent._blog_helper_original_check_if_master_is_canvas = original_check

            def guarded_check(widget, scroll_parent=parent):
                for excluded_child in getattr(scroll_parent, "_blog_helper_scroll_exclusions", []):
                    if self._is_scroll_content_taller_than_view(excluded_child) and self._is_widget_inside_scroll_frame(widget, excluded_child):
                        return False
                original = getattr(scroll_parent, "_blog_helper_original_check_if_master_is_canvas", None)
                if callable(original):
                    return original(widget)
                return False

            parent.check_if_master_is_canvas = guarded_check

        if child not in parent._blog_helper_scroll_exclusions:
            parent._blog_helper_scroll_exclusions.append(child)
            self._scroll_exclusion_bindings.append((parent, child))

    def _bind_private_mousewheel_scroll(self, widget) -> None:
        def on_mousewheel(event):
            delta = getattr(event, "delta", 0)
            if delta:
                units = -int(delta / 120) if abs(delta) >= 120 else -int(delta)
                if units == 0:
                    units = -1 if delta > 0 else 1
            else:
                units = -1 if getattr(event, "num", 0) == 4 else 1
            try:
                widget.yview_scroll(units, "units")
            except Exception:
                pass
            return "break"

        targets = [widget]
        internal_textbox = getattr(widget, "_textbox", None)
        if internal_textbox is not None:
            targets.append(internal_textbox)
        for target in targets:
            target.bind("<MouseWheel>", on_mousewheel)
            target.bind("<Button-4>", on_mousewheel)
            target.bind("<Button-5>", on_mousewheel)

