    def _fetch_public_data_events(self) -> None:
        if self.public_data_worker and self.public_data_worker.is_alive():
            messagebox.showinfo("진행 중", "공공데이터 행사정보를 가져오는 중입니다.")
            return
        api_key = self.public_data_key_entry.get().strip()
        if not api_key:
            messagebox.showerror("입력 오류", "공공데이터 API 키를 입력해 주세요.")
            return
        settings = self._read_wordpress_settings(include_prompts=False)
        self.wordpress_settings = settings
        AppStateStore.save(settings)
        self.public_data_fetch_button.configure(state="disabled", text="조회 중...")
        self.public_data_status_label.configure(text="공공데이터 API 조회를 시작했습니다.", text_color="#6dadff")
        self.public_data_worker = PublicDataEventWorker(
            service_key=api_key,
            keyword=self.public_data_keyword_entry.get(),
            region=self.public_data_region_entry.get(),
            event_type=self.public_data_type_menu.get(),
            start_date=self.public_data_start_entry.get(),
            end_date=self.public_data_end_entry.get(),
            result_queue=self.result_queue,
        )
        self.public_data_worker.start()

    def _save_public_data_state(self) -> None:
        if not hasattr(self, "public_data_key_entry"):
            return
        self.wordpress_settings.public_data_api_key = self.public_data_key_entry.get().strip()
        self.wordpress_settings.public_data_keyword = self.public_data_keyword_entry.get().strip()
        self.wordpress_settings.public_data_region = self.public_data_region_entry.get().strip()
        self.wordpress_settings.public_data_type = self.public_data_type_menu.get()
        self.wordpress_settings.public_data_events = list(self.public_data_events)
        self.wordpress_settings.public_data_selected_seq = self.selected_public_event_var.get()
        AppStateStore.save(self.wordpress_settings)

    def _render_public_data_events(self, events: list[dict]) -> None:
        if not hasattr(self, "public_data_result_frame"):
            return
        table_palette = self._public_data_table_palette()
        if hasattr(self, "public_data_table_card"):
            self.public_data_table_card.configure(
                fg_color=table_palette["table_fg"],
                border_color=table_palette["border"],
            )
        if hasattr(self, "public_data_header_row"):
            self.public_data_header_row.configure(fg_color=table_palette["header_fg"])
            for header_label in self.public_data_header_row.winfo_children():
                if isinstance(header_label, ctk.CTkLabel):
                    header_label.configure(text_color=table_palette["text"])
        for child in self.public_data_result_frame.winfo_children():
            child.destroy()
        self.public_data_events = list(events)
        if not events:
            empty = ctk.CTkFrame(self.public_data_result_frame, fg_color=table_palette["empty_fg"], corner_radius=16)
            empty.grid(row=0, column=0, padx=8, pady=10, sticky="ew")
            ctk.CTkLabel(
                empty,
                text="조회된 행사정보가 없습니다. API 키와 검색 조건을 입력한 뒤 조회해 주세요.",
                text_color=table_palette["subtext"],
                font=ctk.CTkFont(size=14),
                wraplength=760,
                justify="left",
            ).grid(row=0, column=0, padx=18, pady=18, sticky="w")
            self._finish_theme_paint()
            return

        selected = self.selected_public_event_var.get()
        if not selected:
            self.selected_public_event_var.set(str(events[0].get("seq") or "0"))
        for row, event in enumerate(events, start=1):
            seq = str(event.get("seq") or row)
            row_frame = ctk.CTkFrame(
                self.public_data_result_frame,
                fg_color=table_palette["row_odd"] if row % 2 else table_palette["row_even"],
                corner_radius=14,
            )
            row_frame.grid(row=row - 1, column=0, padx=8, pady=(0, 8), sticky="ew")
            self._configure_public_data_table_columns(row_frame)
            ctk.CTkRadioButton(
                row_frame,
                text="",
                value=seq,
                variable=self.selected_public_event_var,
                command=self._save_public_data_state,
                width=22,
                radiobutton_width=18,
                radiobutton_height=18,
                fg_color="#3468e8",
                hover_color="#2d5cd0",
            ).grid(row=0, column=0, padx=(10, 4), pady=12, sticky="w")
            values = [
                str(row),
                self._event_value(event, "title"),
                self._event_value(event, "place"),
                self._event_value(event, "realmName") or self._event_value(event, "serviceName"),
                self._format_public_event_date(self._event_value(event, "startDate")),
                self._format_public_event_date(self._event_value(event, "endDate")),
                self._event_value(event, "price") or "정보 없음",
            ]
            for col, value in enumerate(values, start=1):
                ctk.CTkLabel(
                    row_frame,
                    text=value,
                    text_color=table_palette["text"] if col == 2 else table_palette["muted"],
                    font=ctk.CTkFont(size=13, weight="bold" if col == 2 else "normal"),
                    anchor="w",
                    justify="left",
                    wraplength=280 if col == 2 else 145,
                ).grid(row=0, column=col, padx=8, pady=12, sticky="ew")
        self._finish_theme_paint()

    def _selected_public_event(self) -> dict | None:
        selected = self.selected_public_event_var.get()
        if not selected and self.public_data_events:
            return self.public_data_events[0]
        for event in self.public_data_events:
            if str(event.get("seq") or "") == selected:
                return event
        return None

    def _apply_selected_public_event_to_writing(self) -> None:
        event = self._selected_public_event()
        if not event:
            messagebox.showwarning("선택 필요", "글쓰기에 반영할 행사를 선택해 주세요.")
            return
        title = self._event_value(event, "title") or "공공데이터 행사"
        reference_text = str(event.get("reference_text") or "").strip()
        source_url = str(event.get("source_url") or event.get("url") or "").strip()
        self.current_keyword = "공공데이터 공연/행사"
        self.current_insights = [
            KeywordInsight(
                keyword=title,
                score=92,
                reasons=["공공데이터포털 문화정보 API 기반", "행사명/장소/기간/입장료 등 사실 정보 포함"],
                sources=["공공데이터"],
                categories=[self._event_value(event, "realmName") or self.public_data_type_menu.get()],
                source_urls={"공공데이터 출처": source_url or "https://www.data.go.kr/"},
            )
        ]
        self.selected_keyword_var.set(title)
        if hasattr(self, "topic_entry"):
            self.topic_entry.delete(0, "end")
            self.topic_entry.insert(0, title)
        if hasattr(self, "manual_keyword_entry"):
            self.manual_keyword_entry.delete(0, "end")
            self.manual_keyword_entry.insert(0, title)
        if hasattr(self, "reference_textbox"):
            self.reference_textbox.delete("1.0", "end")
            self.reference_textbox.insert("1.0", reference_text)
            self._update_reference_count()
        self.daum_reference_map = {}
        self.signal_reference_map = {}
        self.newneek_reference_map = {}
        self.collected_reference_map = {title: reference_text}
        self._render_keyword_choices(self.current_insights)
        self._render_results(self.current_insights)
        self._switch_page("writing")
        self._open_writing_section("keyword")
        self.keyword_status_label.configure(text="공공데이터 행사정보를 블로그글쓰기에 반영했습니다.")
        self._save_ui_state()

    def _event_value(self, event: dict, key: str) -> str:
        return re.sub(r"\s+", " ", str(event.get(key) or "").strip())

    def _format_public_event_date(self, value: str) -> str:
        digits = re.sub(r"\D", "", value or "")
        if len(digits) >= 8:
            return f"{digits[:4]}-{digits[4:6]}-{digits[6:8]}"
        return value or "-"

