    def _prompt_textarea(self, parent, row: int, height: int, sticky: str = "ew") -> tk.Text:
        frame = ctk.CTkFrame(parent, fg_color="#111826", corner_radius=16)
        frame.grid(row=row, column=0, padx=24, pady=(0, 18), sticky=sticky)
        frame.grid_columnconfigure(0, weight=1)
        frame.grid_rowconfigure(0, weight=1)

        text_box = tk.Text(
            frame,
            height=height,
            wrap="word",
            undo=True,
            maxundo=100,
            bg="#111826",
            fg="#e6edf7",
            insertbackground="#e6edf7",
            selectbackground="#3468e8",
            relief="flat",
            borderwidth=0,
            padx=14,
            pady=12,
            font=("Helvetica", 14),
        )
        scrollbar = tk.Scrollbar(frame, orient="vertical", command=text_box.yview, bg="#111826", troughcolor="#1b2533")
        text_box.configure(yscrollcommand=scrollbar.set)
        text_box.grid(row=0, column=0, sticky="nsew")
        scrollbar.grid(row=0, column=1, sticky="ns")
        text_box.bind("<KeyRelease>", self._on_prompt_text_changed)
        self._bind_private_mousewheel_scroll(text_box)
        return text_box

    def _switch_prompt_platform(self, platform: str) -> None:
        if hasattr(self, "active_prompt_platform") and self.active_prompt_platform in getattr(self, "prompt_title_boxes", {}):
            self._save_active_prompt_set_to_memory(self.active_prompt_platform)
        self.active_prompt_platform = platform
        palette = self._theme_palette()
        for key, frame in self.prompt_platform_frames.items():
            if key == platform:
                frame.tkraise()
            button = self.prompt_tab_buttons.get(key)
            if button:
                button.configure(
                    text_color=palette["accent"] if key == platform else palette["muted"],
                    fg_color=palette["selected"] if key == platform else "transparent",
                    hover_color=palette["hover"],
                )
        if platform in self.prompt_title_boxes:
            self.title_prompt_box = self.prompt_title_boxes[platform]
        if platform in self.prompt_article_boxes:
            self.article_prompt_box = self.prompt_article_boxes[platform]
        if platform in getattr(self, "prompt_set_menus", {}):
            self._load_prompt_set_into_boxes(platform)
        self._finish_theme_paint()

    def _prompt_sets(self) -> list[dict]:
        if not self.wordpress_settings.prompt_sets:
            self.wordpress_settings.prompt_sets = PromptFileStore.default_prompt_sets(self.wordpress_settings)
        self.wordpress_settings.prompt_sets = PromptFileStore.normalize_prompt_sets(
            self.wordpress_settings.prompt_sets,
            self.wordpress_settings,
        )
        return self.wordpress_settings.prompt_sets

    def _prompt_set_label(self, prompt_set: dict) -> str:
        platform_label = {"wordpress": "워드프레스", "tistory": "티스토리", "blogspot": "블로그스팟"}.get(
            str(prompt_set.get("platform") or ""),
            "블로그",
        )
        return f"{platform_label} · {prompt_set.get('name') or '기본'}"

    def _prompt_set_menu_values(self, platform: str | None = None) -> list[str]:
        values = []
        for prompt_set in self._prompt_sets():
            if platform and prompt_set.get("platform") != platform:
                continue
            values.append(self._prompt_set_label(prompt_set))
        return values or ["기본"]

    def _prompt_set_by_label(self, label: str, platform: str | None = None) -> dict | None:
        for prompt_set in self._prompt_sets():
            if platform and prompt_set.get("platform") != platform:
                continue
            if self._prompt_set_label(prompt_set) == label:
                return prompt_set
        return None

    def _prompt_set_by_id(self, prompt_id: str) -> dict | None:
        return next((item for item in self._prompt_sets() if item.get("id") == prompt_id), None)

    def _refresh_prompt_set_menus(self) -> None:
        if not hasattr(self, "prompt_set_menus"):
            return
        for platform, menu in self.prompt_set_menus.items():
            values = self._prompt_set_menu_values(platform)
            menu.configure(values=values)
            active_id = self.active_prompt_set_ids.get(platform)
            active_set = self._prompt_set_by_id(active_id) if active_id else None
            if not active_set or active_set.get("platform") != platform:
                active_set = next((item for item in self._prompt_sets() if item.get("platform") == platform), None)
                if active_set:
                    self.active_prompt_set_ids[platform] = str(active_set.get("id"))
            if active_set:
                menu.set(self._prompt_set_label(active_set))
        self._refresh_writing_prompt_menu()

    def _refresh_writing_prompt_menu(self) -> None:
        if not hasattr(self, "writing_prompt_menu"):
            return
        values = self._prompt_set_menu_values()
        self.writing_prompt_menu.configure(values=values)
        selected_set = self._prompt_set_by_id(self.wordpress_settings.selected_prompt_id)
        selected_label = self._prompt_set_label(selected_set) if selected_set else values[0]
        if selected_label not in values:
            selected_label = values[0]
        self.writing_prompt_menu.set(selected_label)

    def _save_active_prompt_set_to_memory(self, platform: str) -> None:
        if platform not in getattr(self, "prompt_title_boxes", {}):
            return
        prompt_id = self.active_prompt_set_ids.get(platform)
        prompt_set = self._prompt_set_by_id(prompt_id) if prompt_id else None
        if not prompt_set:
            return
        prompt_set["name"] = self.prompt_name_entries[platform].get().strip() or "기본"
        prompt_set["title_prompt"] = self.prompt_title_boxes[platform].get("1.0", "end").strip()
        prompt_set["article_prompt"] = self.prompt_article_boxes[platform].get("1.0", "end").strip()

    def _load_prompt_set_into_boxes(self, platform: str) -> None:
        prompt_id = self.active_prompt_set_ids.get(platform)
        prompt_set = self._prompt_set_by_id(prompt_id) if prompt_id else None
        if not prompt_set or prompt_set.get("platform") != platform:
            prompt_set = next((item for item in self._prompt_sets() if item.get("platform") == platform), None)
        if not prompt_set:
            return
        self.active_prompt_set_ids[platform] = str(prompt_set.get("id"))
        if platform in self.prompt_set_menus:
            self.prompt_set_menus[platform].set(self._prompt_set_label(prompt_set))
        self.prompt_name_entries[platform].delete(0, "end")
        self.prompt_name_entries[platform].insert(0, str(prompt_set.get("name") or "기본"))
        self.prompt_title_boxes[platform].delete("1.0", "end")
        self.prompt_title_boxes[platform].insert("1.0", str(prompt_set.get("title_prompt") or ""))
        self.prompt_article_boxes[platform].delete("1.0", "end")
        self.prompt_article_boxes[platform].insert("1.0", str(prompt_set.get("article_prompt") or ""))

    def _select_prompt_set_from_menu(self, platform: str) -> None:
        self._save_active_prompt_set_to_memory(platform)
        selected = self._prompt_set_by_label(self.prompt_set_menus[platform].get(), platform)
        if selected:
            self.active_prompt_set_ids[platform] = str(selected.get("id"))
            self._load_prompt_set_into_boxes(platform)
        self._on_prompt_text_changed()

    def _add_prompt_set(self, platform: str) -> None:
        self._save_active_prompt_set_to_memory(platform)
        base_name = self.prompt_name_entries[platform].get().strip() or "새 프롬프트"
        prompt_id = f"{platform}-{int(time.time() * 1000)}"
        self.wordpress_settings.prompt_sets.append(
            {
                "id": prompt_id,
                "platform": platform,
                "name": base_name if base_name != "기본" else "새 프롬프트",
                "title_prompt": self.prompt_title_boxes[platform].get("1.0", "end").strip(),
                "article_prompt": self.prompt_article_boxes[platform].get("1.0", "end").strip(),
            }
        )
        self.active_prompt_set_ids[platform] = prompt_id
        self._refresh_prompt_set_menus()
        self._load_prompt_set_into_boxes(platform)
        self.prompt_feedback_label.configure(text="새 프롬프트가 추가되었습니다. 저장 버튼을 누르면 반영됩니다.", text_color="#f4c95d")

    def _update_prompt_set(self, platform: str) -> None:
        prompt_id = self.active_prompt_set_ids.get(platform)
        prompt_set = self._prompt_set_by_id(prompt_id) if prompt_id else None
        if not prompt_set:
            self.prompt_feedback_label.configure(text="수정할 프롬프트를 먼저 선택해 주세요.", text_color="#ffb84d")
            return
        self._save_active_prompt_set_to_memory(platform)
        self.wordpress_settings.prompt_sets = PromptFileStore.normalize_prompt_sets(
            self.wordpress_settings.prompt_sets,
            self.wordpress_settings,
        )
        PromptFileStore.save_prompt_sets(self.wordpress_settings.prompt_sets)
        settings = self._read_wordpress_settings()
        self.wordpress_settings = settings
        AppStateStore.save(settings, save_secrets=False)
        self._refresh_prompt_set_menus()
        self._refresh_writing_prompt_menu()
        prompt_name = self.prompt_name_entries[platform].get().strip() or "선택한"
        self.prompt_feedback_label.configure(text=f"{prompt_name} 프롬프트 수정 저장 완료", text_color="#48d980")

    def _delete_prompt_set(self, platform: str) -> None:
        platform_sets = [item for item in self._prompt_sets() if item.get("platform") == platform]
        if len(platform_sets) <= 1:
            messagebox.showwarning("삭제 불가", "플랫폼마다 최소 1개의 프롬프트는 필요합니다.")
            return
        prompt_id = self.active_prompt_set_ids.get(platform)
        self.wordpress_settings.prompt_sets = [item for item in self._prompt_sets() if item.get("id") != prompt_id]
        first = next((item for item in self.wordpress_settings.prompt_sets if item.get("platform") == platform), None)
        if first:
            self.active_prompt_set_ids[platform] = str(first.get("id"))
        self._refresh_prompt_set_menus()
        self._load_prompt_set_into_boxes(platform)
        self.prompt_feedback_label.configure(text="프롬프트를 삭제했습니다. 저장 버튼을 누르면 반영됩니다.", text_color="#f4c95d")

    def _on_writing_prompt_selected(self, label: str) -> None:
        selected = self._prompt_set_by_label(label)
        if selected:
            self.wordpress_settings.selected_prompt_id = str(selected.get("id") or "")
        self._save_ui_state()

    def _platform_prompt_values_from_boxes(self) -> dict[str, str]:
        if hasattr(self, "active_prompt_platform"):
            self._save_active_prompt_set_to_memory(self.active_prompt_platform)
        if not hasattr(self, "prompt_title_boxes"):
            return {}
        return {
            "wordpress_title_prompt_template": self.prompt_title_boxes["wordpress"].get("1.0", "end").strip(),
            "wordpress_article_prompt_template": self.prompt_article_boxes["wordpress"].get("1.0", "end").strip(),
            "tistory_title_prompt_template": self.prompt_title_boxes["tistory"].get("1.0", "end").strip(),
            "tistory_article_prompt_template": self.prompt_article_boxes["tistory"].get("1.0", "end").strip(),
            "blogspot_title_prompt_template": self.prompt_title_boxes["blogspot"].get("1.0", "end").strip(),
            "blogspot_article_prompt_template": self.prompt_article_boxes["blogspot"].get("1.0", "end").strip(),
            "tistory_automation_prompt": self.tistory_automation_prompt_box.get("1.0", "end").strip()
            if self.tistory_automation_prompt_box
            else self.wordpress_settings.tistory_automation_prompt,
            "naver_kin_answer_prompt": self.naver_kin_answer_prompt_box.get("1.0", "end").strip()
            if self.naver_kin_answer_prompt_box
            else self.wordpress_settings.naver_kin_answer_prompt,
        }

    def _current_tistory_automation_prompt(self) -> str:
        prompt = ""
        if hasattr(self, "tistory_automation_prompt_box") and self.tistory_automation_prompt_box:
            try:
                prompt = self.tistory_automation_prompt_box.get("1.0", "end").strip()
            except tk.TclError:
                prompt = ""
        prompt = prompt or self.wordpress_settings.tistory_automation_prompt or DEFAULT_TISTORY_AUTOMATION_PROMPT
        self.wordpress_settings.tistory_automation_prompt = prompt
        return prompt

    def _current_naver_kin_answer_prompt(self) -> str:
        prompt = ""
        if hasattr(self, "naver_kin_answer_prompt_box") and self.naver_kin_answer_prompt_box:
            try:
                prompt = self.naver_kin_answer_prompt_box.get("1.0", "end").strip()
            except tk.TclError:
                prompt = ""
        prompt = prompt or self.wordpress_settings.naver_kin_answer_prompt or DEFAULT_NAVER_KIN_ANSWER_PROMPT
        self.wordpress_settings.naver_kin_answer_prompt = prompt
        return prompt

    def _select_naver_kin_prompt_for_writing(self) -> None:
        prompt = self._current_naver_kin_answer_prompt()
        prompt_sets = PromptFileStore.normalize_prompt_sets(self.wordpress_settings.prompt_sets, self.wordpress_settings)
        target_id = "wordpress-naver-kin-answer"
        target_set = next((item for item in prompt_sets if item.get("id") == target_id), None)
        if not target_set:
            target_set = {
                "id": target_id,
                "platform": "wordpress",
                "name": "N지식인 답변",
                "title_prompt": DEFAULT_WORDPRESS_TITLE_PROMPT,
                "article_prompt": prompt,
            }
            prompt_sets.append(target_set)
        target_set["name"] = "N지식인 답변"
        target_set["platform"] = "wordpress"
        target_set["article_prompt"] = prompt
        if not str(target_set.get("title_prompt") or "").strip():
            target_set["title_prompt"] = DEFAULT_WORDPRESS_TITLE_PROMPT
        self.wordpress_settings.prompt_sets = PromptFileStore.normalize_prompt_sets(prompt_sets, self.wordpress_settings)
        self.wordpress_settings.selected_prompt_id = target_id
        self.active_prompt_set_ids["wordpress"] = target_id
        PromptFileStore.save_prompt_sets(self.wordpress_settings.prompt_sets)
        if hasattr(self, "prompt_set_menus"):
            self._refresh_prompt_set_menus()

    def _primary_prompt_platform(self, target_platforms: list[str] | None = None) -> str:
        platforms = target_platforms or [platform for platform, var in self.target_platform_vars.items() if var.get()]
        if len(platforms) == 1:
            return platforms[0]
        # 티스토리는 에디터/HTML 전환 방식이 달라 전용 프롬프트를 우선 적용합니다.
        for platform in ("tistory", "wordpress", "blogspot"):
            if platform in platforms:
                return platform
        return "wordpress"

    def _selected_platform_prompts(self, settings: WordPressSettings, platform: str) -> tuple[str, str]:
        return {
            "wordpress": (settings.wordpress_title_prompt_template, settings.wordpress_article_prompt_template),
            "tistory": (settings.tistory_title_prompt_template, settings.tistory_article_prompt_template),
            "blogspot": (settings.blogspot_title_prompt_template, settings.blogspot_article_prompt_template),
        }.get(platform, (settings.wordpress_title_prompt_template, settings.wordpress_article_prompt_template))

