        self.keyword_choice_frame = ctk.CTkScrollableFrame(keyword_card, fg_color="#111826", corner_radius=18, height=180)
        self.keyword_choice_frame.grid(row=0, column=0, padx=24, pady=(18, 16), sticky="ew")
        self.keyword_choice_frame.grid_columnconfigure(0, weight=1)
        self._contain_child_scroll(self.writing_scroll, self.keyword_choice_frame)

        manual_keyword_label = ctk.CTkLabel(
            keyword_card,
            text="직접 키워드 입력",
            anchor="w",
            font=ctk.CTkFont(size=15, weight="bold"),
        )
        manual_keyword_label.grid(row=1, column=0, padx=24, pady=(0, 8), sticky="w")

        self.manual_keyword_entry = ctk.CTkEntry(
            keyword_card,
            height=46,
            corner_radius=14,
            fg_color="#111826",
            border_width=0,
            placeholder_text="추천 키워드가 마음에 들지 않으면 여기에 직접 입력하세요.",
            font=ctk.CTkFont(size=15, weight="bold"),
        )
        self.manual_keyword_entry.grid(row=2, column=0, padx=24, pady=(0, 14), sticky="ew")
        self.manual_keyword_entry.bind("<Return>", lambda _event: self._generate_article_from_selection())
        self.manual_keyword_entry.bind("<KeyRelease>", lambda _event: self._on_manual_keyword_changed())

        reference_header = ctk.CTkFrame(keyword_card, fg_color="transparent")
