    def _create_writing_section(
        self,
        parent: ctk.CTkFrame,
        section_key: str,
        title: str,
        row: int,
        opened: bool,
    ) -> ctk.CTkFrame:
        card = ctk.CTkFrame(
            parent,
            fg_color="#222c3b",
            corner_radius=24,
            border_width=1,
            border_color="#334760",
        )
        card.grid(row=row, column=0, pady=(0, 16), sticky="ew")
        card.grid_columnconfigure(0, weight=1)

        header = ctk.CTkFrame(card, fg_color="transparent")
        header.grid(row=0, column=0, padx=20, pady=(16, 8), sticky="ew")
        header.grid_columnconfigure(0, weight=1)

        title_label = ctk.CTkLabel(
            header,
            text=title,
            font=ctk.CTkFont(size=20, weight="bold"),
        )
        title_label.grid(row=0, column=0, sticky="w")

        toggle_button = ctk.CTkButton(
            header,
            text="접기" if opened else "열기",
            width=88,
            height=34,
            corner_radius=12,
            fg_color="#314761",
            hover_color="#3f5c7f",
            font=ctk.CTkFont(size=13, weight="bold"),
            command=lambda key=section_key: self._toggle_writing_section(key),
        )
        toggle_button.grid(row=0, column=1, sticky="e")

        body = ctk.CTkFrame(card, fg_color="transparent")
        body.grid(row=1, column=0, sticky="ew")
        body.grid_columnconfigure(0, weight=1)

        self.writing_section_cards[section_key] = card
        self.writing_section_bodies[section_key] = body
        self.writing_section_toggle_buttons[section_key] = toggle_button

        if opened:
            self.active_writing_section = section_key
        else:
            body.grid_remove()

        return body

    def _toggle_writing_section(self, section_key: str) -> None:
        if self.active_writing_section == section_key:
            self._set_writing_section_open(section_key, False)
            self.active_writing_section = ""
            return

        self._open_writing_section(section_key)

    def _open_writing_section(self, section_key: str) -> None:
        for key in self.writing_section_bodies:
            self._set_writing_section_open(key, key == section_key)
        self.active_writing_section = section_key
        self.after(80, lambda key=section_key: self._scroll_writing_section_into_view(key))

    def _scroll_writing_section_into_view(self, section_key: str) -> None:
        card = self.writing_section_cards.get(section_key)
        canvas = getattr(self.writing_scroll, "_parent_canvas", None)
        if not card or canvas is None:
            return
        try:
            self.update_idletasks()
            bbox = canvas.bbox("all")
            if not bbox:
                return
            content_height = max(1, bbox[3] - bbox[1])
            target_y = max(0, card.winfo_y() - 14)
            canvas.yview_moveto(min(1.0, target_y / content_height))
        except Exception:
            pass

    def _go_to_thumbnail_section(self) -> None:
        article_html = self.article_editor.get("1.0", "end").strip()
        if not article_html or article_html == "생성된 글이 여기에 표시됩니다. 내용을 직접 수정한 뒤 업로드할 수 있습니다.":
            messagebox.showwarning("글 없음", "먼저 생성된 글을 확인하거나 본문을 입력해 주세요.")
            return
        if self._thumbnail_sync_job is not None:
            self.after_cancel(self._thumbnail_sync_job)
            self._thumbnail_sync_job = None
        try:
            self._sync_thumbnail_text_if_needed()
        except Exception:
            pass
        try:
            self._generate_thumbnail_preview()
        except Exception as exc:
            self.publish_status_label.configure(
                text=f"썸네일 미리보기 갱신은 건너뛰었습니다: {str(exc)[:80]}",
                text_color="#ffb86b",
            )
        self._open_writing_section("publish")

    def _set_writing_section_open(self, section_key: str, opened: bool) -> None:
        body = self.writing_section_bodies.get(section_key)
        button = self.writing_section_toggle_buttons.get(section_key)
        if not body or not button:
            return

        if opened:
            body.grid()
            button.configure(text="접기")
        else:
            body.grid_remove()
            button.configure(text="열기")

