    def _fill_thumbnail_text_from_article_title(self) -> None:
        title = self.article_title_entry.get().strip() or self.generated_article_title or self._selected_or_manual_keyword()
        if not title:
            messagebox.showwarning("제목 없음", "먼저 글 제목을 입력하거나 생성해 주세요.")
            return
        self.thumbnail_prompt_preview.delete("1.0", "end")
        self.thumbnail_prompt_preview.insert("1.0", title)
        self._show_thumbnail_preview()
        self._save_ui_state()

    def _on_article_title_changed(self, _event=None) -> None:
        self._mark_text_input_activity(_event)
        if self._thumbnail_sync_job is not None:
            self.after_cancel(self._thumbnail_sync_job)
        self._thumbnail_sync_job = self.after(1100, self._sync_thumbnail_text_if_needed)

    def _sync_thumbnail_text_if_needed(self) -> None:
        self._thumbnail_sync_job = None
        if self._defer_while_text_composing("_thumbnail_sync_job", self._sync_thumbnail_text_if_needed, 1.2):
            return
        if not self.thumbnail_auto_title_var.get():
            self._save_ui_state()
            return
        title = self.article_title_entry.get().strip() or self.generated_article_title
        if not title:
            return
        self.thumbnail_prompt_preview.delete("1.0", "end")
        self.thumbnail_prompt_preview.insert("1.0", title)
        self._generate_thumbnail_preview()
        self._save_ui_state()

    def _on_thumbnail_control_changed(self) -> None:
        self._generate_thumbnail_preview()
        self._save_ui_state()

    def _schedule_thumbnail_control_update(self, _event=None) -> None:
        self._mark_text_input_activity(_event)
        if self._thumbnail_control_job is not None:
            self.after_cancel(self._thumbnail_control_job)
        self._thumbnail_control_job = self.after(1100, self._run_scheduled_thumbnail_control_update)

    def _run_scheduled_thumbnail_control_update(self) -> None:
        self._thumbnail_control_job = None
        if self._defer_while_text_composing("_thumbnail_control_job", self._run_scheduled_thumbnail_control_update, 1.2):
            return
        self._on_thumbnail_control_changed()

    def _on_thumbnail_image_adjust_changed(self, *_args) -> None:
        scale = round(float(self.thumbnail_image_scale_var.get()))
        opacity = round(float(self.thumbnail_image_opacity_var.get()))
        if hasattr(self, "thumbnail_image_scale_value_label"):
            self.thumbnail_image_scale_value_label.configure(text=f"{scale}%")
        if hasattr(self, "thumbnail_image_opacity_value_label"):
            self.thumbnail_image_opacity_value_label.configure(text=f"{opacity}%")
        self._on_thumbnail_control_changed()

    def _on_thumbnail_background_mode_changed(self, _value: str) -> None:
        self._on_thumbnail_control_changed()

    def _on_thumbnail_ratio_changed(self, ratio_name: str) -> None:
        width = self._safe_int(self.thumbnail_width_entry.get(), 400)
        ratio_map = {
            "1:1": (1, 1),
            "16:9": (16, 9),
            "4:5": (4, 5),
            "3:2": (3, 2),
        }
        x_ratio, y_ratio = ratio_map.get(ratio_name, (1, 1))
        height = max(1, round(width * y_ratio / x_ratio))
        self.thumbnail_height_entry.delete(0, "end")
        self.thumbnail_height_entry.insert(0, str(height))
        self._on_thumbnail_control_changed()

    def _on_cardnews_control_changed(self) -> None:
        if getattr(self, "_loading_cardnews_slide_style", False):
            return
        self._save_active_cardnews_slide()
        self._show_cardnews_preview()
        self._save_ui_state()

