    def _load_thumbnail_image_from_clipboard(self) -> None:
        clipboard_path = DATA_DIR / "clipboard-thumbnail.png"
        try:
            result = subprocess.run(
                ["pngpaste", str(clipboard_path)],
                capture_output=True,
                text=True,
                check=False,
            )
        except FileNotFoundError:
            messagebox.showerror(
                "클립보드 가져오기 실패",
                "mac에서 클립보드 이미지를 가져오려면 `pngpaste` 설치가 필요합니다.\n예: brew install pngpaste",
            )
            return

        if result.returncode != 0 or not clipboard_path.exists():
            messagebox.showerror("클립보드 가져오기 실패", "현재 클립보드에 이미지가 없거나 읽지 못했습니다.")
            return

        self.thumbnail_background_image_path = str(clipboard_path)
        self.thumbnail_selected_image_label_text.set("clipboard-thumbnail.png")
        self.thumbnail_background_mode_menu.set("선택 이미지 사용")
        self._on_thumbnail_control_changed()

    def _generate_thumbnail_background_with_ai(self) -> None:
        if self.thumbnail_ai_worker and self.thumbnail_ai_worker.is_alive():
            messagebox.showinfo("진행 중", "AI 썸네일 배경을 생성하는 중입니다.")
            return
        settings = self._read_wordpress_settings()
        if not settings.imagen_api_key:
            messagebox.showerror("Imagen API 필요", "환경설정에서 Imagen API 키를 먼저 입력해 주세요.")
            return

        title = self.thumbnail_prompt_preview.get("1.0", "end").strip()
        if not title or title.startswith("썸네일에 들어갈"):
            title = self.article_title_entry.get().strip() or self.generated_article_title or self._selected_or_manual_keyword()
        if not title:
            messagebox.showwarning("제목 필요", "썸네일 문구 또는 글 제목을 먼저 준비해 주세요.")
            return

        keyword = self._selected_or_manual_keyword() or title
        article_html = self._get_current_article_html() if hasattr(self, "article_editor") else ""
        self.wordpress_settings = settings
        AppStateStore.save(settings, save_secrets=False)
        self.thumbnail_ai_button.configure(state="disabled", text="AI 배경 생성 중...")
        self.publish_status_label.configure(
            text="Codex CLI가 썸네일 콘셉트를 설계하고 Imagen이 배경 이미지를 생성합니다.",
            text_color="#6dadff",
        )
        self.thumbnail_ai_worker = ThumbnailAIWorker(settings, title, keyword, article_html, self.result_queue)
        self.thumbnail_ai_worker.start()

    def _handle_thumbnail_ai_success(self, payload: dict) -> None:
        image_path = str(payload.get("image_path") or "")
        if not image_path:
            messagebox.showerror("AI 썸네일 실패", "생성된 이미지 경로를 찾지 못했습니다.")
            return
        self.thumbnail_background_image_path = image_path
        self.thumbnail_selected_image_label_text.set(Path(image_path).name)
        self.thumbnail_background_mode_menu.set("선택 이미지 사용")
        self.thumbnail_image_position_menu.set("가운데")
        self.thumbnail_image_scale_var.set(100)
        self.thumbnail_image_opacity_var.set(100)
        self._on_thumbnail_image_adjust_changed()
        self.thumbnail_ai_button.configure(state="normal", text="Codex+Imagen 배경 생성")
        self.publish_status_label.configure(
            text="Codex+Imagen 배경 이미지를 썸네일에 적용했습니다.",
            text_color="#48d980",
        )
        self._save_ui_state()

