    def _switch_page(self, page_name: str) -> None:
        if page_name not in self._page_frame_map():
            page_name = "writing"
        self.current_page = page_name
        palette = self._theme_palette() if hasattr(self, "_theme_palette") else {
            "accent": "#6dadff",
            "muted": "#9aa7bb",
            "selected": "#0f1724",
            "hover": "#111826",
        }
        nav_buttons = {
            "writing": self.writing_nav_button,
            "automation": self.automation_nav_button,
            "naver_blog": self.naver_blog_nav_button,
            "naver_kin": self.naver_kin_nav_button,
            "public_data": self.public_data_nav_button,
            "prompts": self.prompt_nav_button,
            "settings": self.settings_nav_button,
        }
        for name, button in nav_buttons.items():
            button.configure(
                text_color=palette["accent"] if name == page_name else palette["muted"],
                fg_color=palette["selected"] if name == page_name else "transparent",
                hover_color=palette["hover"],
            )
        if page_name == "automation":
            self._refresh_automation_queue()
        self._show_only_page_frame(page_name)
        if hasattr(self, "shell_frame"):
            self._finish_theme_paint()
            if self._normalize_app_theme(self.wordpress_settings.app_theme) == "화이트테마":
                self.after(120, self._finish_theme_paint)

    def _switch_settings_section(self, section_name: str) -> None:
        self.settings_section = section_name if section_name in {"basic", "theme", "ai"} else "ai"
        palette = self._theme_palette()
        if hasattr(self, "settings_theme_section_button"):
            for key, button in {
                "basic": self.settings_basic_section_button,
                "theme": self.settings_theme_section_button,
                "ai": self.settings_ai_section_button,
            }.items():
                button.configure(
                    fg_color=palette["selected"] if self.settings_section == key else "transparent",
                    text_color=palette["accent"] if self.settings_section == key else palette["muted"],
                    hover_color=palette["hover"],
                )
        if not hasattr(self, "theme_scroll") or not hasattr(self, "basic_scroll"):
            return
        self.basic_scroll.grid_remove()
        self.theme_scroll.grid_remove()
        self.settings_scroll.grid_remove()
        if self.settings_section in {"basic", "theme"}:
            self.settings_ai_tabs_header.grid_remove()
            self.settings_ai_track.grid_remove()
            self.settings_active_line.place_forget()
        else:
            self.settings_ai_tabs_header.grid()
            self.settings_ai_track.grid()
            self.settings_active_line.place(x=250, y=162)

        if self.settings_section == "basic":
            self.basic_scroll.grid(row=3, column=0, padx=28, pady=(20, 26), sticky="nsew")
            self._update_quick_status("기본설정", "프로그램 공통 설정을 저장합니다.", palette["accent"])
        elif self.settings_section == "theme":
            self.theme_scroll.grid(row=3, column=0, padx=28, pady=(20, 26), sticky="nsew")
            self._update_quick_status("테마 설정", "블랙/화이트 테마를 선택하고 자동 저장합니다.", palette["accent"])
        else:
            self.settings_scroll.grid(row=3, column=0, padx=28, pady=(20, 26), sticky="nsew")
        self._finish_theme_paint()

    def _switch_settings_tab(self, tab_name: str) -> None:
        self.active_platform = tab_name
        palette = self._theme_palette()
        card_map = {
            "wordpress": self.wp_card,
            "tistory": self.tistory_card,
            "blogspot": self.blogspot_card,
            "gpt": self.gpt_card,
            "gemini": self.gemini_card,
            "imagen": self.imagen_card,
            "codex": self.codex_card,
            "threads": self.threads_card,
        }
        if tab_name in card_map:
            card_map[tab_name].tkraise()

        self.wp_top_tab.configure(text_color=palette["accent"] if tab_name == "wordpress" else palette["muted"])
        self.tistory_top_tab.configure(text_color=palette["accent"] if tab_name == "tistory" else palette["muted"])
        self.gpt_top_tab.configure(text_color=palette["accent"] if tab_name == "gpt" else palette["muted"])
        self.gemini_top_tab.configure(text_color=palette["accent"] if tab_name == "gemini" else palette["muted"])
        self.imagen_top_tab.configure(text_color=palette["accent"] if tab_name == "imagen" else palette["muted"])
        self.codex_top_tab.configure(text_color=palette["accent"] if tab_name == "codex" else palette["muted"])
        self.blogspot_top_tab.configure(text_color=palette["accent"] if tab_name == "blogspot" else palette["muted"])
        self.threads_top_tab.configure(text_color=palette["accent"] if tab_name == "threads" else palette["muted"])

        if tab_name == "wordpress":
            self._update_quick_status("워드프레스 설정", "블로그 연결 정보와 카테고리를 저장합니다.", "#6dadff")
        elif tab_name == "tistory":
            self._update_quick_status("티스토리 설정", "글쓰기 화면을 열고 HTML 본문을 준비하는 화면 기반 연동입니다.", "#6dadff")
        elif tab_name == "gpt":
            self._update_quick_status("GPT API 설정", "OpenAI API 키와 기본 모델을 클라이언트에 저장합니다.", "#6dadff")
        elif tab_name == "gemini":
            self._update_quick_status("제미나이 API 설정", "Gemini API 키와 기본 모델을 클라이언트에 저장합니다.", "#6dadff")
        elif tab_name == "imagen":
            self._update_quick_status("Imagen API 설정", "본문 카드뉴스 이미지 생성 API 키를 클라이언트에 저장합니다.", "#6dadff")
        elif tab_name == "codex":
            self._update_quick_status("Codex CLI 설정", "썸네일 배경 이미지 프롬프트 설계에 Codex CLI를 사용합니다.", "#6dadff")
        elif tab_name == "blogspot":
            self._update_quick_status("블로그스팟 설정", "Blog ID와 Google OAuth Client 정보를 저장해 Blogger API를 연결합니다.", "#6dadff")
        elif tab_name == "threads":
            self._update_quick_status("Threads 설정", "Meta OAuth 인증과 Threads 사용자 연결 상태를 관리합니다.", "#6dadff")
        self._finish_theme_paint()

    def _on_gpt_model_changed(self, model_name: str) -> None:
        self.wordpress_settings.gpt_model = model_name

    def _on_gemini_model_changed(self, model_name: str) -> None:
        self.wordpress_settings.gemini_model = model_name

    def _on_imagen_model_changed(self, model_name: str) -> None:
        self.wordpress_settings.imagen_model = model_name
        self._save_ui_state()

    def _on_cardnews_count_changed(self, count_text: str) -> None:
        self.wordpress_settings.cardnews_count = self._safe_int(count_text, 2)
        self._save_ui_state()

    def _on_inline_images_count_changed(self, count_text: str) -> None:
        normalized = str(max(1, min(self._safe_int(count_text, 2), 4)))
        if hasattr(self, "inline_images_count_menu") and self.inline_images_count_menu.get() != normalized:
            self.inline_images_count_menu.set(normalized)
        if hasattr(self, "writing_inline_images_count_menu") and self.writing_inline_images_count_menu.get() != normalized:
            self.writing_inline_images_count_menu.set(normalized)
        self.wordpress_settings.inline_images_count = int(normalized)
        self._save_ui_state()

    def _on_inline_images_provider_changed(self, provider_name: str) -> None:
        provider = provider_name if provider_name in ("Imagen API", "Codex CLI + Imagen", "카드뉴스 생성") else "Imagen API"
        if hasattr(self, "inline_images_provider_menu") and self.inline_images_provider_menu.get() != provider:
            self.inline_images_provider_menu.set(provider)
        if hasattr(self, "writing_inline_images_provider_menu") and self.writing_inline_images_provider_menu.get() != provider:
            self.writing_inline_images_provider_menu.set(provider)
        self.wordpress_settings.inline_images_provider = provider
        self._save_ui_state()

    def _select_inline_images_provider(self, provider_name: str) -> None:
        if not self.inline_images_enabled_var.get():
            self.inline_images_enabled_var.set(True)
        self._on_inline_images_provider_changed(provider_name)
        if hasattr(self, "article_progress_label"):
            self.article_progress_label.configure(
                text=f"이미지 삽입 방식이 '{provider_name}'으로 설정되었습니다."
            )

    def _on_codex_speed_changed(self, speed_name: str) -> None:
        presets = {
            "기본": "--skip-git-repo-check",
            "빠름": "--skip-git-repo-check -c model_reasoning_effort=low -c service_tier=fast",
            "고품질": "--skip-git-repo-check -c model_reasoning_effort=medium",
        }
        if hasattr(self, "codex_extra_args_entry"):
            self.codex_extra_args_entry.delete(0, "end")
            self.codex_extra_args_entry.insert(0, presets.get(speed_name, presets["기본"]))
        self._sync_codex_display_name()

    def _sync_codex_display_name(self) -> None:
        if not hasattr(self, "codex_display_name_entry"):
            return
        model = self.codex_cli_model_entry.get().strip() if hasattr(self, "codex_cli_model_entry") else ""
        speed = self.codex_speed_menu.get() if hasattr(self, "codex_speed_menu") else "기본"
        label = "[CLI] Codex"
        if model:
            label += f" · {model}"
        if speed and speed != "기본":
            label += f" · {speed}"
        self.codex_display_name_entry.delete(0, "end")
        self.codex_display_name_entry.insert(0, label)
        self._save_ui_state()

    def _on_ai_provider_changed(self, provider_name: str) -> None:
        self.wordpress_settings.preferred_ai_provider = provider_name
        self._save_ui_state()

    def _category_names(self) -> list[str]:
        names = [item.get("name", "이름 없음") for item in self.wordpress_settings.categories if item.get("name")]
        return names or ["카테고리 없음"]

    def _refresh_category_checkboxes(self) -> None:
        if not hasattr(self, "category_checkbox_frame"):
            return
        for widget in self.category_checkbox_frame.winfo_children():
            widget.destroy()
        self.category_vars = {}

        selected_ids = set(self.wordpress_settings.category_ids or ([] if self.wordpress_settings.category_id is None else [self.wordpress_settings.category_id]))
        if not self.wordpress_settings.categories:
            empty_label = ctk.CTkLabel(
                self.category_checkbox_frame,
                text="카테고리 목록이 없습니다. 먼저 검사 버튼으로 불러와 주세요.",
                text_color="#9aa7bb",
                font=ctk.CTkFont(size=13),
            )
            empty_label.grid(row=0, column=0, padx=12, pady=10, sticky="w")
            self._finish_theme_paint()
            return

        for index, item in enumerate(self.wordpress_settings.categories):
            category_id = item.get("id")
            category_name = item.get("name", "이름 없음")
            if not category_id:
                continue
            variable = ctk.BooleanVar(value=category_id in selected_ids)
            self.category_vars[int(category_id)] = variable
            checkbox = ctk.CTkCheckBox(
                self.category_checkbox_frame,
                text=category_name,
                variable=variable,
                onvalue=True,
                offvalue=False,
                checkbox_width=20,
                checkbox_height=20,
                corner_radius=6,
                font=ctk.CTkFont(size=14, weight="bold"),
                command=self._on_multi_categories_changed,
            )
            checkbox.grid(row=index, column=0, padx=12, pady=8, sticky="w")
        self._finish_theme_paint()

    def _on_category_changed(self, category_name: str) -> None:
        self.wordpress_settings.category_name = category_name
        selected = next(
            (item for item in self.wordpress_settings.categories if item.get("name") == category_name),
            None,
        )
        self.wordpress_settings.category_id = selected.get("id") if selected else None
        if self.wordpress_settings.category_id:
            current_ids = set(self.wordpress_settings.category_ids)
            current_ids.add(int(self.wordpress_settings.category_id))
            self.wordpress_settings.category_ids = sorted(current_ids)
            self.wordpress_settings.category_names = [
                item.get("name", "이름 없음")
                for item in self.wordpress_settings.categories
                if item.get("id") in current_ids
            ]
            self._refresh_category_checkboxes()
        self._save_ui_state()

    def _on_multi_categories_changed(self) -> None:
        selected_ids = [category_id for category_id, variable in self.category_vars.items() if variable.get()]
        self.wordpress_settings.category_ids = selected_ids
        self.wordpress_settings.category_names = [
            item.get("name", "이름 없음")
            for item in self.wordpress_settings.categories
            if item.get("id") in selected_ids
        ]
        if self.wordpress_settings.category_id and self.wordpress_settings.category_id not in selected_ids:
            self.wordpress_settings.category_id = selected_ids[0] if selected_ids else None
            matching_name = next(
                (item.get("name", "카테고리 없음") for item in self.wordpress_settings.categories if item.get("id") == self.wordpress_settings.category_id),
                "카테고리 없음",
            )
            self.wordpress_settings.category_name = matching_name if self.wordpress_settings.category_id else "카테고리 없음"
            self.category_menu.set(self.wordpress_settings.category_name)
        self._save_ui_state()

    def _on_post_mode_changed(self, post_mode: str) -> None:
        self.wordpress_settings.post_mode = post_mode
        self._save_ui_state()

    def _toggle_password_visibility(self) -> None:
        self.password_visible = not self.password_visible
        self.password_entry.configure(show="" if self.password_visible else "*")

    def _toggle_gpt_visibility(self) -> None:
        self.gpt_password_visible = not self.gpt_password_visible
        self.gpt_secret_entry.configure(show="" if self.gpt_password_visible else "*")

    def _toggle_gemini_visibility(self) -> None:
        self.gemini_password_visible = not self.gemini_password_visible
        self.gemini_secret_entry.configure(show="" if self.gemini_password_visible else "*")

    def _toggle_imagen_visibility(self) -> None:
        self.imagen_password_visible = not self.imagen_password_visible
        self.imagen_secret_entry.configure(show="" if self.imagen_password_visible else "*")

    def _toggle_threads_token_visibility(self) -> None:
        self.threads_token_visible = not getattr(self, "threads_token_visible", False)
        self.threads_access_token_entry.configure(show="" if self.threads_token_visible else "*")

    def _save_ui_state(self) -> None:
        if self._ui_state_save_job is not None:
            self.after_cancel(self._ui_state_save_job)
        self._ui_state_save_job = self.after(1600, self._save_ui_state_now)

    def _save_ui_state_now(self) -> None:
        self._ui_state_save_job = None
        if self._defer_while_text_composing("_ui_state_save_job", self._save_ui_state_now, 1.5):
            return
        try:
            if hasattr(self, "reference_textbox"):
                self._update_reference_count()
            settings = self._read_wordpress_settings(include_prompts=False)
        except Exception:
            return
        self.wordpress_settings = settings
        AppStateStore.save(settings, save_secrets=False)

    def _on_reference_text_changed(self, _event=None) -> None:
        self._mark_text_input_activity(_event)
        self._schedule_reference_count_update()
        self._save_ui_state()

    def _schedule_reference_count_update(self) -> None:
        if self._reference_count_job is not None:
            self.after_cancel(self._reference_count_job)
        self._reference_count_job = self.after(700, self._run_reference_count_update)

    def _run_reference_count_update(self) -> None:
        self._reference_count_job = None
        if self._defer_while_text_composing("_reference_count_job", self._run_reference_count_update, 1.0):
            return
        self._update_reference_count()

    def _on_benchmark_mode_changed(self, save: bool = True) -> None:
        enabled = bool(self.benchmark_mode_var.get())
        if hasattr(self, "topic_entry"):
            self.topic_entry.configure(state="disabled" if enabled else "normal")
        if hasattr(self, "benchmark_url_entry"):
            self.benchmark_url_entry.configure(state="normal" if enabled else "disabled")
        if hasattr(self, "benchmark_button"):
            self.benchmark_button.configure(state="normal" if enabled else "disabled")
        if hasattr(self, "find_keywords_button"):
            self.find_keywords_button.configure(state="disabled" if enabled else "normal")
        if save:
            self._save_ui_state()

    def _on_prompt_text_changed(self, _event=None) -> None:
        self._mark_text_input_activity(_event)
        if self._prompt_feedback_job is not None:
            self.after_cancel(self._prompt_feedback_job)
        self._prompt_feedback_job = self.after(500, self._run_prompt_feedback_update)

    def _run_prompt_feedback_update(self) -> None:
        self._prompt_feedback_job = None
        if hasattr(self, "prompt_feedback_label"):
            self.prompt_feedback_label.configure(text="수정 중 - 저장 버튼을 누르면 반영됩니다.", text_color="#f4c95d")

    def _update_reference_count(self) -> None:
        if not hasattr(self, "reference_count_label"):
            return
        count = len(self.reference_textbox.get("1.0", "end").strip())
        self.reference_count_label.configure(text=f"{count:,}자")

    def _add_link_row(self, link: dict | None = None) -> None:
        if not hasattr(self, "link_list_frame"):
            return
        if len(self.link_rows) >= 5:
            messagebox.showinfo("링크 추가 제한", "본문 링크 버튼은 최대 5개까지 추가할 수 있습니다.")
            return

        link = link or {}
        row_frame = ctk.CTkFrame(self.link_list_frame, fg_color="#111826", corner_radius=14)
        row_frame.grid(row=len(self.link_rows), column=0, pady=(0, 8), sticky="ew")
        row_frame.grid_columnconfigure(0, weight=1)
        row_frame.grid_columnconfigure(1, weight=2)
        row_frame.grid_columnconfigure(2, weight=0)
        row_frame.grid_columnconfigure(3, weight=0)
        row_frame.grid_columnconfigure(4, weight=0)
        row_frame.grid_columnconfigure(5, weight=0)

        button_entry = ctk.CTkEntry(
            row_frame,
            height=40,
            corner_radius=12,
            fg_color="#0b1220",
            border_width=0,
            placeholder_text="버튼명",
            font=ctk.CTkFont(size=13, weight="bold"),
        )
        button_entry.grid(row=0, column=0, padx=(10, 8), pady=10, sticky="ew")
        button_entry.insert(0, str(link.get("button_text", "")))
        button_entry.bind("<KeyRelease>", lambda _event: self._save_ui_state())

        url_entry = ctk.CTkEntry(
            row_frame,
            height=40,
            corner_radius=12,
            fg_color="#0b1220",
            border_width=0,
            placeholder_text="URL",
            font=ctk.CTkFont(size=13, weight="bold"),
        )
        url_entry.grid(row=0, column=1, padx=(0, 8), pady=10, sticky="ew")
        url_entry.insert(0, str(link.get("url", "")))
        url_entry.bind("<KeyRelease>", lambda _event: self._save_ui_state())

        position = str(link.get("position", "본문하단"))
        if position not in LINK_POSITION_OPTIONS:
            position = "본문하단"
        width_entry = ctk.CTkEntry(
            row_frame,
            height=40,
            width=88,
            corner_radius=12,
            fg_color="#0b1220",
            border_width=0,
            placeholder_text="크기",
            font=ctk.CTkFont(size=13, weight="bold"),
        )
        width_entry.grid(row=0, column=2, padx=(0, 8), pady=10, sticky="e")
        width_entry.insert(0, str(link.get("width", "")))
        width_entry.bind("<KeyRelease>", lambda _event: self._save_ui_state())

        full_width_var = ctk.BooleanVar(value=bool(link.get("full_width", False)))
        full_width_checkbox = ctk.CTkCheckBox(
            row_frame,
            text="100%",
            variable=full_width_var,
            onvalue=True,
            offvalue=False,
            checkbox_width=18,
            checkbox_height=18,
            corner_radius=5,
            width=68,
            font=ctk.CTkFont(size=13, weight="bold"),
            command=self._save_ui_state,
        )
        full_width_checkbox.grid(row=0, column=3, padx=(0, 8), pady=10, sticky="e")

        position_menu = ctk.CTkOptionMenu(
            row_frame,
            values=LINK_POSITION_OPTIONS,
            width=112,
            height=40,
            corner_radius=12,
            fg_color="#243247",
            button_color="#31445f",
            button_hover_color="#3b5170",
            font=ctk.CTkFont(size=13, weight="bold"),
            command=lambda _value: self._save_ui_state(),
        )
        position_menu.grid(row=0, column=4, padx=(0, 8), pady=10, sticky="e")
        position_menu.set(position)

        row_data: dict = {
            "frame": row_frame,
            "button_entry": button_entry,
            "url_entry": url_entry,
            "width_entry": width_entry,
            "full_width_var": full_width_var,
            "position_menu": position_menu,
        }
        delete_button = ctk.CTkButton(
            row_frame,
            text="삭제",
            width=64,
            height=40,
            corner_radius=12,
            fg_color="#596579",
            hover_color="#6a768b",
            font=ctk.CTkFont(size=13, weight="bold"),
            command=lambda data=row_data: self._remove_link_row(data),
        )
        delete_button.grid(row=0, column=5, padx=(0, 10), pady=10, sticky="e")
        row_data["delete_button"] = delete_button
        self.link_rows.append(row_data)
        self._update_add_link_button_state()
        self._save_ui_state()

    def _remove_link_row(self, row_data: dict) -> None:
        if row_data not in self.link_rows:
            return
        row_data["frame"].destroy()
        self.link_rows.remove(row_data)
        self._regrid_link_rows()
        self._update_add_link_button_state()
        self._save_ui_state()

    def _regrid_link_rows(self) -> None:
        for index, row_data in enumerate(self.link_rows):
            row_data["frame"].grid_configure(row=index)

    def _update_add_link_button_state(self) -> None:
        if hasattr(self, "add_link_button"):
            self.add_link_button.configure(state="disabled" if len(self.link_rows) >= 5 else "normal")

    def _load_link_rows(self, links: list[dict]) -> None:
        if not hasattr(self, "link_list_frame"):
            return
        for row_data in list(self.link_rows):
            row_data["frame"].destroy()
        self.link_rows = []
        for link in (links or [])[:5]:
            if str(link.get("button_text", "")).strip() or str(link.get("url", "")).strip():
                self._add_link_row(link)
        self._update_add_link_button_state()

    def _current_writing_links(self) -> list[dict]:
        links: list[dict] = []
        if not hasattr(self, "link_rows"):
            return list(self.wordpress_settings.writing_links or [])
        for row_data in self.link_rows:
            button_text = row_data["button_entry"].get().strip()
            url = row_data["url_entry"].get().strip()
            width = row_data["width_entry"].get().strip()
            full_width = bool(row_data["full_width_var"].get())
            position = row_data["position_menu"].get()
            if not button_text and not url and not width and not full_width:
                continue
            links.append(
                {
                    "button_text": button_text,
                    "url": url,
                    "width": width,
                    "full_width": full_width,
                    "position": position if position in LINK_POSITION_OPTIONS else "본문하단",
                }
            )
        return links[:5]

    def _read_wordpress_settings(self, include_prompts: bool = True) -> WordPressSettings:
        wordpress_title_prompt_template = self.wordpress_settings.wordpress_title_prompt_template
        wordpress_article_prompt_template = self.wordpress_settings.wordpress_article_prompt_template
        tistory_title_prompt_template = self.wordpress_settings.tistory_title_prompt_template
        tistory_article_prompt_template = self.wordpress_settings.tistory_article_prompt_template
        tistory_automation_prompt = self.wordpress_settings.tistory_automation_prompt
        naver_kin_answer_prompt = self.wordpress_settings.naver_kin_answer_prompt
        blogspot_title_prompt_template = self.wordpress_settings.blogspot_title_prompt_template
        blogspot_article_prompt_template = self.wordpress_settings.blogspot_article_prompt_template
        if include_prompts and hasattr(self, "prompt_title_boxes"):
            prompt_values = self._platform_prompt_values_from_boxes()
            prompt_sets = PromptFileStore.normalize_prompt_sets(self.wordpress_settings.prompt_sets, self.wordpress_settings)
            wordpress_title_prompt_template = nonempty_text(prompt_values["wordpress_title_prompt_template"], DEFAULT_WORDPRESS_TITLE_PROMPT)
            wordpress_article_prompt_template = nonempty_text(prompt_values["wordpress_article_prompt_template"], DEFAULT_WORDPRESS_ARTICLE_PROMPT)
            tistory_title_prompt_template = nonempty_text(prompt_values["tistory_title_prompt_template"], DEFAULT_TISTORY_TITLE_PROMPT)
            tistory_article_prompt_template = nonempty_text(prompt_values["tistory_article_prompt_template"], DEFAULT_TISTORY_ARTICLE_PROMPT)
