    def _blogspot_oauth_scopes(self, include_indexing: bool = False) -> list[str]:
        scopes = ["https://www.googleapis.com/auth/blogger"]
        if include_indexing:
            scopes.append("https://www.googleapis.com/auth/indexing")
        return scopes

    def _open_blogspot_auth(self, include_indexing: bool = False) -> None:
        settings = self._read_wordpress_settings(include_prompts=False)
        if not settings.blogspot_client_id or not settings.blogspot_client_secret:
            messagebox.showerror("입력 오류", "Client ID와 Client Secret을 먼저 입력하고 저장해 주세요.")
            return
        self.wordpress_settings = settings
        AppStateStore.save(settings)
        auth_url = "https://accounts.google.com/o/oauth2/v2/auth?" + urlencode(
            {
                "client_id": settings.blogspot_client_id,
                "redirect_uri": settings.blogspot_redirect_uri or "http://localhost",
                "response_type": "code",
                "scope": " ".join(self._blogspot_oauth_scopes(include_indexing)),
                "access_type": "offline",
                "prompt": "consent",
            }
        )
        webbrowser.open(auth_url, new=2)
        self.blogspot_status_label.configure(text="● Google 인증 화면을 열었습니다. code를 복사해 붙여넣어 주세요.", text_color="#6dadff")
        self._update_quick_status("블로그스팟 인증", "브라우저에서 승인 후 URL의 code 값을 인증 코드에 붙여넣어 주세요.", "#6dadff")

    def _complete_blogspot_auth(self) -> None:
        settings = self._read_wordpress_settings(include_prompts=False)
        code = self.blogspot_auth_code_entry.get().strip()
        if not settings.blogspot_client_id or not settings.blogspot_client_secret:
            messagebox.showerror("입력 오류", "Client ID와 Client Secret을 먼저 입력해 주세요.")
            return
        if not code:
            messagebox.showerror("입력 오류", "Google 인증 후 발급된 code를 인증 코드 칸에 붙여넣어 주세요.")
            return
        code = self._extract_google_auth_code(code)
        try:
            token_payload = self._exchange_blogspot_auth_code(
                settings.blogspot_client_id,
                settings.blogspot_client_secret,
                code,
                settings.blogspot_redirect_uri or "http://localhost",
            )
        except RuntimeError as exc:
            messagebox.showerror("블로그스팟 인증 실패", str(exc))
            self.blogspot_status_label.configure(text="● 인증 실패", text_color="#ff6b6b")
            return
        refresh_token = str(token_payload.get("refresh_token") or settings.blogspot_refresh_token or "").strip()
        access_token = str(token_payload.get("access_token") or "").strip()
        if not refresh_token and not access_token:
            messagebox.showerror("블로그스팟 인증 실패", "Google 응답에 토큰이 없습니다. 다시 인증해 주세요.")
            return
        settings.blogspot_refresh_token = refresh_token
        settings.blogspot_access_token = access_token
        self.wordpress_settings = settings
        AppStateStore.save(settings)
        self.blogspot_auth_code_entry.delete(0, "end")
        status = "● 인증 완료"
        if refresh_token:
            status += " (자동 갱신 가능)"
        self.blogspot_status_label.configure(text=status, text_color="#48d980")
        self._update_quick_status("블로그스팟 인증 완료", "Blogger API OAuth 토큰을 저장했습니다.", "#48d980")

    def _extract_google_auth_code(self, code_or_url: str) -> str:
        text = code_or_url.strip()
        if "code=" not in text:
            return text
        parsed = urlparse(text)
        for part in parsed.query.split("&"):
            if part.startswith("code="):
                return unquote(part.split("=", 1)[1])
        return text

    def _exchange_blogspot_auth_code(self, client_id: str, client_secret: str, code: str, redirect_uri: str) -> dict:
        data = urlencode(
            {
                "client_id": client_id,
                "client_secret": client_secret,
                "code": code,
                "grant_type": "authorization_code",
                "redirect_uri": redirect_uri or "http://localhost",
            }
        ).encode("utf-8")
        request = Request(
            "https://oauth2.googleapis.com/token",
            data=data,
            method="POST",
            headers={
                "Content-Type": "application/x-www-form-urlencoded; charset=utf-8",
                "User-Agent": "BlogHelper/1.0",
            },
        )
        try:
            with urlopen(request, timeout=20, context=ssl.create_default_context(cafile=certifi.where())) as response:
                return json.loads(response.read().decode("utf-8"))
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="ignore")
            raise RuntimeError(f"Google OAuth 토큰 발급 실패 ({exc.code}): {detail[:300]}") from exc
        except URLError as exc:
            raise RuntimeError(f"Google OAuth 서버에 연결할 수 없습니다: {exc.reason}") from exc

    def _revoke_blogspot_auth(self) -> None:
        token = self.wordpress_settings.blogspot_refresh_token or self.wordpress_settings.blogspot_access_token
        if token:
            data = urlencode({"token": token}).encode("utf-8")
            request = Request(
                "https://oauth2.googleapis.com/revoke",
                data=data,
                method="POST",
                headers={"Content-Type": "application/x-www-form-urlencoded; charset=utf-8"},
            )
            try:
                with urlopen(request, timeout=10, context=ssl.create_default_context(cafile=certifi.where())):
                    pass
            except Exception:
                pass
        self.wordpress_settings.blogspot_refresh_token = ""
        self.wordpress_settings.blogspot_access_token = ""
        AppStateStore.save(self.wordpress_settings)
        KeychainStore.delete_secret(KEYCHAIN_BLOGSPOT_REFRESH_TOKEN)
        KeychainStore.delete_secret(KEYCHAIN_BLOGSPOT_ACCOUNT)
        self.blogspot_status_label.configure(text="● 블로그스팟 인증 해제 완료", text_color="#9aa7bb")
        self._update_quick_status("블로그스팟 인증 해제", "저장된 Google OAuth 토큰을 삭제했습니다.", "#9aa7bb")

